// ===================================================================================
// 📊 ESTADÍSTICAS DE PQRSF y bandeja de lo que falta por responder
// ===================================================================================
// Todo viene agregado del servidor (sql/90): la pantalla no baja las 2.589 PQRSF, pide el
// resumen del periodo. El CUMPLIMIENTO que se muestra se calcula con las fechas —radicado,
// fecha límite y fecha de respuesta— y no con la columna de la hoja, que se contradice
// consigo misma (hay filas marcadas CUMPLIO que a la vez dicen SIN RESPUESTA).
const PQS_BLOQUES = [
  { key: 'resumen', icon: '📊', label: 'Resumen' },
  { key: 'cumplimiento', icon: '⏱️', label: 'Cumplimiento y tiempos' },
  { key: 'motivos', icon: '💬', label: 'Motivos y canales' },
  { key: 'vehiculos', icon: '🚌', label: 'Vehículos y rutas' },
  { key: 'pendientes', icon: '📥', label: 'Falta por responder' },
];
const _pqs = { res: null, pend: null, bloque: 'resumen', filtro: '' };

function pqsPeriodo() {
  const anio = $('pqs-anio')?.value || '';
  const mes = anio ? ($('pqs-mes')?.value || '') : '';
  if (anio && mes) {
    const fin = new Date(Number(anio), Number(mes), 0);   // día 0 del mes siguiente
    return [`${anio}-${mes}-01`, `${anio}-${mes}-${String(fin.getDate()).padStart(2, '0')}`];
  }
  if (anio) return [`${anio}-01-01`, `${anio}-12-31`];
  return [null, null];   // todo el histórico
}
function pqsPeriodoTxt() {
  const anio = $('pqs-anio')?.value || '';
  const mes = anio ? ($('pqs-mes')?.value || '') : '';
  if (anio && mes) return `${PST_MESES[Number(mes) - 1]} de ${anio}`;
  return anio ? `Año ${anio}` : 'Todo el histórico';
}

async function openPqrsfStats(bloque) {
  if (!puedeVerPqrsf()) return;
  _pqs.bloque = bloque || 'resumen';
  currentView = 'pqrstats';
  statsPrepararVista();
  $('pst-fl-perfil').hidden = true; $('pst-fl-sin').hidden = true; $('pst-fl-pqr').hidden = false;
  $('nav-pqs-' + _pqs.bloque)?.classList.add('active');
  buildBottomNav();
  const b = PQS_BLOQUES.find((x) => x.key === _pqs.bloque) || PQS_BLOQUES[0];
  const tit = $('pst-title'); if (tit) tit.textContent = `📣 PQRSF · ${b.label}`;
  if (!_pqs.res) await cargarPqrsfStats(); else renderPqrsfStats();
}

async function cargarPqrsfStats() {
  const body = $('pst-body');
  body.innerHTML = '<div class="loading">Leyendo las PQRSF…</div>';
  const [desde, hasta] = pqsPeriodo();
  try {
    const [r1, r2] = await Promise.all([
      sb.rpc('pqrsf_resumen', { p_desde: desde, p_hasta: hasta }),
      sb.rpc('pqrsf_pendientes', { p_limite: 500 }),
    ]);
    if (r1.error) throw r1.error;
    _pqs.res = r1.data; _pqs.pend = r2.error ? null : r2.data;
    pqsLlenarAnios();
    renderPqrsfStats();
  } catch (e) {
    const txt = String(e.message || e);
    body.innerHTML = '';
    body.appendChild(pstEl('div', 'cump-empty', 'No se pudieron leer las PQRSF: ' + txt
      + (/pqrsf_resumen|pqrsf_pendientes/.test(txt) ? ' — falta ejecutar sql/90.' : '')));
  }
}

// Los años salen de lo que hay cargado; el mes solo se habilita con un año elegido
function pqsLlenarAnios() {
  const selA = $('pqs-anio'), selM = $('pqs-mes');
  if (selA && selA.options.length <= 1) {
    const k = _pqs.res?.kpi || {};
    const a1 = Number(String(k.desde || '').slice(0, 4)) || new Date().getFullYear();
    const a2 = Number(String(k.hasta || '').slice(0, 4)) || new Date().getFullYear();
    for (let a = a2; a >= a1; a--) {
      selA.appendChild(Object.assign(document.createElement('option'), { value: String(a), textContent: String(a) }));
    }
  }
  if (selM && selM.options.length <= 1) {
    PST_MESES.forEach((m, i) => selM.appendChild(Object.assign(document.createElement('option'),
      { value: String(i + 1).padStart(2, '0'), textContent: m })));
  }
  if (selM) { selM.disabled = !(selA && selA.value); if (selA && !selA.value) selM.value = ''; }
}

const pqsBarras = (items) => ({ items, sin: 0, total: items.reduce((s, i) => s + i.n, 0) });
const pqsItems = (arr, etiqueta) => (arr || []).map((x) => ({
  k: etiqueta ? etiqueta(x) : String(x.k), n: Number(x.n || 0),
}));

function renderPqrsfStats() {
  const body = $('pst-body'); if (!_pqs.res) return;
  const R = _pqs.res;
  _pst.tablas = [];
  _pqs.filtro = pqsPeriodoTxt();
  _pst.filtro = _pqs.filtro;
  $('pst-sub').textContent = _pqs.filtro;
  const bAct = PQS_BLOQUES.find((x) => x.key === _pqs.bloque) || PQS_BLOQUES[0];
  const tit = $('pst-title'); if (tit) tit.textContent = `📣 PQRSF · ${bAct.label}`;
  body.innerHTML = '';

  const tabs = pstEl('div', 'pst-tabs');
  PQS_BLOQUES.forEach((b) => {
    const t = pstEl('button', 'pst-tab' + (b.key === _pqs.bloque ? ' on' : ''), `${b.icon} ${b.label}`);
    t.type = 'button';
    t.onclick = () => { _pqs.bloque = b.key; renderPqrsfStats(); };
    tabs.appendChild(t);
  });
  body.appendChild(tabs);

  const B = _pqs.bloque;
  if (B === 'pendientes') { pqsPendientes(body); return; }

  const k = R.kpi || {};
  if (!Number(k.total || 0)) {
    body.appendChild(pstEl('div', 'cump-empty', 'No hay PQRSF en este periodo.'));
    return;
  }
  const tot = Number(k.total || 0);
  const respondidas = Number(k.a_tiempo || 0) + Number(k.tarde || 0);

  // ---- Indicadores ----
  const kpis = pstEl('div', 'pst-kpis');
  kpis.append(
    pstTile('PQRSF', pstNum(tot),
      k.desde ? `del ${fechaLegible(k.desde)} al ${fechaLegible(k.hasta)}` : '', true),
    pstTile('Respondidas a tiempo', `${pstPct(k.a_tiempo, respondidas)}%`,
      `${pstNum(k.a_tiempo)} de ${pstNum(respondidas)} respondidas`),
    pstTile('Fuera de plazo', pstNum(k.tarde), `${pstPct(k.tarde, respondidas)}% de las respondidas`),
    pstTile('Sin respuesta', pstNum(k.sin_resp), `${pstPct(k.sin_resp, tot)}% del total`),
    pstTile('Días en responder', k.dias_prom == null ? '—' : String(k.dias_prom),
      k.dias_medio == null ? 'promedio' : `promedio · la mitad en ${k.dias_medio} día(s) o menos`),
    pstTile('Quejas', pstNum(k.quejas), `${pstNum(k.felicitaciones)} felicitación(es) · ${pstNum(k.con_proceso)} con proceso`),
  );
  body.appendChild(kpis);

  const seccion = (titulo) => { body.appendChild(pstEl('h3', 'pst-sec', titulo)); const g = pstEl('div', 'pst-grid'); body.appendChild(g); return g; };
  const ver = (x) => B === 'resumen' || B === x;
  let g;

  if (ver('resumen')) {
    g = seccion('📊 El panorama');
    g.appendChild(pstBarras('Por tipo', pqsBarras(pqsItems(R.por_tipo))));
    g.appendChild(pstBarras('Cumplimiento', pqsBarras([
      { k: 'A tiempo', n: Number(k.a_tiempo || 0) },
      { k: 'Fuera de plazo', n: Number(k.tarde || 0) },
      { k: 'Sin respuesta', n: Number(k.sin_resp || 0) },
    ]), { nota: 'Calculado con las fechas, no con la columna de la hoja.' }));
    const meses = pqsItems(R.por_mes, (x) => {
      const a = String(x.k).slice(0, 4), m = Number(String(x.k).slice(5, 7));
      return `${PST_MESES[m - 1] || x.k} ${a}`;
    });
    if (meses.length) g.appendChild(pstBarras('Cuántas llegan cada mes', pqsBarras(meses), { ancha: true }));
  }

  if (ver('cumplimiento')) {
    g = seccion('⏱️ Cumplimiento y tiempos');
    g.appendChild(pstBarras('Cuánto se demoran en responder', pqsBarras(pqsItems(R.demora)),
      { nota: 'Días entre el radicado y la respuesta del área.' }));
    const areas = R.por_area || [];
    if (areas.length) {
      g.appendChild(sstTarjetaTabla('Cumplimiento por área de destino',
        'Con cuántas responde a tiempo cada área y cuánto se demora en promedio.',
        { cab: ['Área', 'PQRSF', 'A tiempo', '% a tiempo', 'Fuera de plazo', 'Sin respuesta', 'Días promedio'],
          filas: areas.map((a) => [a.k, Number(a.n || 0), Number(a.a_tiempo || 0),
            `${pstPct(a.a_tiempo, Number(a.a_tiempo || 0) + Number(a.tarde || 0))}%`,
            Number(a.tarde || 0), Number(a.sin_resp || 0), a.dias_prom == null ? '—' : String(a.dias_prom)]) }));
    }
    const meses = R.por_mes || [];
    if (meses.length) {
      g.appendChild(sstTarjetaTabla('Cumplimiento mes a mes',
        'Si el porcentaje a tiempo sube, el proceso está mejorando.',
        { cab: ['Mes', 'PQRSF', 'A tiempo', 'Fuera de plazo', 'Sin respuesta', '% a tiempo'],
          filas: meses.map((m) => {
            const a = String(m.k).slice(0, 4), mm = Number(String(m.k).slice(5, 7));
            const resp = Number(m.a_tiempo || 0) + Number(m.tarde || 0);
            return [`${PST_MESES[mm - 1] || m.k} ${a}`, Number(m.n || 0), Number(m.a_tiempo || 0),
              Number(m.tarde || 0), Number(m.sin_resp || 0), `${pstPct(m.a_tiempo, resp)}%`];
          }) }));
    }
  }

  if (ver('motivos')) {
    g = seccion('💬 Por qué se quejan y por dónde llegan');
    g.appendChild(pstBarras('Motivo', pqsBarras(pqsItems(R.por_motivo)), { ancha: true }));
    g.appendChild(pstBarras('Medio por el que llega', pqsBarras(pqsItems(R.por_medio))));
    const dias = (R.por_dia || []).map((d) => ({
      k: (PST_DIAS[Number(d.k)] || '').replace(/^./, (c) => c.toUpperCase()), n: Number(d.n || 0),
    }));
    if (dias.length) g.appendChild(pstBarras('Día en que se radican', pqsBarras(dias)));
  }

  if (ver('vehiculos')) {
    g = seccion('🚌 Vehículos y rutas');
    g.appendChild(pstBarras('Rutas con más PQRSF', pqsBarras(pqsItems(R.por_ruta)), { ancha: true }));
    const mv = R.por_movil || [];
    if (mv.length) {
      g.appendChild(sstTarjetaTabla('Vehículos con más PQRSF',
        'Los 25 móviles más mencionados. "Con proceso" son las que terminaron en descargos al conductor.',
        { cab: ['Móvil', 'PQRSF', 'Quejas', 'Con proceso', 'Última'],
          filas: mv.map((v) => [v.k, Number(v.n || 0), Number(v.quejas || 0), Number(v.con_proceso || 0),
            v.ultimo ? fechaLegible(v.ultimo) : '—']) }));
    }
  }
}

// ---- 📥 Lo que falta por responder ----
// Son dos trabajos distintos y por eso van en dos listas: lo que nadie ha contestado (hay que
// redactar una respuesta) y lo que YA tiene respuesta pero sigue marcado abierto (solo hay que
// revisarlo y cerrarlo). Mezclados, el área ve un número grande y no sabe por dónde empezar.
function pqsPendientes(body) {
  const P = _pqs.pend;
  if (!P || !P.ok) {
    body.appendChild(pstEl('div', 'cump-empty', 'No se pudo leer la bandeja de pendientes.'));
    return;
  }
  const sin = P.items || [];
  const cer = P.cerrar || [];
  const nSin = Number(P.sin_responder != null ? P.sin_responder : sin.length);
  const nCer = Number(P.falta_cerrar != null ? P.falta_cerrar : cer.length);
  const dosListas = P.cerrar != null; // false mientras no se haya aplicado sql/92

  const kpis = pstEl('div', 'pst-kpis');
  kpis.append(
    pstTile('Sin responder', pstNum(nSin), 'nadie le ha contestado al usuario', true),
    pstTile('De esas, vencidas', pstNum(P.vencidas), 'ya pasaron de la fecha límite'),
    pstTile('Falta cerrar', pstNum(nCer), 'ya respondidas, pero siguen abiertas'),
  );
  body.appendChild(kpis);

  // ---- 1) Sin responder: lo urgente de verdad ----
  body.appendChild(pstEl('h3', 'pst-sec', '✍️ Sin responder'));
  if (!sin.length) {
    body.appendChild(pstEl('div', 'cump-empty', 'No hay PQRSF sin responder. 👏'));
  } else {
    const cab = ['Atraso', 'Radicado', 'Fecha', 'Límite', 'Tipo', 'Motivo', 'Móvil', 'Ruta', 'Área de destino', 'Estado'];
    const filas = sin.map((p) => {
      const a = p.atraso == null ? null : Number(p.atraso);
      return [a == null ? 'sin plazo' : (a > 0 ? `${a} día(s)` : 'a tiempo'),
        p.radicado || '—', p.fecha_radicado ? fechaLegible(p.fecha_radicado) : '—',
        p.fecha_limite ? fechaLegible(p.fecha_limite) : '—', p.tipo || '—', p.motivo || '—',
        p.numero_interno || '—', p.ruta || '—', p.responsable_destino || '—', p.estado || '—'];
    });
    body.appendChild(pqsTablaBandeja(
      `Sin responder (${pstNum(sin.length)}${sin.length < nSin ? ' de ' + pstNum(nSin) : ''})`,
      'Toca una fila para abrir el radicado y responder. Los días en rojo son de atraso sobre la fecha límite.',
      cab, filas, sin, (p, i) => i === 0 && Number(p.atraso) > 0 ? 'evb-alta' : null));
    _pst.tablas.push({ titulo: 'PQRSF sin responder', nota: `Al ${fechaLegible(P.hoy)}`, cab, filas });
  }

  // ---- 2) Respondidas que nadie cerró ----
  if (!dosListas) return; // base sin sql/92: la lista de arriba ya trae todo
  body.appendChild(pstEl('h3', 'pst-sec', '📁 Respondidas, falta cerrarlas'));
  if (!cer.length) {
    body.appendChild(pstEl('div', 'cump-empty', 'No queda ninguna PQRSF respondida sin cerrar. 👏'));
    return;
  }
  const cab2 = ['Sin cerrar', 'Radicado', 'Radicada', 'Respondida', 'Cumplimiento', 'Tipo', 'Motivo', 'Móvil', 'Área de destino', ''];
  const filas2 = cer.map((p) => [
    p.dias_sin_cerrar == null ? '—' : `${p.dias_sin_cerrar} día(s)`,
    p.radicado || '—', p.fecha_radicado ? fechaLegible(p.fecha_radicado) : '—',
    p.fecha_efectiva ? fechaLegible(p.fecha_efectiva) : '—', p.cumplimiento || '—',
    p.tipo || '—', p.motivo || '—', p.numero_interno || '—', p.responsable_destino || '—', '']);
  body.appendChild(pqsTablaBandeja(
    `Falta cerrar (${pstNum(cer.length)}${cer.length < nCer ? ' de ' + pstNum(nCer) : ''})`,
    'Estas ya tienen respuesta: lo único que falta es cerrarlas. Revisa la respuesta abriendo la fila y cierra con el botón.',
    cab2, filas2, cer, null, true));
  _pst.tablas.push({ titulo: 'PQRSF respondidas sin cerrar', nota: `Al ${fechaLegible(P.hoy)}`,
    cab: cab2.slice(0, -1), filas: filas2.map((f) => f.slice(0, -1)) });
}

// Arma una de las dos tablas de la bandeja. `conCerrar` pone el botón de cierre en la última celda.
function pqsTablaBandeja(titulo, nota, cab, filas, items, claseCelda, conCerrar) {
  const g = pstEl('div', 'pst-grid');
  const card = pstEl('section', 'pst-card pst-ancha');
  const head = pstEl('div', 'pst-card-h'); const tt = pstEl('div');
  tt.appendChild(pstEl('h4', null, titulo));
  tt.appendChild(pstEl('div', 'pst-nota', nota));
  head.appendChild(tt);
  const cuerpo = pstEl('div', 'pst-card-b pst-tabla-wrap');
  const tabla = pstEl('table', 'pst-tabla');
  const tr = pstEl('tr'); cab.forEach((c) => tr.appendChild(pstEl('th', null, c)));
  const thead = pstEl('thead'); thead.appendChild(tr); tabla.appendChild(thead);
  const tb = pstEl('tbody');
  filas.forEach((fila, k) => {
    const p = items[k];
    const r = pstEl('tr');
    fila.forEach((v, i) => {
      const td = pstEl('td', claseCelda ? claseCelda(p, i) : null, v);
      if (conCerrar && i === fila.length - 1) {
        td.textContent = '';
        const b = pstEl('button', 'btn btn-sm', '✅ Cerrar');
        b.type = 'button'; b.title = 'Dar por cerrada esta PQRSF (ya tiene respuesta)';
        b.onclick = (e) => { e.stopPropagation(); pqsCerrar(p, b, r); };
        td.appendChild(b);
      }
      r.appendChild(td);
    });
    r.classList.add('pst-clic'); r.tabIndex = 0; r.title = 'Abrir el radicado';
    const abrir = () => pqsAbrirFicha(p.key);
    r.addEventListener('click', abrir);
    r.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); abrir(); } });
    tb.appendChild(r);
  });
  tabla.appendChild(tb); cuerpo.appendChild(tabla); card.append(head, cuerpo);
  g.appendChild(card);
  return g;
}

// Cierra una PQRSF que ya tiene respuesta, sin obligar a reescribirla (sql/92).
async function pqsCerrar(p, btn, fila) {
  btn.disabled = true; const prev = btn.textContent; btn.textContent = '⏳';
  try {
    const { data, error } = await sb.rpc('pqrsf_cerrar', { p_key: p.key, p_nota: null });
    if (error) throw error;
    if (!data?.ok) throw new Error(data?.error || 'no se pudo cerrar');
    toast(`${p.radicado || 'PQRSF'} cerrada.`, 'ok');
    fila.style.opacity = '.45'; btn.textContent = '✅ Cerrada';
    refrescarPqrsfAcceso();
  } catch (e) {
    const t = String(e.message || e);
    toast(/pqrsf_cerrar/.test(t) ? 'Para cerrar desde aquí falta ejecutar sql/92.' : 'No se pudo cerrar: ' + t, 'err');
    btn.disabled = false; btn.textContent = prev;
  }
}

async function pqsAbrirFicha(key) {
  if (!key) return;
  showBusy('Abriendo el radicado…');
  try {
    const { data, error } = await sb.from('pqrsf').select('*').eq('key', key).single();
    if (error) throw error;
    openPqrsf(data);
  } catch (e) {
    toast('No se pudo abrir el radicado: ' + (e.message || e), 'err');
  } finally { hideBusy(); }
}

async function exportarPqrsfStats() {
  if (!_pst.tablas.length) { toast('No hay estadísticas para exportar.', 'err'); return; }
  const btn = $('pst-excel'); const prev = btn.textContent; btn.disabled = true; btn.textContent = '⏳ Generando…';
  try {
    const XLSX = await import('https://esm.sh/xlsx@0.18.5');
    const aoa = [['PQRSF — Autobuses El Poblado'], [`Periodo: ${_pqs.filtro || ''}`],
      [`Generado: ${fmtFechaHora(new Date())}`], []];
    for (const t of _pst.tablas) {
      aoa.push([t.titulo]); if (t.nota) aoa.push([t.nota]);
      aoa.push(t.cab); t.filas.forEach((f) => aoa.push(f)); aoa.push([]);
    }
    const ws = XLSX.utils.aoa_to_sheet(aoa);
    ws['!cols'] = [{ wch: 34 }, { wch: 14 }, { wch: 14 }, { wch: 14 }, { wch: 16 }, { wch: 18 }, { wch: 24 }, { wch: 14 }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'PQRSF');
    const blob = new Blob([XLSX.write(wb, { type: 'array', bookType: 'xlsx' })],
      { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob); a.download = `PQRSF_${hoyServidor()}.xlsx`; a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    toast('Excel generado', 'ok');
  } catch (e) {
    toast('No se pudo generar el Excel: ' + (e.message || e), 'err');
  } finally { btn.disabled = false; btn.textContent = prev; }
}

// ---- Panel de gestión: responder, asignar y ver el historial ----
// La respuesta escrita aquí NO va a las mismas columnas que trae la hoja de AppSheet: vive en
// `respuesta_app` (sql/91), así que volver a traer la hoja no la borra. Lo que se muestra como
// respuesta es la de la app si existe y, si no, la que vino de la hoja.
async function pqrPanelGestion(cont, row) {
  cont.innerHTML = '';
  const deLaApp = !!row.respuesta_app;
  const texto = row.respuesta_app || row.respuesta || '';

  cont.appendChild(pstEl('h4', 'pqr-h', 'Respuesta al usuario'));
  if (texto) {
    const caja = pstEl('div', 'pqr-resp');
    caja.appendChild(pstEl('div', 'pqr-resp-t', texto));
    const pie = deLaApp
      ? `Respondida en la app${row.respondido_por ? ' por ' + row.respondido_por : ''}`
        + `${row.respondido_el ? ' el ' + fechaLegible(row.respondido_el) : ''}`
      : 'Respuesta que venía de la hoja de AppSheet';
    caja.appendChild(pstEl('div', 'pst-nota', pie));
    cont.appendChild(caja);
  } else {
    cont.appendChild(pstEl('div', 'pst-nota', 'Todavía no tiene respuesta.'));
  }

  let F = null;
  try {
    const { data, error } = await sb.rpc('pqrsf_ficha', { p_key: row.key });
    if (error) throw error;
    F = data;
  } catch (e) {
    const txt = String(e.message || e);
    cont.appendChild(pstEl('div', 'pst-nota',
      /pqrsf_ficha/.test(txt) ? 'Para responder desde la app falta ejecutar sql/91.' : 'No se pudo leer la gestión: ' + txt));
    return;
  }
  if (!F || !F.ok) return;

  // ---- Formulario de respuesta ----
  if (F.puede_responder) {
    const caja = pstEl('div', 'pqr-form');
    const ta = document.createElement('textarea');
    ta.className = 'pqr-ta'; ta.rows = 5; ta.value = row.respuesta_app || '';
    ta.placeholder = 'Escribe aquí la respuesta que se le da al usuario…';
    const fila = pstEl('div', 'pqr-btns');
    const bGuardar = pstEl('button', 'btn btn-sm', '💾 Guardar respuesta');
    const bCerrar = pstEl('button', 'btn btn-sm btn-primary', '✅ Responder y cerrar');
    const msg = pstEl('span', 'pst-nota');
    const enviar = async (cerrar) => {
      const t = ta.value.trim();
      if (!t) { msg.textContent = 'Escribe la respuesta primero.'; return; }
      bGuardar.disabled = true; bCerrar.disabled = true; msg.textContent = 'Guardando…';
      try {
        const { data, error } = await sb.rpc('pqrsf_responder',
          { p_key: row.key, p_texto: t, p_cerrar: !!cerrar });
        if (error) throw error;
        if (!data?.ok) throw new Error(data?.error || 'no se pudo guardar');
        toast(cerrar ? 'PQRSF respondida y cerrada.' : 'Respuesta guardada.', 'ok');
        const { data: fresca } = await sb.from('pqrsf').select('*').eq('key', row.key).single();
        if (fresca) { _pqrRow = fresca; openPqrsf(fresca); }
        if (current === 'pqrsf') loadData();
        refrescarPqrsfAcceso();
      } catch (e) {
        msg.textContent = 'No se pudo guardar: ' + (e.message || e);
        bGuardar.disabled = false; bCerrar.disabled = false;
      }
    };
    bGuardar.type = 'button'; bCerrar.type = 'button';
    bGuardar.onclick = () => enviar(false);
    bCerrar.onclick = () => enviar(true);
    fila.append(bGuardar, bCerrar, msg);
    caja.append(ta, fila);
    cont.appendChild(pstEl('h4', 'pqr-h', deLaApp ? 'Corregir la respuesta' : 'Responder'));
    cont.appendChild(caja);

    // Ya tiene respuesta pero sigue abierta: cerrarla no deberia obligar a redactarla de nuevo.
    if ((row.fecha_respuesta || row.respondido_el) && String(row.estado_app || '') !== 'CERRADA') {
      const cj = pstEl('div', 'pqr-form');
      const bc = pstEl('button', 'btn btn-sm', '\ud83d\udcc1 Cerrar sin cambiar la respuesta');
      bc.type = 'button';
      const m2 = pstEl('span', 'pst-nota', 'Ya fue respondida, pero sigue marcada abierta.');
      bc.onclick = async () => {
        bc.disabled = true; m2.textContent = 'Cerrando\u2026';
        try {
          const { data, error } = await sb.rpc('pqrsf_cerrar', { p_key: row.key, p_nota: null });
          if (error) throw error;
          if (!data?.ok) throw new Error(data?.error || 'no se pudo cerrar');
          toast('PQRSF cerrada.', 'ok');
          const { data: fresca } = await sb.from('pqrsf').select('*').eq('key', row.key).single();
          if (fresca) { _pqrRow = fresca; openPqrsf(fresca); }
          if (current === 'pqrsf') loadData();
          refrescarPqrsfAcceso();
        } catch (e) {
          const t = String(e.message || e);
          m2.textContent = /pqrsf_cerrar/.test(t)
            ? 'Para cerrar desde aqu\u00ed falta ejecutar sql/92.' : 'No se pudo cerrar: ' + t;
          bc.disabled = false;
        }
      };
      cj.append(bc, m2);
      cont.appendChild(cj);
    }
  } else {
    cont.appendChild(pstEl('div', 'pst-nota',
      F.mi_area ? `Esta PQRSF no es de tu área (${F.mi_area}), así que solo la puedes consultar.`
        : 'Tu cuenta puede consultar las PQRSF, pero no responderlas.'));
  }

  // ---- Asignar a un área (administración y Gestión Humana) ----
  if (F.puede_asignar) {
    const caja = pstEl('div', 'pqr-form');
    const sel = document.createElement('select'); sel.className = 'pqr-sel';
    sel.appendChild(Object.assign(document.createElement('option'),
      { value: '', textContent: '— Elegir área —' }));
    (F.areas || []).filter(Boolean).sort().forEach((a) => sel.appendChild(
      Object.assign(document.createElement('option'), { value: a, textContent: a })));
    const actual = row.area_app || row.responsable_destino || '';
    if (actual && [...sel.options].some((o) => o.value === actual)) sel.value = actual;
    const b = pstEl('button', 'btn btn-sm', '📨 Asignar');
    b.type = 'button';
    const msg = pstEl('span', 'pst-nota');
    b.onclick = async () => {
      if (!sel.value) { msg.textContent = 'Elige el área.'; return; }
      b.disabled = true; msg.textContent = 'Asignando…';
      try {
        const { data, error } = await sb.rpc('pqrsf_asignar', { p_key: row.key, p_area: sel.value });
        if (error) throw error;
        if (!data?.ok) throw new Error(data?.error || 'no se pudo');
        toast('PQRSF asignada a ' + sel.value, 'ok');
        const { data: fresca } = await sb.from('pqrsf').select('*').eq('key', row.key).single();
        if (fresca) openPqrsf(fresca);
        if (current === 'pqrsf') loadData();
      } catch (e) {
        msg.textContent = 'No se pudo asignar: ' + (e.message || e); b.disabled = false;
      }
    };
    caja.append(sel, b, msg);
    cont.appendChild(pstEl('h4', 'pqr-h', 'Asignar a un área'));
    cont.appendChild(caja);
  }

  // ---- Historial ----
  const hist = F.historial || [];
  if (hist.length) {
    cont.appendChild(pstEl('h4', 'pqr-h', 'Movimientos'));
    const ul = pstEl('div', 'pqr-hist');
    const ICONO = { RESPUESTA: '✍️', CIERRE: '✅', ASIGNACION: '📨', REAPERTURA: '↩️', NOTA: '📝' };
    hist.forEach((h) => {
      const it = pstEl('div', 'pqr-hist-it');
      it.appendChild(pstEl('div', 'pqr-hist-h',
        `${ICONO[h.accion] || '•'} ${h.accion}${h.area ? ' → ' + h.area : ''} · ${h.usuario} · ${evbCuando(h.cuando)}`));
      if (h.texto) it.appendChild(pstEl('div', 'pqr-hist-t', h.texto));
      ul.appendChild(it);
    });
    cont.appendChild(ul);
  }
}

// ---- Ficha del siniestro: el reporte completo, ordenado ----
let _sinRow = null;
function sinModal() {
  let m = $('sin-modal');
  if (m) return m;
  m = document.createElement('div');
  m.id = 'sin-modal'; m.className = 'modal'; m.hidden = true;
  m.innerHTML = `<div class="modal-card pf-card">
    <div class="modal-head"><h3>🚨 Siniestro</h3><span class="spacer"></span>
      <button type="button" class="icon-btn" data-x aria-label="Cerrar">✕</button></div>
    <div class="pf-body"></div>
    <div class="modal-foot"><span class="spacer"></span><button type="button" class="btn" data-x>Cerrar</button></div>
  </div>`;
  m.addEventListener('click', (e) => { if (e.target === m || e.target.closest('[data-x]')) m.hidden = true; });
  document.body.appendChild(m);
  return m;
}
// Bloque de datos: solo pinta lo que tiene valor
function sinBloque(titulo, filas) {
  const con = filas.filter(([, v]) => v != null && String(v).trim() !== '' && String(v).trim() !== '—');
  if (!con.length) return '';
  return `<section class="pf-sec"><h4>${titulo}</h4><dl>${con.map(([k, v]) =>
    `<dt>${esc(k)}</dt><dd>${v}</dd>`).join('')}</dl></section>`;
}
function sinFotosHtml(s) {
  const fotos = Array.isArray(s.fotos) ? s.fotos : [];
  const extra = [['Documento (cara 1)', s.doc_cara1], ['Documento (cara 2)', s.doc_cara2],
    ['Firma del conductor', s.firma_conductor], ['Firma del tercero', s.tercero_firma],
    ['Video', s.video], ['Audio del conductor', s.audio_conductor],
    ['Audio del tercero', s.audio_tercero], ['Audio del asistente', s.audio_asistente]]
    .filter(([, v]) => v && String(v).trim());
  if (!fotos.length && !extra.length) return '';
  const item = (nombre, ruta, obs) => {
    const esLink = /^https?:\/\//i.test(String(ruta || ''));
    const cuerpo = esLink ? `<a href="${esc(ruta)}" target="_blank" rel="noopener">abrir</a>` : `<span class="sin-arch">${esc(ruta)}</span>`;
    return `<li><b>${esc(nombre)}</b> ${cuerpo}${obs ? `<div class="muted">${esc(obs)}</div>` : ''}</li>`;
  };
  return `<section class="pf-sec sin-adj"><h4>📎 Adjuntos del reporte (${fotos.length + extra.length})</h4>
    <ul>${fotos.map((f) => item(`Foto ${f.n}`, f.ruta, f.observacion)).join('')}
    ${extra.map(([n, v]) => item(n, v, '')).join('')}</ul></section>`;
}
// El reporte TAL COMO viene de la app de AppSheet: todas las columnas de la hoja, sin recortar.
// Sirve para verificar un dato puntual que no quedó en los bloques de arriba.
function sinTodoHtml(s) {
  const d = s.datos_origen && typeof s.datos_origen === 'object' ? s.datos_origen : null;
  if (!d) return '';
  const filas = Object.entries(d).filter(([, v]) => String(v == null ? '' : v).trim() !== '');
  if (!filas.length) return '';
  return `<details class="pf-sec sin-todo">
    <summary>🧾 Todos los datos del reporte (${filas.length} campos, como vienen de la app)</summary>
    <dl>${filas.map(([k, v]) => `<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl></details>`;
}
function openSiniestro(s) {
  if (!isTalentoHumano()) return;
  _sinRow = s;
  const m = sinModal(), body = m.querySelector('.pf-body');
  const chips = [
    s.gravedad ? `<span class="chip ${s.gravedad === 'HERIDO' ? 'chip-red' : 'chip-gray'}">${esc(s.gravedad)}</span>` : '',
    s.categorizacion ? `<span class="chip ${s.categorizacion === 'GRAVE' ? 'chip-red' : s.categorizacion === 'MODERADO' ? 'chip-amber' : 'chip-blue'}">${esc(s.categorizacion)}</span>` : '',
    s.responsabilidad ? `<span class="chip ${s.responsabilidad === 'SI' ? 'chip-amber' : s.responsabilidad === 'NO' ? 'chip-green' : 'chip-gray'}">Responsable: ${esc(s.responsabilidad)}</span>` : '',
    s.estado ? `<span class="chip ${s.estado === 'CERRADO' ? 'chip-green' : 'chip-violet'}">${esc(s.estado)}</span>` : '',
  ].filter(Boolean).join(' ');
  const coord = String(s.coordenadas || '').trim();
  const mapa = /-?\d+\.\d+/.test(coord)
    ? `<a href="https://www.google.com/maps?q=${encodeURIComponent(coord)}" target="_blank" rel="noopener">📍 ver en el mapa</a>` : esc(coord);
  const wa = (tel) => {
    const t = String(tel || '').replace(/\D/g, '');
    return t.length === 10 ? `${esc(tel)} <a href="https://wa.me/57${t}" target="_blank" rel="noopener" title="WhatsApp">💬</a>` : esc(tel || '');
  };
  m.querySelector('h3').textContent = `🚨 Siniestro del ${fechaLegible(s.fecha || '')}`;
  body.innerHTML = `
    <header class="pf-top">
      <div class="pf-av cond">${esc(s.numero_interno || '—')}</div>
      <div class="pf-idt">
        <h2>${esc(s.placa || 'sin placa')}${s.ruta ? ` · ruta ${esc(s.ruta)}` : ''}</h2>
        <div class="pf-sub">${esc(fechaLegible(s.fecha || ''))}${s.reportado_en ? ` · reportado ${esc(fmtFechaHora(s.reportado_en))}` : ''}</div>
        <div class="pf-chips">${chips}</div>
        ${(isAdmin() || isAuditor()) && s.numero_interno
    ? `<button type="button" class="btn btn-sm sin-evt-btn" data-sinevt>🔎 Eventos del bus ese día</button>` : ''}
      </div>
    </header>
    <div class="pf-secs">
      ${sinBloque('🚌 Vehículo y ruta', [['Móvil', esc(s.numero_interno || '')], ['Placa', esc(s.placa || '')],
        ['Ruta', esc(s.ruta || '')], ['Afiliado', esc(s.afiliado || '')],
        ['Correo del afiliado', esc(s.correo_afiliado || '')], ['Teléfono del afiliado', wa(s.telefono_afiliado)]])}
      ${sinBloque('🧑‍✈️ Conductor', [['Nombre', s.conductor_nombre
        ? `<button type="button" class="pf-link" data-percedula="${esc(s.conductor_cedula || '')}" data-percodigo="${esc(s.conductor_codigo || '')}"
             title="Ver la ficha de la persona">${esc(s.conductor_nombre)}</button>` : ''], ['Código', esc(s.conductor_codigo || '')],
        ['Cédula', esc(s.conductor_cedula || '')], ['Celular', wa(s.conductor_celular)],
        ['Ingresó a la empresa', esc(fechaLegible(s.conductor_fecha_ingreso || ''))]])}
      ${sinBloque('💥 Qué pasó', [['Causa probable', esc(s.causa || '')], ['Norma', esc(s.norma || '')],
        ['Hipótesis', esc(s.hipotesis || '')], ['Factor', esc(s.factor || '')],
        ['Tipo de lesión', esc(s.tipo_lesion || '')], ['Lugar', esc(s.lugar || '')], ['Ubicación', mapa],
        ['Daños de la empresa', esc(s.danos_empresa || '')], ['Lesiones', esc(s.lesiones || '')],
        ['Observaciones', esc(s.observaciones || '')]])}
      ${sinBloque('🚗 Tercero afectado', [['Nombre', esc(s.tercero_nombre || '')], ['Placa', esc(s.tercero_placa || '')],
        ['Identificación', [s.tercero_tipo_id, s.tercero_cedula].filter(Boolean).map(esc).join(' ')],
        ['Expedida en', esc(s.tercero_ciudad_cedula || '')], ['Teléfono', wa(s.tercero_telefono)],
        ['Otro teléfono', esc(s.tercero_telefono2 || '')], ['Correo', esc(s.tercero_correo || '')],
        ['Aseguradora', esc(s.tercero_aseguradora || '')], ['Daños', esc(s.tercero_danos || '')]])}
      ${sinBloque('📋 Gestión', [['Estado del reporte', esc(s.estado_inicio || '')],
        ['Estado administrativo', esc(s.estado || '')], ['Tipo de conciliación', esc(s.tipo_conciliacion || '')],
        ['Monto', s.monto ? '$ ' + Number(s.monto).toLocaleString('es-CO') : ''],
        ['Monto en texto', esc(s.monto_texto || '')],
        ['Reportó en la app', esc(s.usuario_app || '')], ['Usuario de logística', esc(s.usuario_logistica || '')],
        ['Correo del asistente', esc(s.correo_asistente || '')],
        ['Observaciones de asistencia', esc(s.observaciones_asistencia || '')],
        ['Autorización de datos', esc(s.autorizacion_datos || '')], ['Mes del reporte', esc(s.mes_reporte || '')]])}
      ${sinFotosHtml(s)}
    </div>
    ${sinTodoHtml(s)}`;
  // Qué hacía el bus ese día: excesos de velocidad y puertas abiertas alrededor del siniestro
  body.querySelector('[data-sinevt]')?.addEventListener('click', () => sinEventosDelBus(s));
  // El nombre del conductor abre su ficha en el perfil sociodemográfico
  body.querySelectorAll('[data-percedula]').forEach((b) => {
    b.onclick = () => sinAbrirPersona(b.dataset.percedula, b.dataset.percodigo);
  });
  m.hidden = false;
}
// Del siniestro a la conducta de manejo: abre los eventos del bus alrededor del choque
// (dos horas antes y una después del reporte; si no hay hora, el día completo).
async function sinEventosDelBus(s) {
  if (!(isAdmin() || isAuditor())) {
    toast('Los eventos del bus los consultan el administrador y los auditores.', 'err'); return;
  }
  const f = String(s.fecha || '').slice(0, 10) || hoyServidor();
  let desde = `${f}T04:00`, hasta = `${f}T23:59`;
  const m = /[T ](\d{2}):(\d{2})/.exec(String(s.reportado_en || ''));
  if (m) {
    const h = Number(m[1]);
    desde = `${f}T${_pad2(Math.max(0, h - 2))}:${m[2]}`;
    hasta = `${f}T${_pad2(Math.min(23, h + 1))}:${m[2]}`;
  }
  const evt = $('evt-modal');
  if (evt) document.body.appendChild(evt); // que quede encima de la ficha del siniestro
  await abrirEventosAuditor({ movil: s.numero_interno, ruta: s.ruta, fecha: f, hora: '00:00' }, [desde, hasta]);
}
// Del siniestro a la persona: busca por cédula y, si no está, por el código del conductor
async function sinAbrirPersona(cedula, codigo) {
  const ced = String(cedula || '').trim();
  showBusy('Buscando en el perfil…');
  try {
    let data = null;
    if (ced) ({ data } = await sb.from('perfilsociodemografico').select('*').eq('cedula', ced).maybeSingle());
    if (!data && codigo) {
      ({ data } = await sb.from('perfilsociodemografico').select('*').eq('codigo', String(codigo).trim()).maybeSingle());
    }
    if (!data) { toast('Ese conductor no está en el perfil sociodemográfico.', 'err'); return; }
    openPerfilFicha(data);
  } catch (e) {
    toast('No se pudo abrir la ficha: ' + (e.message || e), 'err');
  } finally { hideBusy(); }
}

// ===================================================================================
// 🪪 FICHA DE PERSONA (Perfil sociodemográfico)
// La tabla muestra lo básico; la ficha muestra TODA la hoja de vida ordenada por
// secciones, sin abrir el formulario de edición. Se abre con el nombre o con 👁️.
// ===================================================================================
const PF_SEC = {
  'Identificación': '🪪', 'Laboral': '💼', 'Seguridad social': '🏥', 'Licencia y restricción': '🚦',
  'Datos personales': '🧍', 'Vivienda': '🏠', 'Educación': '🎓', 'Núcleo familiar': '👨‍👩‍👧',
  'Contacto de emergencia': '🆘', 'Referencia laboral': '📞', 'Control de datos': '🗃️',
};
// Ya salen en el encabezado: no se repiten dentro de las secciones.
const PF_EN_CABECERA = ['cedula', 'nombre', 'tipo', 'estado', 'cargo'];
let _pfVacios = false;  // ver también los campos sin dato
let _pfRow = null;

function pfModal() {
  let m = $('pf-modal');
  if (m) return m;
  m = document.createElement('div');
  m.id = 'pf-modal'; m.className = 'modal'; m.hidden = true;
  m.innerHTML = `<div class="modal-card pf-card">
    <div class="modal-head"><h3>🪪 Ficha</h3><span class="spacer"></span>
      <button type="button" class="icon-btn" data-x aria-label="Cerrar">✕</button></div>
    <div class="pf-body"></div>
    <div class="modal-foot">
      <label class="pf-sw"><input type="checkbox" data-vacios> Ver campos sin dato</label>
      <span class="spacer"></span>
      <button type="button" class="btn btn-sm" data-cert hidden>📄 Certificado laboral</button>
      <button type="button" class="btn btn-sm" data-editar hidden>✏️ Editar ficha</button>
      <button type="button" class="btn" data-x>Cerrar</button>
    </div>
  </div>`;
  m.addEventListener('click', (e) => { if (e.target === m || e.target.closest('[data-x]')) m.hidden = true; });
  m.querySelector('[data-vacios]').addEventListener('change', (e) => {
    _pfVacios = e.target.checked;
    const secs = m.querySelector('.pf-secs');
    if (_pfRow && secs) secs.innerHTML = pfSeccionesHtml(_pfRow);
  });
  m.querySelector('[data-editar]').onclick = () => { m.hidden = true; if (_pfRow) openEditor(_pfRow); };
  m.querySelector('[data-cert]').onclick = () => { if (_pfRow) openCertificado(_pfRow); };
  document.body.appendChild(m);
  return m;
}

// Un campo ya legible: fechas en dd/mm/aaaa, salario con separador, correo y celular enlazados.
function pfValor(f, row) {
  const v = row[f.key];
  if (v == null || String(v).trim() === '') return '';
  if (f.type === 'date') return esc(fechaLegible(v));
  if (f.key === 'salario') return '$ ' + Number(v).toLocaleString('es-CO');
  if (f.key === 'correo') return `<a href="mailto:${esc(v)}">${esc(v)}</a>`;
  if (/^3\d{9}$/.test(String(v).trim())) {
    return `${esc(v)} <a class="pf-wa" href="https://wa.me/57${String(v).trim()}" target="_blank" rel="noopener" title="Escribir por WhatsApp">💬</a>`;
  }
  return esc(String(v));
}

function pfSeccionesHtml(row) {
  const campos = TABLES.perfilsociodemografico.fields;
  const secciones = [];
  campos.forEach((f) => { const s = f.section || 'Otros'; if (!secciones.includes(s)) secciones.push(s); });
  return secciones.map((s) => {
    const filas = campos.filter((f) => (f.section || 'Otros') === s && !PF_EN_CABECERA.includes(f.key))
      .map((f) => ({ f, html: pfValor(f, row) }))
      .filter((x) => _pfVacios || x.html !== '');
    if (!filas.length) return '';
    return `<section class="pf-sec"><h4>${PF_SEC[s] || '•'} ${esc(s)}</h4><dl>${filas.map((x) =>
      `<dt>${esc(x.f.label)}</dt><dd${x.html ? '' : ' class="pf-nada"'}>${x.html || '—'}</dd>`).join('')}</dl></section>`;
  }).join('');
}

function pfHistorialHtml(hist) {
  if (!hist || !hist.length) return '';
  return `<section class="pf-sec pf-hist"><h4>🗂️ Historial de vinculaciones</h4>
    <ol>${hist.map((h) => {
    const activo = !h.fecha_retiro;
    return `<li class="${activo ? 'on' : ''}"><span class="pf-hdot"></span>
        <div><b>${esc(fechaLegible(h.fecha_ingreso || ''))}</b> → ${activo ? '<b>hoy</b>' : esc(fechaLegible(h.fecha_retiro))}
        <span class="${chipClass(h.tipo_ingreso || 'NUEVO')}">${esc(h.tipo_ingreso || 'NUEVO')}</span>
        <div class="muted">${esc(h.cargo || '')}${h.novedad_retiro ? ' · Retiro: ' + esc(h.novedad_retiro) : ''}</div></div></li>`;
  }).join('')}</ol></section>`;
}

// 🚨 Los siniestros de esa persona (cruce por cédula con la tabla de siniestros)
function pfSiniestrosHtml(sin) {
  if (!sin || !sin.length) return '';
  const conResp = sin.filter((s) => s.responsabilidad === 'SI').length;
  const heridos = sin.filter((s) => s.gravedad === 'HERIDO').length;
  const monto = sin.reduce((tt, s) => tt + Number(s.monto || 0), 0);
  const resumen = [`${sin.length} siniestro(s)`, conResp ? `${conResp} con responsabilidad` : '',
    heridos ? `${heridos} con heridos` : '', monto ? `$ ${Math.round(monto).toLocaleString('es-CO')} reconocidos` : '']
    .filter(Boolean).join(' · ');
  return `<section class="pf-sec pf-sin"><h4>🚨 Siniestros del conductor</h4>
    <div class="muted pf-sin-res">${esc(resumen)}</div>
    <ul>${sin.map((s) => `<li><button type="button" class="pf-link" data-sinkey="${esc(s.key)}">
        ${esc(fechaLegible(s.fecha || ''))}</button>
        <span class="muted">móvil ${esc(s.numero_interno || '—')} · ${esc(s.placa || '')}${s.ruta ? ' · ruta ' + esc(s.ruta) : ''}</span>
        ${s.gravedad ? `<span class="chip ${s.gravedad === 'HERIDO' ? 'chip-red' : 'chip-gray'}">${esc(s.gravedad)}</span>` : ''}
        ${s.responsabilidad === 'SI' ? '<span class="chip chip-amber">responsable</span>' : ''}
        ${Number(s.monto || 0) ? `<span class="chip chip-blue">$ ${Math.round(Number(s.monto)).toLocaleString('es-CO')}</span>` : ''}
      </li>`).join('')}</ul></section>`;
}
function pfRender(row, hist, sin) {
  const m = pfModal(), body = m.querySelector('.pf-body');
  const iniciales = String(row.nombre || '?').trim().split(/\s+/).slice(0, 2).map((p) => p[0]).join('');
  const edad = edadPerfil(row), anios = antiguedadPerfil(row);
  const inactivo = row.estado === 'INACTIVO';
  const porCorregir = String(row.por_corregir || '').trim();
  const licVence = row.licencia_vencimiento || '';
  const licVencida = licVence && licVence < hoyServidor();
  const licPronto = licVence && !licVencida && licVence <= new Date(Date.now() + 45 * 864e5).toISOString().slice(0, 10);

  const chips = [
    `<span class="${chipClass(row.estado)}">${esc(row.estado || '—')}</span>`,
    `<span class="chip chip-blue">${esc(row.tipo || '—')}</span>`,
    row.calidad === 'POR CORREGIR' ? '<span class="chip chip-amber">Datos por corregir</span>' : '',
    row.habeas_data_aceptado_en ? '<span class="chip chip-green">Autorizó sus datos</span>' : '',
  ].filter(Boolean).join(' ');

  const kpis = [
    edad ? { n: edad, l: 'años' } : null,
    anios ? { n: anios, l: anios === 1 ? 'año en APL' : 'años en APL' } : null,
    row.salario ? { n: '$' + Number(row.salario).toLocaleString('es-CO'), l: 'salario', sm: true } : null,
    licVence ? { n: fechaLegible(licVence), l: licVencida ? 'licencia VENCIDA' : 'vence la licencia', sm: true, alerta: licVencida || licPronto } : null,
  ].filter(Boolean).map((k) => `<div class="pf-kpi${k.alerta ? ' alerta' : ''}"><b class="${k.sm ? 'sm' : ''}">${esc(String(k.n))}</b><span>${esc(k.l)}</span></div>`).join('');

  const avisos = [
    inactivo ? `<div class="pf-aviso gris">Persona <b>INACTIVA</b>${row.fecha_retiro ? ` desde el ${esc(fechaLegible(row.fecha_retiro))}` : ''}${row.novedad_retiro ? ` · ${esc(row.novedad_retiro)}` : ''}.</div>` : '',
    licVencida && row.tipo === 'CONDUCTOR' ? `<div class="pf-aviso rojo">🪪 La licencia está <b>vencida</b> (${esc(fechaLegible(licVence))}).</div>` : '',
    porCorregir ? `<div class="pf-aviso ambar">📝 Campos por corregir: <b>${esc(porCorregir)}</b></div>` : '',
  ].filter(Boolean).join('');

  m.querySelector('h3').textContent = '🪪 Ficha de la persona';
  // Editar abre el formulario de la tabla; solo tiene sentido estando en ella
  m.querySelector('[data-editar]').hidden = !isTalentoHumano() || current !== 'perfilsociodemografico';
  m.querySelector('[data-cert]').hidden = !isTalentoHumano();
  m.querySelector('[data-vacios]').checked = _pfVacios;
  body.innerHTML = `
    <header class="pf-top">
      <div class="pf-av ${row.tipo === 'CONDUCTOR' ? 'cond' : 'adm'}${inactivo ? ' off' : ''}">${esc(iniciales)}</div>
      <div class="pf-idt">
        <h2>${esc(row.nombre || '—')}</h2>
        <div class="pf-sub">C.C. ${esc(row.cedula || '—')}${row.codigo ? ' · Código ' + esc(row.codigo) : ''}${row.cargo ? ' · ' + esc(row.cargo) : ''}</div>
        <div class="pf-chips">${chips}</div>
      </div>
      ${row.celular ? `<a class="pf-wabtn" href="https://wa.me/57${esc(String(row.celular).trim())}" target="_blank" rel="noopener">💬 ${esc(row.celular)}</a>` : ''}
    </header>
    ${kpis ? `<div class="pf-kpis">${kpis}</div>` : ''}
    ${avisos}
    <div class="pf-secs">${pfSeccionesHtml(row)}</div>
    ${pfSiniestrosHtml(sin)}
    ${pfHistorialHtml(hist)}`;
  // Cada siniestro de la lista abre su reporte completo
  body.querySelectorAll('[data-sinkey]').forEach((b) => { b.onclick = () => sinAbrirPorKey(b.dataset.sinkey); });
}

// Los siniestros de la persona. La cédula del reporte viene de otra app: se prueba tal cual,
// y si no aparece, por el código del conductor (lo que sí comparten las dos fuentes).
async function pfLeerSiniestros(row) {
  const ced = String(row.cedula || '').trim();
  if (!ced) return [];
  const COLS = 'key,fecha,placa,numero_interno,ruta,gravedad,responsabilidad,categorizacion,monto,estado';
  try {
    let { data } = await sb.from('siniestros').select(COLS).eq('conductor_cedula', ced).order('fecha', { ascending: false });
    if ((!data || !data.length) && row.codigo) {
      ({ data } = await sb.from('siniestros').select(COLS).eq('conductor_codigo', String(row.codigo).trim())
        .order('fecha', { ascending: false }));
    }
    return data || [];
  } catch (e) { return []; } // si el rol no ve siniestros, la ficha sigue funcionando igual
}
async function openPerfilFicha(row) {
  if (!isTalentoHumano()) return;
  _pfRow = row;
  const m = pfModal();
  m.querySelector('.pf-body').innerHTML = '<div class="loading">Cargando…</div>';
  m.hidden = false;
  try {
    // La fila de la tabla ya trae todo (select *); faltan el historial y los siniestros del conductor.
    const [{ data: hist }, sin] = await Promise.all([
      sb.from('perfil_vinculaciones').select('*').eq('cedula', row.cedula).order('fecha_ingreso', { ascending: false }),
      pfLeerSiniestros(row),
    ]);
    pfRender(row, hist || [], sin);
  } catch (e) {
    m.querySelector('.pf-body').innerHTML = `<div class="rst-empty">Error: ${esc(e.message || e)}</div>`;
  }
}


// ===================================================================================
// 📄 CERTIFICADO LABORAL (sql/93) — se genera desde la ficha del perfil.
// La redacción se ajusta sola: ACTIVO va en presente ("labora", "devenga") e INACTIVO en
// pasado ("laboró", "devengaba"), que es justo lo que se equivocaba al copiar el de otro.
// Los firmantes, el teléfono y los valores del año NO están en el código (repo público):
// salen de `certificado_config`, que se llena una sola vez desde la base.
// ===================================================================================
let _certCfg = null;   // configuración (se lee una vez por sesión)
let _certRow = null;   // persona del certificado abierto

const CERT_MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto',
  'septiembre', 'octubre', 'noviembre', 'diciembre'];

// Cifra en letras, como se acostumbra en un certificado ("UN MILLÓN SETECIENTOS CINCUENTA MIL…").
function numeroALetras(n) {
  n = Math.floor(Math.abs(Number(n) || 0));
  if (!n) return 'CERO';
  const U = ['', 'UN', 'DOS', 'TRES', 'CUATRO', 'CINCO', 'SEIS', 'SIETE', 'OCHO', 'NUEVE', 'DIEZ',
    'ONCE', 'DOCE', 'TRECE', 'CATORCE', 'QUINCE', 'DIECISÉIS', 'DIECISIETE', 'DIECIOCHO', 'DIECINUEVE',
    'VEINTE', 'VEINTIUNO', 'VEINTIDÓS', 'VEINTITRÉS', 'VEINTICUATRO', 'VEINTICINCO', 'VEINTISÉIS',
    'VEINTISIETE', 'VEINTIOCHO', 'VEINTINUEVE'];
  const D = ['', '', '', 'TREINTA', 'CUARENTA', 'CINCUENTA', 'SESENTA', 'SETENTA', 'OCHENTA', 'NOVENTA'];
  const C = ['', 'CIENTO', 'DOSCIENTOS', 'TRESCIENTOS', 'CUATROCIENTOS', 'QUINIENTOS', 'SEISCIENTOS',
    'SETECIENTOS', 'OCHOCIENTOS', 'NOVECIENTOS'];
  const tramo = (x) => {
    if (x === 100) return 'CIEN';
    const c = Math.floor(x / 100), r = x % 100;
    let t = c ? C[c] : '';
    if (r) {
      const dd = Math.floor(r / 10), uu = r % 10;
      t += (t ? ' ' : '') + (r < 30 ? U[r] : D[dd] + (uu ? ' Y ' + U[uu] : ''));
    }
    return t;
  };
  const apocope = (t) => t.replace(/UNO$/, 'ÚN'); // "VEINTIUNO MIL" no existe: es "VEINTIÚN MIL"
  const mill = Math.floor(n / 1e6), resto = n % 1e6;
  const miles = Math.floor(resto / 1000), unid = resto % 1000;
  const p = [];
  if (mill) p.push(mill === 1 ? 'UN MILLÓN' : apocope(tramo(mill)) + ' MILLONES');
  if (miles) p.push(miles === 1 ? 'MIL' : apocope(tramo(miles)) + ' MIL');
  if (unid) p.push(tramo(unid));
  return p.join(' ');
}

const certPesos = (n) => '$' + Number(n || 0).toLocaleString('es-CO');

// El logo, ya convertido a imagen embebida: si se imprime desde otra ventana, una ruta relativa
// no resolvería y el certificado saldría sin membrete.
async function certLogoDataUri() {
  const img = await ensureLogo();
  if (!img) return '';
  try {
    const cv = document.createElement('canvas');
    cv.width = img.naturalWidth || 300; cv.height = img.naturalHeight || 300;
    cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height);
    return cv.toDataURL('image/png');
  } catch { return ''; }
}

async function certLeerConfig() {
  if (_certCfg) return _certCfg;
  const { data, error } = await sb.rpc('certificado_config_leer');
  if (error) throw error;
  _certCfg = data || { ok: false };
  return _certCfg;
}

// ---- El documento ----
function certDocHtml(row, cfg, opts) {
  const o = opts || {};
  const inactivo = row.estado === 'INACTIVO';
  const sexo = String(row.sexo || '').toUpperCase();
  const trato = sexo.startsWith('F') ? 'La señora' : sexo.startsWith('M') ? 'El señor' : 'El(La) señor(a)';
  const ido = sexo.startsWith('F') ? 'identificada' : sexo.startsWith('M') ? 'identificado' : 'identificado(a)';
  const emp = cfg.empresa_nombre || 'AUTOBUSES EL POBLADO LAURELES S.A.';

  // Verbos: en presente si sigue trabajando, en pasado si ya se retiró.
  const v = inactivo
    ? { labora: 'laboró', desempena: 'Desempeñó', devengando: 'devengando' }
    : { labora: 'labora', desempena: 'Desempeña', devengando: 'devengando' };

  // La fórmula "para vehículos de propiedad de…" solo aplica a quien trabaja sobre el vehículo.
  const donde = (row.tipo === 'CONDUCTOR'
    ? `para vehículos de propiedad de ${esc(emp)}`
    : `en ${esc(emp)}`).replace(/\.$/, ''); // "S.A." ya trae punto: evita el "S.A.." del modelo viejo

  // Salario: si coincide con el mínimo del año, se nombra como tal (es lo que pide el banco).
  let frase = '';
  if (o.conSalario && row.salario) {
    const sal = Number(row.salario);
    const esMin = cfg.smmlv && Math.abs(sal - Number(cfg.smmlv)) < 1;
    const cifra = `${certPesos(sal)} (${numeroALetras(sal)} PESOS M/CTE)`;
    frase = esMin
      ? `, ${v.devengando} un <b>Salario Mínimo Mensual Legal Vigente</b> de ${cifra}`
      : `, ${v.devengando} un salario mensual de <b>${cifra}</b>`;
    // Auxilio de transporte: por ley lo recibe quien gana hasta 2 salarios mínimos.
    if (o.conAuxilio && cfg.auxilio_transporte && (!cfg.smmlv || sal <= Number(cfg.smmlv) * 2)) {
      frase += `, más auxilio de transporte de ${certPesos(cfg.auxilio_transporte)}`;
    }
  }

  const contrato = row.tipo_contrato
    ? ` bajo un contrato laboral a término <b>${esc(row.tipo_contrato)}</b>`
    : '';

  const hoy = new Date();
  const fechaTexto = `${cfg.ciudad || 'Medellín'}, a los ${hoy.getDate()} días del mes de `
    + `${CERT_MESES[hoy.getMonth()]} de ${hoy.getFullYear()}`;
  const motivo = o.dirigidoA
    ? `Se expide a solicitud del interesado, con destino a <b>${esc(o.dirigidoA)}</b>.`
    : 'Se expide a solicitud del interesado.';

  // La firma se imprime con el tamano y la posicion que se dejaron configurados (sql/94),
  // para que salga igual en todos los certificados.
  const firma = (nom, cargo, img, alto, dx, dy) => nom
    ? `<div class="cl-f">${img
      ? `<img src="${esc(img)}" alt="" style="height:${Number(alto) || 58}px;transform:translate(${Number(dx) || 0}px,${Number(dy) || 0}px)">`
      : '<div class="cl-fl"></div>'}
         <div class="cl-fn">${esc(nom)}</div><div class="cl-fc">${esc(cargo || '')}</div></div>`
    : '';

  return `
  <div class="cl-hoja">
    ${o.logo ? `<div class="cl-logo"><img src="${o.logo}" alt=""></div>` : ''}
    <div class="cl-emp">${esc(emp)}</div>
    <div class="cl-nit">${esc(cfg.empresa_nit || '')}</div>

    <div class="cl-tit">CERTIFICA QUE:</div>

    <p class="cl-p">
      ${trato} <b>${esc(row.nombre || '')}</b>, ${ido} con cédula de ciudadanía
      No. <b>${esc(row.cedula || '')}</b>, ${v.labora} como <b>${esc(row.cargo || '')}</b> ${donde}.
      ${v.desempena} sus labores${contrato}${frase}.
    </p>

    <div class="cl-fechas">
      <div><span>Fecha de ingreso:</span> <b>${row.fecha_ingreso ? fechaLegible(row.fecha_ingreso) : '—'}</b></div>
      <div><span>Fecha de retiro:</span> <b>${row.fecha_retiro ? fechaLegible(row.fecha_retiro) : (inactivo ? '—' : '')}</b></div>
    </div>

    <p class="cl-p">${fechaTexto}. ${motivo}</p>

    ${cfg.telefono ? `<p class="cl-p cl-tel">Cualquier información con gusto será suministrada
      comunicándose al ${esc(cfg.telefono)} – ${esc(cfg.ciudad || 'Medellín')}.</p>` : ''}
    ${cfg.nota_pie ? `<p class="cl-p cl-nota">${esc(cfg.nota_pie)}</p>` : ''}

    <div class="cl-firmas">
      ${firma(cfg.firmante1_nombre, cfg.firmante1_cargo, cfg.firmante1_firma,
    cfg.firmante1_alto, cfg.firmante1_dx, cfg.firmante1_dy)}
      ${firma(cfg.firmante2_nombre, cfg.firmante2_cargo, cfg.firmante2_firma,
    cfg.firmante2_alto, cfg.firmante2_dx, cfg.firmante2_dy)}
    </div>
    ${o.consecutivo ? `<div class="cl-cons">${esc(o.consecutivo)}</div>` : ''}
  </div>`;
}

// Estilos del documento: van embebidos porque se imprime en una ventana aparte.
const CERT_CSS = `
  @page { size: letter; margin: 2.2cm 2.4cm; }
  body { margin: 0; font-family: Arial, Helvetica, sans-serif; color: #000; }
  .cl-hoja { font-size: 12.5pt; line-height: 1.55; }
  .cl-logo { text-align: center; margin-bottom: 10px; }
  .cl-logo img { height: 74px; }
  .cl-emp, .cl-nit, .cl-tit { text-align: center; font-weight: 700; }
  .cl-emp { font-size: 13.5pt; }
  .cl-nit { font-size: 12pt; margin-top: 6px; }
  .cl-tit { margin: 54px 0 40px; letter-spacing: .5px; }
  .cl-p { text-align: justify; margin: 0 0 22px; }
  .cl-fechas { margin: 30px 0 34px; }
  .cl-fechas div { margin-bottom: 12px; }
  .cl-fechas span { display: inline-block; min-width: 160px; font-weight: 700; }
  .cl-tel, .cl-nota { margin-top: 34px; }
  .cl-nota { font-size: 11pt; }
  .cl-firmas { display: flex; gap: 40px; margin-top: 80px; }
  .cl-f { flex: 1; text-align: center; }
  .cl-f img { height: 58px; display: block; margin: 0 auto 4px; }
  .cl-fl { height: 58px; }
  .cl-fn { border-top: 1px solid #000; padding-top: 6px; font-weight: 700; font-size: 11.5pt; }
  .cl-fc { font-size: 11pt; }
  .cl-cons { margin-top: 40px; font-size: 9.5pt; color: #444; }
`;

// ---- Pantalla: primero se revisa, se decide lo del salario, y solo entonces se genera ----
// El salario NO viene marcado por defecto a propósito: incluirlo o no es una decisión de quien
// expide el certificado (no es lo mismo el que pide un crédito que el que lo lleva a un arriendo),
// y una casilla premarcada se convierte en una decisión que nadie tomó.
let _certSal = null;   // null = todavía no ha decidido; true/false = con o sin salario

// Los datos que van a salir impresos, para revisarlos antes de generar.
function certRevisionHtml(row, cfg) {
  const inactivo = row.estado === 'INACTIVO';
  // El tercer argumento es lo que se muestra CUANDO NO HAY dato; solo entonces se marca en ambar.
  const dato = (etiqueta, valor, siFalta) => `<div class="cert-d${!valor && siFalta ? ' falta' : ''}">
      <span>${esc(etiqueta)}</span><b>${valor ? esc(String(valor)) : (siFalta || '—')}</b></div>`;
  const falta = [];
  if (!row.nombre) falta.push('el nombre');
  if (!row.cedula) falta.push('la cédula');
  if (!row.fecha_ingreso) falta.push('la fecha de ingreso');

  return `
    <div class="cert-rev">
      <div class="cert-rev-t">Esto es lo que va a decir el certificado</div>
      <div class="cert-datos">
        ${dato('Nombre', row.nombre, 'FALTA')}
        ${dato('Cédula', row.cedula, 'FALTA')}
        ${dato('Cargo', row.cargo, 'sin cargo en la ficha')}
        ${dato('Estado', row.estado)}
        ${dato('Tipo de contrato', row.tipo_contrato, 'sin contrato en la ficha')}
        ${dato('Fecha de ingreso', row.fecha_ingreso ? fechaLegible(row.fecha_ingreso) : '', 'FALTA')}
        ${dato('Fecha de retiro', row.fecha_retiro ? fechaLegible(row.fecha_retiro) : (inactivo ? '' : 'no aplica'),
    inactivo && !row.fecha_retiro ? 'está INACTIVA y no tiene fecha de retiro' : '')}
        ${dato('Salario en la ficha', row.salario ? certPesos(row.salario) : '', 'sin salario en la ficha')}
      </div>
      ${inactivo
    ? '<div class="cert-nota-est">Esta persona está <b>INACTIVA</b>: el certificado se redacta en pasado («laboró», «desempeñó») y lleva la fecha de retiro.</div>'
    : '<div class="cert-nota-est">Esta persona está <b>ACTIVA</b>: el certificado se redacta en presente («labora», «desempeña») y la fecha de retiro va en blanco.</div>'}
      ${falta.length
    ? `<div class="cert-bloqueo">No se puede expedir sin ${falta.join(', ')}. Corrige la ficha primero.</div>` : ''}
    </div>`;
}

function certModal() {
  let m = $('cert-modal');
  if (m) return m;
  m = document.createElement('div');
  m.id = 'cert-modal'; m.className = 'modal'; m.hidden = true;
  m.innerHTML = `<div class="modal-card cert-card">
    <div class="modal-head"><h3>📄 Certificado laboral</h3><span class="spacer"></span>
      <button type="button" class="icon-btn" data-x aria-label="Cerrar">✕</button></div>
    <div class="cert-aviso" data-aviso hidden></div>
    <div class="cert-paso" data-paso1><div class="loading">Cargando…</div></div>
    <div class="cert-paso cert-prev" data-paso2 hidden></div>
    <div class="modal-foot">
      <button type="button" class="btn btn-sm" data-volver hidden>← Cambiar</button>
      <span class="spacer"></span>
      <button type="button" class="btn btn-primary" data-imprimir hidden>🖨️ Imprimir / Guardar PDF</button>
      <button type="button" class="btn" data-x>Cerrar</button>
    </div>
  </div>`;
  m.addEventListener('click', (e) => {
    if (e.target === m || e.target.closest('[data-x]')) { m.hidden = true; return; }
    const s = e.target.closest('[data-sal]');
    if (s) { _certSal = s.dataset.sal === '1'; certPaso(2); return; }
    if (e.target.closest('[data-volver]')) { certPaso(1); return; }
    if (e.target.closest('[data-imprimir]')) certImprimir();
  });
  document.body.appendChild(m);
  return m;
}

function certOpciones() {
  const m = certModal();
  const dir = m.querySelector('[data-dir]');
  return {
    conSalario: _certSal === true,
    conAuxilio: _certSal === true,
    dirigidoA: dir ? dir.value.trim() : '',
    logo: _certLogo || '',
  };
}
let _certLogo = '';

// Cambia entre revisar (1) y ver el documento ya armado (2).
function certPaso(n) {
  const m = certModal();
  m.querySelector('[data-paso1]').hidden = n !== 1;
  m.querySelector('[data-paso2]').hidden = n !== 2;
  m.querySelector('[data-volver]').hidden = n !== 2;
  m.querySelector('[data-imprimir]').hidden = n !== 2;
  if (n === 2) certPintar();
}

function certPintar() {
  if (!_certRow || !_certCfg) return;
  const prev = certModal().querySelector('[data-paso2]');
  prev.innerHTML = `<style>${CERT_CSS}</style>` + certDocHtml(_certRow, _certCfg, certOpciones());
}

async function openCertificado(row) {
  if (!isTalentoHumano() || !row) return;
  _certRow = row; _certSal = null;
  const m = certModal();
  m.hidden = false;
  certPaso(1);
  const p1 = m.querySelector('[data-paso1]');
  p1.innerHTML = '<div class="loading">Cargando…</div>';
  const aviso = m.querySelector('[data-aviso]');
  try {
    const [cfg] = await Promise.all([certLeerConfig(), certLogoDataUri().then((d) => { _certLogo = d; })]);
    if (!cfg || !cfg.ok) throw new Error('falta ejecutar sql/93 o no tienes permiso');

    const LBL = { firmante1_nombre: 'quién firma', telefono: 'el teléfono de contacto',
      smmlv: 'el salario mínimo del año', auxilio_transporte: 'el auxilio de transporte' };
    const falta = cfg.falta || [];
    aviso.hidden = !falta.length;
    if (falta.length) {
      aviso.innerHTML = `⚠️ Falta configurar ${falta.map((f) => LBL[f] || f).join(', ')}. `
        + 'El certificado sale igual, pero sin esos datos.';
    }

    const puede = !!(row.nombre && row.cedula && row.fecha_ingreso);
    const haySalario = !!row.salario;
    p1.innerHTML = certRevisionHtml(row, cfg) + (puede ? `
      <div class="cert-preg">
        <div class="cert-preg-t">¿El certificado debe incluir el salario?</div>
        <div class="cert-preg-b">
          <button type="button" class="btn btn-primary" data-sal="1"${haySalario ? '' : ' disabled'}>💰 Sí, con salario</button>
          <button type="button" class="btn" data-sal="0">🔒 No, sin salario</button>
        </div>
        <div class="pst-nota">${haySalario
    ? 'Con salario es lo que piden bancos y arrendadores. Sin salario sirve para trámites donde no hay que revelarlo.'
    : 'Esta persona no tiene salario en la ficha, así que solo se puede expedir sin salario.'}</div>
        <label class="cert-dir">Con destino a
          <input type="text" data-dir placeholder="(opcional) banco, entidad…" maxlength="80">
        </label>
      </div>` : '');
  } catch (e) {
    p1.innerHTML = `<div class="rst-empty">No se pudo preparar el certificado: ${esc(String(e.message || e))}</div>`;
  }
}

// Imprimir: primero se registra (para que el documento salga con su consecutivo), luego se abre.
async function certImprimir() {
  if (!_certRow || !_certCfg) return;
  const m = certModal(), btn = m.querySelector('[data-imprimir]');
  const o = certOpciones();
  btn.disabled = true; const prev = btn.textContent; btn.textContent = '⏳ Generando…';
  try {
    let consecutivo = '';
    try {
      const { data } = await sb.rpc('certificado_registrar', {
        p_cedula: _certRow.cedula, p_con_salario: o.conSalario, p_dirigido_a: o.dirigidoA || null });
      if (data?.ok) consecutivo = data.consecutivo || '';
    } catch { /* si la bitácora falla, el certificado se imprime igual */ }

    const w = window.open('', '_blank');
    if (!w) { toast('Permite las ventanas emergentes para imprimir.', 'err'); return; }
    w.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8">`
      + `<title>Certificado laboral${consecutivo ? ' ' + consecutivo : ''}</title>`
      + `<style>${CERT_CSS}</style></head><body>`
      + certDocHtml(_certRow, _certCfg, { ...o, consecutivo })
      + `<script>window.onload=function(){window.print()}<\/script></body></html>`);
    w.document.close();
  } catch (e) {
    toast('No se pudo generar: ' + (e.message || e), 'err');
  } finally { btn.disabled = false; btn.textContent = prev; }
}


// ===================================================================================
// ✍️ FIRMAS DEL CERTIFICADO (sql/94) — quién firma, desde cuándo, y su firma escaneada.
// Cada firma es un CARGO con titular vigente: cuando entra otra persona, a la anterior se le
// cierra la vigencia y el certificado empieza a salir con el nuevo nombre sin tocar nada más.
// La foto de la firma se limpia aquí mismo (fondo del papel → transparente) y se recorta, que es
// lo que evita tener que acomodarla a mano en cada documento.
// ===================================================================================
const CF_ROLES = [
  { rol: 'GERENTE', icono: '👔', titulo: 'Gerente General', cargo: 'Gerente General' },
  { rol: 'GESTION_HUMANA', icono: '🧾', titulo: 'Gestión Humana', cargo: 'Coordinador de Gestión Humana' },
];
const _cf = { datos: null, cfg: null, sug: null, edit: {}, src: {} }; // edit = lo que se está tocando; src = la foto sin procesar

// Deja el trazo y vuelve transparente el papel; después recorta el sobrante.
// `umbral` es qué tan claro tiene que ser un punto para considerarlo fondo (0-255).
function cfLimpiarFirma(srcDataUrl, umbral) {
  return new Promise((res) => {
    const img = new Image();
    img.onload = () => {
      try {
        const factor = Math.min(1, 700 / (img.naturalWidth || 700));
        const w = Math.max(1, Math.round((img.naturalWidth || 700) * factor));
        const h = Math.max(1, Math.round((img.naturalHeight || 300) * factor));
        const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
        const cx = cv.getContext('2d');
        cx.drawImage(img, 0, 0, w, h);
        const dat = cx.getImageData(0, 0, w, h), p = dat.data;
        let x0 = w, y0 = h, x1 = -1, y1 = -1;
        for (let i = 0, px = 0; i < p.length; i += 4, px++) {
          if ((p[i] + p[i + 1] + p[i + 2]) / 3 >= umbral) { p[i + 3] = 0; continue; }
          p[i] = p[i + 1] = p[i + 2] = 20; // el trazo, en tinta pareja
          const y = (px / w) | 0, x = px % w;
          if (x < x0) x0 = x;
          if (x > x1) x1 = x;
          if (y < y0) y0 = y;
          if (y > y1) y1 = y;
        }
        cx.putImageData(dat, 0, 0);
        if (x1 < 0) { res(''); return; } // no quedó nada: el umbral se comió la firma
        const m = 4;
        x0 = Math.max(0, x0 - m); y0 = Math.max(0, y0 - m);
        x1 = Math.min(w - 1, x1 + m); y1 = Math.min(h - 1, y1 + m);
        const cw = x1 - x0 + 1, ch = y1 - y0 + 1;
        const out = document.createElement('canvas'); out.width = cw; out.height = ch;
        out.getContext('2d').drawImage(cv, x0, y0, cw, ch, 0, 0, cw, ch);
        res(out.toDataURL('image/png'));
      } catch { res(''); }
    };
    img.onerror = () => res('');
    img.src = srcDataUrl;
  });
}

function cfModal() {
  let m = $('cf-modal');
  if (m) return m;
  m = document.createElement('div');
  m.id = 'cf-modal'; m.className = 'modal'; m.hidden = true;
  m.innerHTML = `<div class="modal-card cf-card">
    <div class="modal-head"><h3>✍️ Firmas del certificado</h3><span class="spacer"></span>
      <button type="button" class="icon-btn" data-x aria-label="Cerrar">✕</button></div>
    <div class="cf-body"><div class="loading">Cargando…</div></div>
    <div class="modal-foot"><span class="spacer"></span>
      <button type="button" class="btn" data-x>Cerrar</button></div>
  </div>`;
  m.addEventListener('click', (e) => { if (e.target === m || e.target.closest('[data-x]')) m.hidden = true; });
  document.body.appendChild(m);
  return m;
}

async function openCertFirmas() {
  if (!isTalentoHumano()) return;
  const m = cfModal();
  m.hidden = false; closeMenu();
  const body = m.querySelector('.cf-body');
  body.innerHTML = '<div class="loading">Cargando…</div>';
  try {
    const [r1, r2, r3] = await Promise.all([
      sb.rpc('certificado_firmantes_listar'), sb.rpc('certificado_config_leer'),
      // el builder de supabase es "thenable", no una promesa: no tiene .catch
      sb.rpc('certificado_firmantes_sugerir').then((x) => x, () => ({ data: null }))]);
    if (r1.error) throw r1.error;
    const data = r1.data;
    if (!data || !data.ok) throw new Error('falta ejecutar sql/94 o no tienes permiso');
    _cf.datos = data; _cf.cfg = (r2.data && r2.data.ok) ? r2.data : {};
    _cf.sug = (r3 && r3.data && r3.data.ok) ? r3.data : {};   // candidatos del perfil (sql/96)
    _cf.edit = {}; _cf.src = {};
    CF_ROLES.forEach((r) => {
      const v = (data.vigentes || {})[r.rol] || null;
      _cf.edit[r.rol] = {
        hay: !!v,
        nombre: v ? v.nombre : '',
        cargo: v ? v.cargo : r.cargo,
        firma: v ? (v.firma || '') : '',
        alto: v ? Number(v.firma_alto || 58) : 58,
        dx: v ? Number(v.firma_dx || 0) : 0,
        dy: v ? Number(v.firma_dy || 0) : 0,
        desde: v ? v.vigente_desde : null,
        umbral: 195,
        cambio: !v, // sin titular, guardar siempre crea uno
      };
    });
    cfRender();
  } catch (e) {
    body.innerHTML = `<div class="rst-empty">No se pudo cargar: ${esc(String(e.message || e))}</div>`;
  }
}

function cfRender() {
  const body = cfModal().querySelector('.cf-body');
  const puede = !!(_cf.datos && _cf.datos.puede_editar);
  body.innerHTML = `
    <div class="cf-intro">Estas dos firmas salen en <b>todos</b> los certificados laborales.
      Cuando entra otra persona al cargo no se borra la anterior: se registra desde cuándo firma
      la nueva, y el certificado se actualiza solo.</div>
    ${puede ? '' : '<div class="cert-bloqueo">Puedes consultarlas, pero solo administración las cambia.</div>'}
    <div class="cf-grid">${CF_ROLES.map((r) => cfTarjetaHtml(r, puede)).join('')}</div>
    ${cfDatosHtml(puede)}
    ${cfHistorialHtml()}`;
  CF_ROLES.forEach((r) => cfConectar(r, puede));
  cfConectarDatos(puede);
}

function cfTarjetaHtml(r, puede) {
  const e = _cf.edit[r.rol];
  return `
  <section class="cf-card-f" data-rol="${r.rol}">
    <header class="cf-h"><span class="cf-ic">${r.icono}</span>
      <div><h4>${esc(r.titulo)}</h4>
        <div class="pst-nota">${e.hay && e.desde ? 'Firma desde el ' + esc(fechaLegible(e.desde))
    : 'Todavía no hay nadie asignado'}</div></div>
    </header>
    <label class="cf-l">Nombre de quien firma
      <input type="text" data-nombre value="${esc(e.nombre)}" maxlength="80" ${puede ? '' : 'disabled'}
        placeholder="Nombre completo, como debe aparecer"></label>
    ${cfSugerencias(r.rol, puede)}
    <label class="cf-l">Cargo
      <input type="text" data-cargo value="${esc(e.cargo)}" maxlength="60" ${puede ? '' : 'disabled'}></label>

    <div class="cf-firma-zona">
      <div class="cf-prev" data-prev></div>
      <div class="cf-acc">
        <label class="btn btn-sm cf-file">📷 Subir foto de la firma
          <input type="file" accept="image/*" data-file hidden ${puede ? '' : 'disabled'}></label>
        <button type="button" class="btn btn-sm" data-quitar ${puede ? '' : 'disabled'}>🗑️ Quitar</button>
      </div>
      <div class="cf-ajustes" data-ajustes${e.firma ? '' : ' hidden'}>
        <label class="cf-r">Limpiar el papel
          <input type="range" min="120" max="245" step="5" value="${e.umbral}" data-umbral ${puede ? '' : 'disabled'}>
          <span class="pst-nota">Súbelo si queda fondo gris; bájalo si se borran trazos.</span></label>
        <label class="cf-r">Tamaño
          <input type="range" min="26" max="120" step="2" value="${e.alto}" data-alto ${puede ? '' : 'disabled'}></label>
        <label class="cf-r">Mover a los lados
          <input type="range" min="-90" max="90" step="2" value="${e.dx}" data-dx ${puede ? '' : 'disabled'}></label>
        <label class="cf-r">Subir o bajar
          <input type="range" min="-50" max="50" step="2" value="${e.dy}" data-dy ${puede ? '' : 'disabled'}></label>
      </div>
    </div>

    <div class="cf-guardar">
      <label class="pf-sw"><input type="checkbox" data-cambio ${e.cambio ? 'checked' : ''}
        ${e.hay && puede ? '' : 'disabled'}> Entra otra persona al cargo</label>
      <label class="cf-desde" data-desdewrap${e.cambio ? '' : ' hidden'}>Firma desde
        <input type="date" data-desde value="${hoyServidor()}" ${puede ? '' : 'disabled'}></label>
      <div class="cf-btns">
        <button type="button" class="btn btn-primary btn-sm" data-guardar ${puede ? '' : 'disabled'}>💾 Guardar</button>
        <span class="pst-nota" data-msg></span>
      </div>
    </div>
  </section>`;
}

// Lo que cambia cada ano y hace que el certificado salga completo. Estaba solo en la base;
// aqui lo mantiene quien expide los certificados, sin tener que pedir un SQL cada enero.
function cfDatosHtml(puede) {
  const c = _cf.cfg || {};
  const campo = (k, etiqueta, valor, tipo, nota) => `<label class="cf-l">${esc(etiqueta)}
      <input type="${tipo}" data-cfg="${k}" value="${valor == null ? '' : esc(String(valor))}"
        ${puede ? '' : 'disabled'}>${nota ? `<span class="pst-nota">${esc(nota)}</span>` : ''}</label>`;
  return `<div class="cf-datos">
    <h4>Datos que salen en el certificado</h4>
    <div class="cf-datos-g">
      ${campo('telefono', 'Tel\u00e9fono de contacto', c.telefono, 'text', 'El que se imprime en "cualquier informaci\u00f3n\u2026"')}
      ${campo('ciudad', 'Ciudad', c.ciudad, 'text')}
      ${campo('anio_valores', 'A\u00f1o de estos valores', c.anio_valores, 'number')}
      ${campo('smmlv', 'Salario m\u00ednimo del a\u00f1o', c.smmlv, 'number', 'Si el sueldo coincide, se nombra como "salario m\u00ednimo legal vigente".')}
      ${campo('auxilio_transporte', 'Auxilio de transporte', c.auxilio_transporte, 'number', 'Solo se imprime para quien gana hasta 2 salarios m\u00ednimos.')}
    </div>
    ${puede ? `<div class="cf-btns">
      <button type="button" class="btn btn-primary btn-sm" data-cfg-guardar>\ud83d\udcbe Guardar estos datos</button>
      <span class="pst-nota" data-cfg-msg></span></div>` : ''}
  </div>`;
}

function cfConectarDatos(puede) {
  if (!puede) return;
  const m = cfModal();
  const btn = m.querySelector('[data-cfg-guardar]');
  if (!btn) return;
  const msg = m.querySelector('[data-cfg-msg]');
  btn.addEventListener('click', async () => {
    const p = {};
    m.querySelectorAll('[data-cfg]').forEach((el) => {
      const v = el.value.trim();
      if (v !== '') p[el.dataset.cfg] = el.type === 'number' ? Number(v) : v;
    });
    btn.disabled = true; msg.textContent = 'Guardando\u2026';
    try {
      const { data, error } = await sb.rpc('certificado_config_guardar', { p });
      if (error) throw error;
      if (!data?.ok) throw new Error(data?.error || 'no se pudo guardar');
      toast('Datos del certificado guardados.', 'ok');
      _certCfg = null;              // el certificado vuelve a leerlos
      await openCertFirmas();
    } catch (e) {
      msg.textContent = 'No se pudo guardar: ' + (e.message || e);
      btn.disabled = false;
    }
  });
}

// Candidatos sacados del perfil: quien configura solo confirma, no teclea el nombre.
function cfSugerencias(rol, puede) {
  if (!puede) return '';
  const lista = ((_cf.sug || {})[rol] || []).slice(0, 6);
  if (!lista.length) return '';
  const e = _cf.edit[rol];
  return `<div class="cf-sug">
    <span class="pst-nota">Del perfil${e.nombre ? ', por si cambi\u00f3' : ''}:</span>
    ${lista.map((c, i) => `<button type="button" class="cf-sug-b" data-sug="${i}"
      title="${esc(c.cargo || '')}">${esc(c.nombre)}</button>`).join('')}
  </div>`;
}

function cfHistorialHtml() {
  const h = (_cf.datos && _cf.datos.historial) || [];
  if (!h.length) return '';
  const nom = { GERENTE: 'Gerente General', GESTION_HUMANA: 'Gestión Humana' };
  return `<div class="cf-hist">
    <h4>Quién firmaba antes</h4>
    ${h.map((x) => `<div class="cf-hist-it"><b>${esc(x.nombre)}</b> · ${esc(nom[x.rol] || x.rol)}
      · del ${esc(fechaLegible(x.desde))} al ${esc(fechaLegible(x.hasta))}
      ${x.tiene_firma ? ' · tenía firma cargada' : ''}</div>`).join('')}
  </div>`;
}

// Así se va a ver impreso: la firma sobre la línea, con el nombre y el cargo debajo.
function cfPintarPrev(rol) {
  const e = _cf.edit[rol];
  const cont = cfModal().querySelector(`[data-rol="${rol}"] [data-prev]`);
  if (!cont) return;
  cont.innerHTML = e.firma
    ? `<img src="${e.firma}" alt="" style="height:${e.alto}px;transform:translate(${e.dx}px,${e.dy}px)">`
    : '<div class="cf-sin">Sin firma cargada: el certificado imprime la línea para firmar a mano.</div>';
  const linea = document.createElement('div');
  linea.className = 'cf-linea';
  linea.innerHTML = `<div class="cf-linea-n">${esc(e.nombre || '—')}</div>
    <div class="cf-linea-c">${esc(e.cargo || '')}</div>`;
  cont.appendChild(linea);
}

function cfConectar(r, puede) {
  const card = cfModal().querySelector(`[data-rol="${r.rol}"]`);
  const e = _cf.edit[r.rol];
  const q = (sel) => card.querySelector(sel);
  const msg = q('[data-msg]');
  cfPintarPrev(r.rol);
  if (!puede) return;

  card.querySelectorAll('[data-sug]').forEach((b) => b.addEventListener('click', () => {
    const c = ((_cf.sug || {})[r.rol] || [])[Number(b.dataset.sug)];
    if (!c) return;
    e.nombre = c.nombre;
    q('[data-nombre]').value = c.nombre;
    if (c.cargo) { e.cargo = c.cargo; q('[data-cargo]').value = c.cargo; }
    cfPintarPrev(r.rol);
    msg.textContent = 'Nombre tomado del perfil. Revisa el cargo y guarda.';
  }));

  q('[data-nombre]').addEventListener('input', (ev) => { e.nombre = ev.target.value; cfPintarPrev(r.rol); });
  q('[data-cargo]').addEventListener('input', (ev) => { e.cargo = ev.target.value; cfPintarPrev(r.rol); });

  q('[data-file]').addEventListener('change', async (ev) => {
    const f = ev.target.files && ev.target.files[0];
    if (!f) return;
    if (f.size > 8 * 1024 * 1024) { msg.textContent = 'La foto pesa demasiado (máximo 8 MB).'; return; }
    msg.textContent = 'Procesando la foto…';
    const crudo = await new Promise((res) => {
      const fr = new FileReader(); fr.onload = () => res(fr.result); fr.onerror = () => res(''); fr.readAsDataURL(f);
    });
    if (!crudo) { msg.textContent = 'No se pudo leer la imagen.'; return; }
    _cf.src[r.rol] = crudo;
    await cfReprocesar(r.rol);
    q('[data-ajustes]').hidden = false;
    msg.textContent = e.firma ? 'Lista. Ajusta el tamaño y la posición, y guarda.' : 'No se distingue la firma: prueba subiendo "Limpiar el papel".';
    ev.target.value = '';
  });

  q('[data-quitar]').addEventListener('click', () => {
    e.firma = ''; _cf.src[r.rol] = '';
    q('[data-ajustes]').hidden = true;
    cfPintarPrev(r.rol);
    msg.textContent = 'Firma quitada. Guarda para que quede así.';
  });

  q('[data-umbral]').addEventListener('input', async (ev) => {
    e.umbral = Number(ev.target.value);
    if (_cf.src[r.rol]) await cfReprocesar(r.rol);
  });
  q('[data-alto]').addEventListener('input', (ev) => { e.alto = Number(ev.target.value); cfPintarPrev(r.rol); });
  q('[data-dx]').addEventListener('input', (ev) => { e.dx = Number(ev.target.value); cfPintarPrev(r.rol); });
  q('[data-dy]').addEventListener('input', (ev) => { e.dy = Number(ev.target.value); cfPintarPrev(r.rol); });

  q('[data-cambio]').addEventListener('change', (ev) => {
    e.cambio = ev.target.checked;
    q('[data-desdewrap]').hidden = !e.cambio;
  });

  q('[data-guardar]').addEventListener('click', () => cfGuardar(r, card, msg));
}

async function cfReprocesar(rol) {
  const e = _cf.edit[rol];
  if (!_cf.src[rol]) return;
  e.firma = await cfLimpiarFirma(_cf.src[rol], e.umbral);
  cfPintarPrev(rol);
}

async function cfGuardar(r, card, msg) {
  const e = _cf.edit[r.rol];
  const btn = card.querySelector('[data-guardar]');
  if (!e.nombre.trim() || !e.cargo.trim()) { msg.textContent = 'Escribe el nombre y el cargo.'; return; }
  if (e.firma && e.firma.length > 900000) {
    msg.textContent = 'La firma quedó muy pesada: recorta la foto antes de subirla.'; return;
  }
  btn.disabled = true; msg.textContent = 'Guardando…';
  try {
    let resp;
    if (e.cambio || !e.hay) {
      const desde = card.querySelector('[data-desde]').value || null;
      resp = await sb.rpc('certificado_firmante_cambiar', {
        p_rol: r.rol, p_nombre: e.nombre.trim(), p_cargo: e.cargo.trim(), p_desde: desde,
        p_firma: e.firma || null, p_alto: e.alto, p_dx: e.dx, p_dy: e.dy });
    } else {
      resp = await sb.rpc('certificado_firmante_actualizar', {
        p_rol: r.rol, p_nombre: e.nombre.trim(), p_cargo: e.cargo.trim(),
        p_firma: e.firma === '' ? '' : (e.firma || null), p_alto: e.alto, p_dx: e.dx, p_dy: e.dy });
    }
    if (resp.error) throw resp.error;
    if (!resp.data?.ok) throw new Error(resp.data?.error || 'no se pudo guardar');
    toast('Firma guardada.', 'ok');
    _certCfg = null; // el certificado vuelve a leer la configuración
    await openCertFirmas();
  } catch (err) {
    const t = String(err.message || err);
    msg.textContent = /certificado_firmante/.test(t) ? 'Falta ejecutar sql/94.' : 'No se pudo guardar: ' + t;
    btn.disabled = false;
  }
}


// ===================================================================================
// 📝 PERMISOS Y LICENCIAS (formato F-GH-07, sql/97)
// El empleado radica en permisos.html (link público). Aquí Gestión Humana y Gerencia deciden,
// y de aquí sale el mismo formato impreso, ya con el estado y quién autorizó — que en el papel
// quedaba en blanco.
// ===================================================================================
let PERM_OK = false, PERM_GH = false, PERM_GER = false, PERM_MIOS = 0;
const _perm = { rows: [], vista: 'decidir', q: '', abierto: null };
const PERM_VISTAS = [
  { key: 'decidir', label: 'Por decidir' },
  { key: 'PENDIENTE', label: 'Pendientes' },
  { key: 'APROBADO', label: 'Aprobados' },
  { key: 'NEGADO', label: 'Negados' },
  { key: 'todos', label: 'Todos' },
];
const PERM_CHIP = { PENDIENTE: 'chip-amber', 'EN TRAMITE': 'chip-blue', APROBADO: 'chip-green',
  NEGADO: 'chip-red', ANULADO: 'chip-gray' };

async function refrescarPermisos(rebuild = true) {
  try {
    const { data } = await sb.rpc('permisos_estado');
    PERM_OK = !!(data && data.ok);
    PERM_GH = !!(data && data.es_gh);
    PERM_GER = !!(data && data.es_gerencia);
    PERM_MIOS = Number((data && data.mios) || 0);
  } catch { PERM_OK = false; PERM_GH = false; PERM_GER = false; PERM_MIOS = 0; }
  if (rebuild) buildSidebar();
}

function permLinkUrl() { return new URL('permisos.html', location.href).href; }

// Cuánto duró, dicho como lo diría una persona.
function permDuracion(r) {
  const h = Number(r.horas || 0);
  if (!h) return '—';
  if (h < 24) return `${h % 1 ? h.toFixed(1) : h} hora(s)`;
  const d = h / 24;
  return `${d % 1 ? d.toFixed(1) : d} día(s)`;
}
const permFechaHora = (v) => {
  if (!v) return '—';
  const s = String(v).replace('T', ' ');
  return `${fechaLegible(s.slice(0, 10))} ${s.slice(11, 16)}`;
};

function permModal() {
  let m = $('perm-modal');
  if (m) return m;
  m = document.createElement('div');
  m.id = 'perm-modal'; m.className = 'modal'; m.hidden = true;
  m.innerHTML = `<div class="modal-card perm-card">
    <div class="modal-head"><h3>📝 Permisos y licencias</h3><span class="spacer"></span>
      <button type="button" class="icon-btn" data-x aria-label="Cerrar">✕</button></div>
    <div class="asp-toolbar">
      <div class="asp-vistas">${PERM_VISTAS.map((v) =>
    `<button type="button" class="btn btn-sm" data-vista="${v.key}">${v.label} <b data-n="${v.key}"></b></button>`).join('')}</div>
      <input type="search" class="asp-q" placeholder="🔎 Nombre, cédula o radicado" aria-label="Buscar">
      <span class="spacer"></span>
      <button type="button" class="btn btn-sm" data-link>🔗 Link para el empleado</button>
      <button type="button" class="btn btn-sm" data-excel>⬇️ Excel</button>
      <button type="button" class="btn btn-sm" data-recargar title="Recargar" aria-label="Recargar">🔄</button>
    </div>
    <div class="perm-body"><div class="loading">Cargando…</div></div>
  </div>`;
  m.addEventListener('click', (e) => {
    if (e.target === m || e.target.closest('[data-x]')) { m.hidden = true; return; }
    const v = e.target.closest('[data-vista]');
    if (v) { _perm.vista = v.dataset.vista; renderPermisos(); return; }
    if (e.target.closest('[data-link]')) { permCopiarLink(); return; }
    const x = e.target.closest('[data-excel]'); if (x) { exportarPermisos(x); return; }
    if (e.target.closest('[data-recargar]')) { cargarPermisos(); return; }
    const t = e.target.closest('[data-perm]'); if (t) openPermiso(Number(t.dataset.perm));
  });
  m.querySelector('.asp-q').addEventListener('input', (e) => { _perm.q = e.target.value; renderPermisos(); });
  document.body.appendChild(m);
  return m;
}

async function openPermisos() {
  if (!PERM_OK) { toast('No tienes permiso para ver las solicitudes.', 'err'); return; }
  permModal().hidden = false;
  closeMenu();
  await cargarPermisos();
}

async function cargarPermisos() {
  const body = permModal().querySelector('.perm-body');
  if (!_perm.rows.length) body.innerHTML = '<div class="loading">Cargando…</div>';
  try {
    const { data, error } = await sb.from('permisos').select('*').order('radicado', { ascending: false }).limit(2000);
    if (error) throw error;
    _perm.rows = data || [];
    renderPermisos();
    refrescarPermisos();
  } catch (e) {
    body.innerHTML = `<div class="rst-empty">No se pudo cargar: ${esc(String(e.message || e))}</div>`;
  }
}

// Lo que ESTA cuenta todavía no ha decidido: es la vista con la que se entra a trabajar.
function permMeFalta(r) {
  if (r.estado === 'ANULADO') return false;
  return (PERM_GH && !r.gh_estado) || (PERM_GER && !r.ger_estado);
}

function renderPermisos() {
  const m = permModal(), body = m.querySelector('.perm-body');
  const q = _perm.q.trim().toLowerCase();
  const todas = _perm.rows;
  const cuenta = {
    decidir: todas.filter(permMeFalta).length,
    PENDIENTE: todas.filter((r) => r.estado === 'PENDIENTE' || r.estado === 'EN TRAMITE').length,
    APROBADO: todas.filter((r) => r.estado === 'APROBADO').length,
    NEGADO: todas.filter((r) => r.estado === 'NEGADO').length,
    todos: todas.length,
  };
  PERM_VISTAS.forEach((v) => {
    const b = m.querySelector(`[data-n="${v.key}"]`); if (b) b.textContent = cuenta[v.key] || '';
    const btn = m.querySelector(`[data-vista="${v.key}"]`);
    if (btn) btn.classList.toggle('btn-primary', _perm.vista === v.key);
  });

  let rows = _perm.vista === 'decidir' ? todas.filter(permMeFalta)
    : _perm.vista === 'todos' ? todas
      : _perm.vista === 'PENDIENTE' ? todas.filter((r) => r.estado === 'PENDIENTE' || r.estado === 'EN TRAMITE')
        : todas.filter((r) => r.estado === _perm.vista);
  if (q) {
    rows = rows.filter((r) => [r.nombre, r.cedula, String(r.radicado), r.tipo, r.area, r.cargo]
      .some((v) => String(v || '').toLowerCase().includes(q)));
  }

  if (!rows.length) {
    body.innerHTML = `<div class="rst-empty">${_perm.vista === 'decidir'
      ? 'No tienes solicitudes por decidir. 👏' : 'No hay solicitudes en esta vista.'}</div>`;
    return;
  }

  const tabla = pstEl('table', 'pst-tabla');
  const cab = ['#', 'Empleado', 'Cargo / área', 'Tipo', 'Desde', 'Hasta', 'Duración', 'Repone', 'G. Humana', 'Gerencia', 'Estado'];
  const thead = pstEl('thead'); const tr = pstEl('tr');
  cab.forEach((c) => tr.appendChild(pstEl('th', null, c)));
  thead.appendChild(tr); tabla.appendChild(thead);
  const tb = pstEl('tbody');
  const marca = (v) => v === 'APROBADO' ? '✅' : v === 'NEGADO' ? '⛔' : '⏳';
  rows.forEach((r) => {
    const f = pstEl('tr');
    f.dataset.perm = r.id;
    [`${r.radicado}`, r.nombre || '—', `${r.cargo || '—'}${r.area ? ' · ' + r.area : ''}`,
      r.tipo || '—', permFechaHora(r.desde), permFechaHora(r.hasta), permDuracion(r),
      r.reposicion ? 'Sí' : 'No', marca(r.gh_estado), marca(r.ger_estado)]
      .forEach((v) => f.appendChild(pstEl('td', null, v)));
    const td = pstEl('td');
    td.innerHTML = `<span class="chip ${PERM_CHIP[r.estado] || 'chip-gray'}">${esc(r.estado)}</span>`;
    f.appendChild(td);
    f.classList.add('pst-clic'); f.tabIndex = 0; f.title = 'Abrir la solicitud';
    f.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); openPermiso(r.id); } });
    tb.appendChild(f);
  });
  tabla.appendChild(tb);
  body.innerHTML = '';
  const wrap = pstEl('div', 'pst-tabla-wrap perm-tabla');
  wrap.appendChild(tabla);
  body.appendChild(wrap);
}

// ---- Ficha de una solicitud ----
async function openPermiso(id) {
  const r = _perm.rows.find((x) => x.id === id);
  if (!r) return;
  _perm.abierto = r;
  let m = $('permf-modal');
  if (!m) {
    m = document.createElement('div');
    m.id = 'permf-modal'; m.className = 'modal'; m.hidden = true;
    m.innerHTML = `<div class="modal-card perm-ficha">
      <div class="modal-head"><h3>📝 Solicitud</h3><span class="spacer"></span>
        <button type="button" class="icon-btn" data-x aria-label="Cerrar">✕</button></div>
      <div class="permf-body"></div>
      <div class="modal-foot">
        <button type="button" class="btn btn-sm" data-imprimir>🖨️ Imprimir formato</button>
        <span class="spacer"></span>
        <button type="button" class="btn" data-x>Cerrar</button>
      </div>
    </div>`;
    m.addEventListener('click', (e) => { if (e.target === m || e.target.closest('[data-x]')) m.hidden = true; });
    m.querySelector('[data-imprimir]').addEventListener('click', () => permImprimir(_perm.abierto));
    document.body.appendChild(m);
  }
  const body = m.querySelector('.permf-body');
  m.querySelector('h3').textContent = `📝 Radicado # ${r.radicado}`;
  body.innerHTML = permFichaHtml(r) + '<div class="loading">Cargando soportes…</div>';
  m.hidden = false;
  permConectarFicha(body, r);

  try {
    const { data } = await sb.rpc('permiso_soportes_de', { p_id: r.id });
    const cont = body.querySelector('.loading');
    if (!cont) return;
    const lista = data || [];
    cont.outerHTML = lista.length
      ? `<h4 class="pqr-h">Soportes (${lista.length})</h4><div class="perm-sops">${lista.map((s) => {
        const esImg = String(s.tipo_mime || '').startsWith('image/');
        return `<a href="${s.archivo}" target="_blank" rel="noopener" class="perm-sop" title="${esc(s.nombre || '')}">
            ${esImg ? `<img src="${s.archivo}" alt="">` : '<span class="perm-pdf">📄 PDF</span>'}
            <span>${esc((s.nombre || 'soporte').slice(0, 26))}</span></a>`;
      }).join('')}</div>`
      : '<div class="pst-nota">No adjuntó soportes.</div>';
  } catch {
    const c = body.querySelector('.loading');
    if (c) c.outerHTML = '<div class="pst-nota">No se pudieron cargar los soportes.</div>';
  }
}

function permFichaHtml(r) {
  const T = (PERMISO_TIPOS || []).find((t) => t.key === r.tipo);
  const decision = (titulo, estado, por, en, nota) => `
    <div class="perm-dec ${estado === 'APROBADO' ? 'ok' : estado === 'NEGADO' ? 'no' : ''}">
      <div class="perm-dec-t">${esc(titulo)}</div>
      <div class="perm-dec-e">${estado ? esc(estado) : 'Sin decidir'}</div>
      ${por ? `<div class="pst-nota">${esc(por)} · ${esc(evbCuando(en))}</div>` : ''}
      ${nota ? `<div class="perm-dec-n">${esc(nota)}</div>` : ''}
    </div>`;

  return `
    <header class="pf-top">
      <div class="pf-av ${r.estado === 'APROBADO' ? 'cond' : 'adm'}">${esc(String(r.radicado))}</div>
      <div class="pf-idt">
        <h2>${esc(r.nombre || '')}</h2>
        <div class="pf-sub">C.C. ${esc(r.cedula || '')}${r.cargo ? ' · ' + esc(r.cargo) : ''}${r.area ? ' · ' + esc(r.area) : ''}</div>
        <div class="pf-chips">
          <span class="chip chip-indigo">${esc(r.tipo || '')}</span>
          <span class="chip ${PERM_CHIP[r.estado] || 'chip-gray'}">${esc(r.estado)}</span>
          ${r.reposicion ? '<span class="chip chip-blue">Repone el tiempo</span>' : ''}
        </div>
      </div>
    </header>
    <div class="pf-secs">
      ${sinBloque('🕐 El permiso', [['Desde', esc(permFechaHora(r.desde))], ['Hasta', esc(permFechaHora(r.hasta))],
    ['Duración', esc(permDuracion(r))], ['Radicada el', esc(fechaLegible(r.fecha_solicitud))],
    ['Motivo', esc(r.motivo || '')], ['Lo reemplaza', esc(r.reemplaza || '')],
    ['Repone el tiempo', r.reposicion ? 'Sí' : 'No'], ['Cómo lo repone', esc(r.forma_reposicion || '')],
    ['Celular', esc(r.celular || '')]])}
      ${T ? `<section class="pf-sec"><h4>📎 Soportes que exige este permiso</h4>
        <ul class="perm-req">${T.soportes.map((s) => `<li>${esc(s)}</li>`).join('')}</ul></section>` : ''}
    </div>
    <h4 class="pqr-h">Estado del permiso</h4>
    <div class="perm-decs">
      ${decision('Gestión Humana', r.gh_estado, r.gh_por, r.gh_en, r.gh_nota)}
      ${decision('Gerencia', r.ger_estado, r.ger_por, r.ger_en, r.ger_nota)}
    </div>
    ${r.anulado_en ? `<div class="cert-bloqueo">Solicitud anulada por ${esc(r.anulado_por || '')} · ${esc(evbCuando(r.anulado_en))}</div>` : `
    <div class="perm-acciones">
      ${PERM_GH ? `<div class="perm-acc-g"><b>Gestión Humana</b>
        <button type="button" class="btn btn-sm" data-dec="GH:APROBADO">✅ Aprobar</button>
        <button type="button" class="btn btn-sm" data-dec="GH:NEGADO">⛔ Negar</button></div>` : ''}
      ${PERM_GER ? `<div class="perm-acc-g"><b>Gerencia</b>
        <button type="button" class="btn btn-sm" data-dec="GERENCIA:APROBADO">✅ Aprobar</button>
        <button type="button" class="btn btn-sm" data-dec="GERENCIA:NEGADO">⛔ Negar</button></div>` : ''}
      <label class="perm-nota">Observación (opcional)
        <input type="text" data-nota maxlength="200" placeholder="Queda en el formato impreso"></label>
      ${PERM_GH ? '<button type="button" class="btn btn-sm" data-anular>🗑️ Anular solicitud</button>' : ''}
      <span class="pst-nota" data-msg></span>
    </div>`}`;
}

function permConectarFicha(body, r) {
  const msg = body.querySelector('[data-msg]');
  const nota = () => (body.querySelector('[data-nota]') || {}).value || null;
  body.querySelectorAll('[data-dec]').forEach((b) => b.addEventListener('click', async () => {
    const [instancia, estado] = b.dataset.dec.split(':');
    b.disabled = true; msg.textContent = 'Guardando…';
    try {
      const { data, error } = await sb.rpc('permiso_decidir',
        { p_id: r.id, p_instancia: instancia, p_estado: estado, p_nota: nota() });
      if (error) throw error;
      if (!data?.ok) throw new Error(data?.error || 'no se pudo');
      toast(`Solicitud ${estado.toLowerCase()} por ${instancia === 'GH' ? 'Gestión Humana' : 'Gerencia'}.`, 'ok');
      $('permf-modal').hidden = true;
      await cargarPermisos();
    } catch (e) {
      msg.textContent = 'No se pudo: ' + (e.message || e);
      b.disabled = false;
    }
  }));
  const ba = body.querySelector('[data-anular]');
  if (ba) ba.addEventListener('click', async () => {
    if (!confirm('¿Anular esta solicitud? No se borra: queda registrada como anulada.')) return;
    ba.disabled = true;
    try {
      const { data, error } = await sb.rpc('permiso_anular', { p_id: r.id, p_nota: nota() });
      if (error) throw error;
      if (!data?.ok) throw new Error(data?.error || 'no se pudo');
      toast('Solicitud anulada.', 'ok');
      $('permf-modal').hidden = true;
      await cargarPermisos();
    } catch (e) { msg.textContent = 'No se pudo anular: ' + (e.message || e); ba.disabled = false; }
  });
}

// ---- El formato F-GH-07, para imprimir ----
