const _pst = { personas: null, vinc: null, tablas: [] };
// La pantalla de estadísticas la comparten el perfil sociodemográfico y los siniestros:
// esto deja el lienzo listo (cierra lo demás y muestra la vista). Cada módulo pone sus filtros.
function statsPrepararVista() {
  if (mapaFlotante) cerrarMapaFlotante();
  cerrarRecorridoBus();
  cerrarPanelesFlotantes();
  ['table-view', 'map-view', 'cump-view', 'rutas-view', 'malla-view', 'laureles-view', 'integradas-view', 'pasajeros-view',
    'usuarios-view', 'top-view', 'preventivas-view', 'frecuencia-view', 'productividad-view', 'jornada-view']
    .forEach((id) => { const e = $(id); if (e) e.hidden = true; });
  if (mapTimer) { clearInterval(mapTimer); mapTimer = null; }
  if (_rutasTimer) { clearInterval(_rutasTimer); _rutasTimer = null; }
  document.getElementById('app').classList.remove('view-map');
  ocultarVistas('perfilstats-view');
  $('perfilstats-view').hidden = false;
  document.querySelectorAll('#sidebar button').forEach((b) => b.classList.remove('active'));
}
async function openPerfilStats(bloque) {
  if (!isTalentoHumano()) return;
  _pst.bloque = bloque || 'resumen';
  currentView = 'perfilstats';
  statsPrepararVista();
  $('pst-fl-perfil').hidden = false; $('pst-fl-sin').hidden = true; $('pst-fl-pqr').hidden = true;
  $('nav-pst-' + (_pst.bloque || 'resumen'))?.classList.add('active');
  buildBottomNav();
  const b = PST_BLOQUES.find((x) => x.key === _pst.bloque) || PST_BLOQUES[0];
  const tit = $('pst-title'); if (tit) tit.textContent = `${b.icon} ${b.label}`;
  if (!_pst.personas) await cargarPerfilStats(); else renderPerfilStats();
}
function cerrarPerfilStats() { $('perfilstats-view').hidden = true; selectTable(current); }
async function cargarPerfilStats() {
  const body = $('pst-body');
  body.innerHTML = '<div class="loading">Leyendo el perfil sociodemográfico…</div>';
  // Se trae la identificación (id, cédula, nombre…) para poder mostrar QUIÉNES son en cada dato
  const COLS_P = 'id,cedula,nombre,codigo,celular,tipo,estado,sexo,fecha_nacimiento,fecha_ingreso,fecha_retiro,estado_civil,escolaridad,estrato,tipo_vivienda,'
    + 'ciudad,personas_a_cargo,tiene_hijos,convive_pareja,eps,afp,arl,tipo_sangre,uso_lentes,tipo_contrato,cargo,area,salario,'
    + 'categoria_licencia,licencia_vencimiento,estado_restriccion,por_corregir,habeas_data_aceptado_en';
  const leerTodo = async (tabla, cols) => {
    const out = [];
    for (let desde = 0; desde < 50000; desde += 1000) {
      const { data, error } = await sb.from(tabla).select(cols).order('id').range(desde, desde + 999);
      if (error) throw error;
      out.push(...(data || []));
      if (!data || data.length < 1000) break;
    }
    return out;
  };
  try {
    const [personas, vinc] = await Promise.all([
      leerTodo('perfilsociodemografico', COLS_P),
      leerTodo('perfil_vinculaciones', 'cedula,cargo,tipo,area,fecha_ingreso,fecha_retiro'),
    ]);
    _pst.personas = personas; _pst.vinc = vinc;
    // Para ponerle nombre a cada movimiento de rotación (el historial guarda la cédula)
    _pst.porCedula = new Map(personas.map((p) => [String(p.cedula || '').trim(), p]));
    // Áreas reales para el filtro (conserva la elegida)
    const sel = $('pst-area'), prev = sel.value;
    const areas = [...new Set(personas.map((p) => p.area).filter(Boolean))].sort();
    sel.innerHTML = '<option value="">Todas</option>';
    areas.forEach((a) => sel.appendChild(Object.assign(document.createElement('option'), { value: a, textContent: a })));
    if (areas.includes(prev)) sel.value = prev;
    renderPerfilStats();
  } catch (e) {
    body.innerHTML = '';
    body.appendChild(pstEl('div', 'cump-empty', 'No se pudieron leer los datos: ' + (e.message || e)));
  }
}
// ---- utilidades de cálculo ----
function pstEl(tag, cls, text) { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; }
function pstAnios(desde, hasta) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(desde || '')); if (!m) return null;
  const h = hasta ? new Date(String(hasta).slice(0, 10) + 'T12:00:00') : new Date();
  let a = h.getFullYear() - Number(m[1]);
  if (h.getMonth() + 1 < Number(m[2]) || (h.getMonth() + 1 === Number(m[2]) && h.getDate() < Number(m[3]))) a--;
  return a >= 0 && a < 120 ? a : null;
}
const pstNum = (n) => Number(n || 0).toLocaleString('es-CO');
const pstPct = (n, t) => (t ? Math.round((n / t) * 1000) / 10 : 0);
// Cuenta por categoría. opts.orden = lista de categorías en orden fijo (escala ordinal);
// opts.top = deja las N mayores y agrupa el resto en "Otros"; valor vacío = "Sin dato".
function pstContar(rows, fn, opts = {}) {
  const c = new Map(); let sin = 0; const sinQuienes = [];
  for (const r of rows) {
    const v = fn(r);
    if (v == null || String(v).trim() === '') { sin++; sinQuienes.push(r); continue; }
    const k = String(v);
    if (!c.has(k)) c.set(k, { n: 0, quienes: [] });
    const e = c.get(k); e.n++; e.quienes.push(r);
  }
  let items = [...c.entries()].map(([k, e]) => ({ k, n: e.n, quienes: e.quienes }));
  if (opts.orden) {
    const pos = (k) => { const i = opts.orden.indexOf(k); return i < 0 ? 999 : i; };
    items.sort((a, b) => pos(a.k) - pos(b.k) || b.n - a.n);
  } else {
    items.sort((a, b) => b.n - a.n || a.k.localeCompare(b.k));
  }
  if (opts.top && items.length > opts.top) {
    const cola = items.slice(opts.top);
    const resto = cola.reduce((s, i) => s + i.n, 0);
    items = [...items.slice(0, opts.top), { k: `Otros (${cola.length})`, n: resto, otros: true, quienes: cola.flatMap((i) => i.quienes) }];
  }
  return { items, sin, sinQuienes, total: items.reduce((s, i) => s + i.n, 0) };
}
const PST_RANGOS = {
  edad: [[0, 17, 'Menor de 18'], [18, 25, '18 a 25 años'], [26, 35, '26 a 35 años'], [36, 45, '36 a 45 años'],
    [46, 55, '46 a 55 años'], [56, 65, '56 a 65 años'], [66, 200, 'Más de 65 años']],
  antig: [[0, 0, 'Menos de 1 año'], [1, 2, '1 a 2 años'], [3, 5, '3 a 5 años'], [6, 10, '6 a 10 años'],
    [11, 20, '11 a 20 años'], [21, 200, 'Más de 20 años']],
  salario: [[0, 1, 'Hasta 1 SMMLV'], [1, 2, 'Más de 1 a 2 SMMLV'], [2, 3, 'Más de 2 a 3 SMMLV'], [3, 5, 'Más de 3 a 5 SMMLV'],
    [5, 1e9, 'Más de 5 SMMLV']],
};
const pstRango = (val, rangos) => { if (val == null) return null; const r = rangos.find(([a, b]) => val >= a && val <= b); return r ? r[2] : null; };
const pstSalRango = (s) => {
  if (!s) return null;
  const x = Number(s) / PST_SMMLV;
  return x <= 1.0001 ? PST_RANGOS.salario[0][2] : x <= 2 ? PST_RANGOS.salario[1][2] : x <= 3 ? PST_RANGOS.salario[2][2]
    : x <= 5 ? PST_RANGOS.salario[3][2] : PST_RANGOS.salario[4][2];
};
const PST_CAMPOS = { celular: 'Celular', emergencia_telefono1: 'Tel. emergencia 1', emergencia_telefono2: 'Tel. emergencia 2',
  fecha_nacimiento: 'Fecha de nacimiento', salario: 'Salario', fecha_retiro: 'Fecha de retiro', tipo_sangre: 'Tipo de sangre',
  fecha_ultimo_grado: 'Fecha último grado', licencia_vencimiento: 'Vencimiento licencia', escolaridad: 'Escolaridad',
  licencia_expedicion: 'Expedición licencia', tipo_vivienda: 'Tipo de vivienda', estrato: 'Estrato', departamento: 'Departamento',
  cedula: 'Cédula' };
const PST_MESES = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];

// ---- tooltip compartido (valor primero, etiqueta después) ----
function pstTip() {
  let t = $('pst-tip');
  if (!t) {
    t = pstEl('div', 'pst-tip'); t.id = 'pst-tip'; t.hidden = true; t.setAttribute('role', 'tooltip');
    document.body.appendChild(t);
  }
  return t;
}
function pstTipMostrar(x, y, lineas) {
  const t = pstTip(); t.innerHTML = '';
  for (const l of lineas) {
    const fila = pstEl('div', 'pst-tip-row');
    if (l.color) { const key = pstEl('span', 'pst-tip-key'); key.style.background = l.color; fila.appendChild(key); }
    fila.appendChild(pstEl('b', null, l.valor));
    fila.appendChild(pstEl('span', null, l.etiqueta));
    t.appendChild(fila);
  }
  t.hidden = false;
  const w = t.offsetWidth, h = t.offsetHeight;
  t.style.left = Math.max(8, Math.min(window.innerWidth - w - 8, x + 14)) + 'px';
  t.style.top = Math.max(8, Math.min(window.innerHeight - h - 8, y - h - 10)) + 'px';
}
function pstTipOcultar() { const t = $('pst-tip'); if (t) t.hidden = true; }

// ---- tarjetas ----
// Tarjeta con título, nota, cuerpo (gráfica) y botón "Ver tabla" (equivalente accesible)
function pstCard(titulo, nota, grafica, tabla, ancha = false) {
  const card = pstEl('section', 'pst-card' + (ancha ? ' pst-ancha' : ''));
  const head = pstEl('div', 'pst-card-h');
  const tt = pstEl('div');
  tt.appendChild(pstEl('h4', null, titulo));
  if (nota) tt.appendChild(pstEl('div', 'pst-nota', nota));
  const btn = pstEl('button', 'btn btn-sm pst-vt', 'Ver tabla'); btn.type = 'button';
  head.append(tt, btn);
  const cuerpo = pstEl('div', 'pst-card-b'); cuerpo.appendChild(grafica);
  const tablaWrap = pstEl('div', 'pst-tabla-wrap'); tablaWrap.hidden = true; tablaWrap.appendChild(pstTablaHtml(tabla, titulo));
  btn.onclick = () => { const ver = tablaWrap.hidden; tablaWrap.hidden = !ver; cuerpo.hidden = ver; btn.textContent = ver ? 'Ver gráfica' : 'Ver tabla'; };
  card.append(head, cuerpo, tablaWrap);
  card._cuerpo = cuerpo;
  card._setTabla = (t2) => { tablaWrap.innerHTML = ''; tablaWrap.appendChild(pstTablaHtml(t2, titulo)); };
  _pst.tablas.push({ titulo, nota, ...tabla });
  return card;
}
function pstTablaHtml({ cab, filas, quienesPorFila }, titulo) {
  const t = pstEl('table', 'pst-tabla');
  const tr = pstEl('tr'); cab.forEach((c) => tr.appendChild(pstEl('th', null, c)));
  const thead = pstEl('thead'); thead.appendChild(tr); t.appendChild(thead);
  const tb = pstEl('tbody');
  filas.forEach((f, i) => {
    const r = pstEl('tr');
    f.forEach((v) => r.appendChild(pstEl('td', null, typeof v === 'number' ? pstNum(v) : v)));
    // Cada fila lleva a las personas que hay detrás del número
    const quienes = quienesPorFila && quienesPorFila[i];
    if (pstHayPersonas(quienes)) {
      r.classList.add('pst-clic'); r.tabIndex = 0; r.title = 'Ver quiénes son';
      const abrir = () => pstVerPersonas(`${titulo || 'Detalle'}: ${f[0]}`, quienes);
      r.addEventListener('click', abrir);
      r.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); abrir(); } });
    }
    tb.appendChild(r);
  });
  t.appendChild(tb);
  return t;
}
// ¿Hay detalle detrás del número? Puede ser una lista de personas (con cédula) o de siniestros.
function pstHayPersonas(arr) {
  return Array.isArray(arr) && arr.length > 0 && arr[0] && typeof arr[0] === 'object'
    && ('cedula' in arr[0] || esFilaSiniestro(arr[0]));
}
const esFilaSiniestro = (o) => !!o && typeof o === 'object' && 'key' in o && 'placa' in o;
// Barras horizontales de UNA serie: largo = cantidad; valor y % al final de la barra
function pstBarras(titulo, conteo, opts = {}) {
  const { items, sin, total } = conteo;
  const cont = pstEl('div', 'pst-bars');
  if (!items.length) cont.appendChild(pstEl('div', 'pst-vacio', 'Sin datos con estos filtros.'));
  const max = Math.max(1, ...items.map((i) => i.n));
  for (const it of items) {
    const pct = pstPct(it.n, total);
    const fila = pstEl('div', 'pst-bar-row'); fila.tabIndex = 0;
    fila.setAttribute('aria-label', `${it.k}: ${pstNum(it.n)} (${pct}%)`);
    fila.appendChild(pstEl('div', 'pst-bar-lbl', it.k));
    // Área de la barra con espacio reservado a la derecha para el valor (que va justo en la punta)
    const track = pstEl('div', 'pst-bar-track');
    const ancho = Math.max(0.6, (it.n / max) * 100);
    const bar = pstEl('div', 'pst-bar'); bar.style.width = ancho + '%';
    bar.style.background = it.otros ? '#b9b7ae' : PST_COL.s1;
    const val = pstEl('span', 'pst-bar-val', `${pstNum(it.n)} · ${pct}%`); val.style.left = `calc(${ancho}% + 8px)`;
    track.append(bar, val);
    fila.appendChild(track);
    if (pstHayPersonas(it.quienes)) {
      fila.classList.add('pst-clic'); fila.setAttribute('role', 'button');
      fila.title = `Ver las ${pstNum(it.n)} personas`;
      const abrir = () => pstVerPersonas(`${titulo}: ${it.k}`, it.quienes);
      fila.addEventListener('click', abrir);
      fila.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); abrir(); } });
    }
    const lineas = [{ valor: `${pstNum(it.n)} (${pct}%)`, etiqueta: it.k }];
    fila.addEventListener('pointermove', (e) => pstTipMostrar(e.clientX, e.clientY, lineas));
    fila.addEventListener('pointerleave', pstTipOcultar);
    fila.addEventListener('focus', () => { const b = fila.getBoundingClientRect(); pstTipMostrar(b.left + b.width / 2, b.top, lineas); });
    fila.addEventListener('blur', pstTipOcultar);
    cont.appendChild(fila);
  }
  // Los "sin dato" también se pueden revisar uno por uno (sirve para completar la información)
  if (sin && pstHayPersonas(conteo.sinQuienes)) {
    const b = pstEl('button', 'pst-sindato', `Ver quiénes no tienen este dato (${pstNum(sin)})`);
    b.type = 'button';
    b.onclick = () => pstVerPersonas(`${titulo}: sin dato`, conteo.sinQuienes);
    cont.appendChild(b);
  }
  const nota = [opts.nota, `${pstNum(total)} con dato${sin ? ` · ${pstNum(sin)} sin dato` : ''}`].filter(Boolean).join(' · ');
  const filas = items.map((i) => [i.k, i.n, `${pstPct(i.n, total)}%`]);
  const quienesPorFila = items.map((i) => i.quienes);
  if (sin) { filas.push(['Sin dato', sin, '—']); quienesPorFila.push(conteo.sinQuienes); }
  return pstCard(titulo, nota, cont, { cab: ['Categoría', 'Cantidad', '%'], filas, quienesPorFila }, opts.ancha);
}
// Rotación: ingresos y retiros. Dos vistas: POR AÑO (2019 → hoy) y POR MES (los 12 meses
// del año elegido). Dos series en líneas, un solo eje, crosshair + tooltip. Cada punto y cada
// fila de la tabla abren la lista de personas que entraron o salieron en ese periodo.
function pstRotacion(vinc) {
  const anioHoy = new Date().getFullYear(), desde = 2019;
  const aniosDisp = []; for (let a = anioHoy; a >= desde; a--) aniosDisp.push(a);
  const st = { modo: 'anio', anio: anioHoy };

  const cont = pstEl('div', 'pst-rot');
  // Controles: por año / por mes (+ año a mirar)
  const ctr = pstEl('div', 'pst-rot-ctr');
  const seg = pstEl('div', 'pst-seg');
  const bAnio = pstEl('button', 'pst-segb on', 'Por año'); bAnio.type = 'button';
  const bMes = pstEl('button', 'pst-segb', 'Por mes'); bMes.type = 'button';
  seg.append(bAnio, bMes);
  const selAnio = pstEl('select', 'pst-rot-anio'); selAnio.hidden = true;
  aniosDisp.forEach((a) => selAnio.appendChild(Object.assign(document.createElement('option'), { value: a, textContent: a })));
  selAnio.value = String(anioHoy);
  const lblAnio = pstEl('label', 'pst-rot-lbl', 'Año '); lblAnio.hidden = true; lblAnio.appendChild(selAnio);
  ctr.append(seg, lblAnio);

  const leyenda = pstEl('div', 'pst-leyenda');
  const lienzo = pstEl('div', 'pst-lienzo');
  cont.append(ctr, leyenda, lienzo);

  // Datos del modo actual: etiquetas del eje + personas de cada punto
  const calcular = () => {
    if (st.modo === 'anio') {
      const anios = []; for (let a = desde; a <= anioHoy; a++) anios.push(a);
      return {
        etiquetas: anios.map((a) => (a === anioHoy ? `${a}*` : String(a))),
        filaLbl: anios.map((a) => (a === anioHoy ? `${a} (hasta hoy)` : String(a))),
        pref: anios.map((a) => `${a}-`),
        cabecera: 'Año',
      };
    }
    const a = st.anio;
    return {
      etiquetas: PST_MESES.map((m) => m.slice(0, 3)),
      filaLbl: PST_MESES.map((m) => `${m} ${a}`),
      pref: PST_MESES.map((_, i) => `${a}-${String(i + 1).padStart(2, '0')}`),
      cabecera: 'Mes',
    };
  };
  // Las personas detrás de cada punto (el historial guarda la cédula; el nombre sale del perfil)
  const gente = (prefijo, campo) => vinc.filter((v) => String(v[campo] || '').startsWith(prefijo))
    .map((v) => ({ ...(_pst.porCedula?.get(String(v.cedula || '').trim()) || {}), cedula: v.cedula, cargo: v.cargo, _fecha: v[campo] }));

  const card = pstCard('Rotación: ingresos y retiros',
    'Historial de vinculaciones · los retiros se registran desde 2019 · * año en curso · no depende del filtro de estado',
    cont, { cab: ['Año', 'Ingresos', 'Retiros', 'Balance'], filas: [] }, true);

  const pintar = () => {
    const D = calcular();
    const ing = D.pref.map((p) => vinc.filter((v) => String(v.fecha_ingreso || '').startsWith(p)).length);
    const ret = D.pref.map((p) => vinc.filter((v) => String(v.fecha_retiro || '').startsWith(p)).length);
    const series = [{ nombre: 'Ingresos', color: PST_COL.s1, datos: ing, campo: 'fecha_ingreso' },
      { nombre: 'Retiros', color: PST_COL.s2, datos: ret, campo: 'fecha_retiro' }];
    leyenda.innerHTML = '';
    series.forEach((s) => { const k = pstEl('span', 'pst-ley'); const l = pstEl('i'); l.style.background = s.color; k.append(l, document.createTextNode(s.nombre)); leyenda.appendChild(k); });

    const dibujar = () => {
      const N = D.etiquetas.length;
      const W = Math.max(280, lienzo.clientWidth || 600), H = 230, m = { t: 14, r: 44, b: 26, l: 40 };
      const iw = W - m.l - m.r, ih = H - m.t - m.b;
      const maxV = Math.max(1, ...ing, ...ret);
      const paso = maxV <= 10 ? 2 : maxV <= 50 ? 10 : maxV <= 200 ? 50 : maxV <= 500 ? 100 : 250;
      const tope = Math.ceil(maxV / paso) * paso;
      const x = (i) => m.l + (N === 1 ? iw / 2 : (i * iw) / (N - 1));
      const y = (v) => m.t + ih - (v / tope) * ih;
      const NS = 'http://www.w3.org/2000/svg';
      const svg = document.createElementNS(NS, 'svg');
      svg.setAttribute('width', W); svg.setAttribute('height', H); svg.setAttribute('role', 'img');
      svg.setAttribute('aria-label', st.modo === 'anio' ? 'Ingresos y retiros por año' : `Ingresos y retiros por mes de ${st.anio}`);
      const add = (tag, attrs, text) => { const e = document.createElementNS(NS, tag); Object.entries(attrs).forEach(([k, v]) => e.setAttribute(k, v)); if (text != null) e.textContent = text; svg.appendChild(e); return e; };
      for (let v = 0; v <= tope; v += paso) {
        add('line', { x1: m.l, x2: W - m.r, y1: y(v), y2: y(v), stroke: v === 0 ? PST_COL.eje : PST_COL.grid, 'stroke-width': 1 });
        add('text', { x: m.l - 6, y: y(v) + 4, 'text-anchor': 'end', class: 'pst-eje' }, pstNum(v));
      }
      D.etiquetas.forEach((e2, i) => add('text', { x: x(i), y: H - 8, 'text-anchor': 'middle', class: 'pst-eje' }, e2));
      for (const s of series) {
        add('polyline', { points: s.datos.map((v, i) => `${x(i)},${y(v)}`).join(' '), fill: 'none', stroke: s.color, 'stroke-width': 2, 'stroke-linejoin': 'round', 'stroke-linecap': 'round' });
        s.datos.forEach((v, i) => {
          const c = add('circle', { cx: x(i), cy: y(v), r: 4, fill: s.color, stroke: '#fff', 'stroke-width': 2 });
          if (v > 0) { // el punto abre la lista de quiénes entraron o salieron
            c.setAttribute('r', 5); c.style.cursor = 'pointer';
            c.addEventListener('click', () => pstVerPersonas(`${s.nombre} · ${D.filaLbl[i]}`, gente(D.pref[i], s.campo), { fecha: s.nombre === 'Ingresos' ? 'Ingresó el' : 'Se retiró el' }));
          }
        });
      }
      const ultY = series.map((s) => y(s.datos[s.datos.length - 1]));
      if (Math.abs(ultY[0] - ultY[1]) >= 14) {
        series.forEach((s, k) => add('text', { x: x(N - 1) + 8, y: ultY[k] + 4, class: 'pst-fin' }, pstNum(s.datos[s.datos.length - 1])));
      }
      const cruz = add('line', { x1: 0, x2: 0, y1: m.t, y2: m.t + ih, stroke: '#898781', 'stroke-width': 1, visibility: 'hidden' });
      const zona = add('rect', { x: m.l - 10, y: m.t, width: iw + 20, height: ih, fill: 'transparent', tabindex: 0 });
      const mostrar = (i, cx, cy) => {
        cruz.setAttribute('x1', x(i)); cruz.setAttribute('x2', x(i)); cruz.setAttribute('visibility', 'visible');
        pstTipMostrar(cx, cy, [
          { valor: D.filaLbl[i], etiqueta: '' },
          ...series.map((s) => ({ color: s.color, valor: pstNum(s.datos[i]), etiqueta: s.nombre })),
        ]);
      };
      let foco = N - 1;
      zona.addEventListener('pointermove', (e) => {
        const r = svg.getBoundingClientRect();
        const px = e.clientX - r.left;
        const i = Math.max(0, Math.min(N - 1, Math.round(((px - m.l) / iw) * (N - 1))));
        mostrar(i, e.clientX, e.clientY);
      });
      zona.addEventListener('pointerleave', () => { cruz.setAttribute('visibility', 'hidden'); pstTipOcultar(); });
      zona.addEventListener('keydown', (e) => {
        if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
        foco = Math.max(0, Math.min(N - 1, foco + (e.key === 'ArrowRight' ? 1 : -1)));
        const r = svg.getBoundingClientRect(); mostrar(foco, r.left + x(foco), r.top + y(Math.max(ing[foco], ret[foco])));
      });
      zona.addEventListener('focus', () => { const r = svg.getBoundingClientRect(); mostrar(foco, r.left + x(foco), r.top + m.t + 20); });
      zona.addEventListener('blur', () => { cruz.setAttribute('visibility', 'hidden'); pstTipOcultar(); });
      lienzo.innerHTML = ''; lienzo.appendChild(svg);
    };
    requestAnimationFrame(dibujar);
    lienzo._redibujar = dibujar;

    // Tabla equivalente: una fila por periodo, clicable (muestra los ingresos de ese periodo)
    const filas = D.filaLbl.map((l, i) => [l, ing[i], ret[i], ing[i] - ret[i]]);
    const quienesPorFila = D.pref.map((p) => gente(p, 'fecha_ingreso'));
    card._setTabla({ cab: [D.cabecera, 'Ingresos', 'Retiros', 'Balance'], filas, quienesPorFila });
    // Lo que se lleva el Excel general
    const guardada = _pst.tablas.find((x) => x.titulo === 'Rotación: ingresos y retiros');
    if (guardada) { guardada.cab = [D.cabecera, 'Ingresos', 'Retiros', 'Balance']; guardada.filas = filas; }
  };

  const cambiarModo = (modo) => {
    st.modo = modo;
    bAnio.classList.toggle('on', modo === 'anio');
    bMes.classList.toggle('on', modo === 'mes');
    lblAnio.hidden = modo !== 'mes';
    selAnio.hidden = modo !== 'mes';
    pintar();
  };
  bAnio.onclick = () => cambiarModo('anio');
  bMes.onclick = () => cambiarModo('mes');
  selAnio.onchange = () => { st.anio = Number(selAnio.value); pintar(); };
  pintar();
  return card;
}
function pstMeses(personas, ancha = false) {
  const porMes = Array.from({ length: 12 }, () => []);
  personas.forEach((p) => { const m = /^\d{4}-(\d{2})/.exec(p.fecha_nacimiento || ''); if (m) porMes[Number(m[1]) - 1].push(p); });
  const n = porMes.map((a) => a.length);
  const max = Math.max(1, ...n), mesHoy = new Date().getMonth();
  const cont = pstEl('div', 'pst-cols');
  n.forEach((v, i) => {
    const col = pstEl('div', 'pst-col' + (i === mesHoy ? ' pst-col-hoy' : '')); col.tabIndex = 0;
    col.setAttribute('aria-label', `${PST_MESES[i]}: ${v}`);
    col.appendChild(pstEl('span', 'pst-col-val', pstNum(v)));
    const barra = pstEl('div', 'pst-col-bar'); barra.style.height = Math.max(2, (v / max) * 110) + 'px'; barra.style.background = PST_COL.s1;
    col.appendChild(barra);
    col.appendChild(pstEl('span', 'pst-col-lbl', PST_MESES[i].slice(0, 3)));
    if (v > 0) {
      col.classList.add('pst-clic'); col.setAttribute('role', 'button'); col.title = `Ver quiénes cumplen en ${PST_MESES[i].toLowerCase()}`;
      const abrir = () => pstVerPersonas(`Cumpleaños de ${PST_MESES[i].toLowerCase()}`,
        porMes[i].slice().sort((a, b) => String(a.fecha_nacimiento).slice(5) < String(b.fecha_nacimiento).slice(5) ? -1 : 1),
        { fecha: 'Cumple el', campoFecha: 'fecha_nacimiento', soloDia: true });
      col.addEventListener('click', abrir);
      col.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); abrir(); } });
    }
    const lineas = [{ valor: pstNum(v), etiqueta: `cumpleaños en ${PST_MESES[i].toLowerCase()}` }];
    col.addEventListener('pointermove', (e) => pstTipMostrar(e.clientX, e.clientY, lineas));
    col.addEventListener('pointerleave', pstTipOcultar);
    col.addEventListener('focus', () => { const b = col.getBoundingClientRect(); pstTipMostrar(b.left, b.top, lineas); });
    col.addEventListener('blur', pstTipOcultar);
    cont.appendChild(col);
  });
  return pstCard('Cumpleaños por mes', `Mes actual resaltado: ${PST_MESES[mesHoy].toLowerCase()} · toca un mes para ver quiénes cumplen`, cont,
    { cab: ['Mes', 'Cumpleaños'], filas: n.map((v, i) => [PST_MESES[i], v]), quienesPorFila: porMes }, ancha);
}
function pstTile(etiqueta, valor, detalle, hero = false, quienes = null) {
  const t = pstEl('div', 'pst-tile' + (hero ? ' pst-hero' : '') + (pstHayPersonas(quienes) ? ' pst-clic' : ''));
  if (pstHayPersonas(quienes)) {
    t.tabIndex = 0; t.setAttribute('role', 'button'); t.title = 'Ver quiénes son';
    const abrir = () => pstVerPersonas(etiqueta, quienes);
    t.addEventListener('click', abrir);
    t.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); abrir(); } });
  }
  t.appendChild(pstEl('div', 'pst-tile-l', etiqueta));
  t.appendChild(pstEl('div', 'pst-tile-v', valor));
  if (detalle) t.appendChild(pstEl('div', 'pst-tile-d', detalle));
  return t;
}
function renderPerfilStats() {
  const body = $('pst-body'); if (!_pst.personas) return;
  const estado = $('pst-estado').value, tipo = $('pst-tipo').value, area = $('pst-area').value;
  const P = _pst.personas.filter((p) => (!estado || p.estado === estado) && (!tipo || p.tipo === tipo) && (!area || p.area === area));
  const V = _pst.vinc.filter((v) => (!tipo || v.tipo === tipo) && (!area || v.area === area));
  _pst.tablas = [];
  _pst.filtro = [estado ? (estado === 'ACTIVO' ? 'Activos' : 'Inactivos') : 'Todos los estados',
    tipo ? (tipo === 'CONDUCTOR' ? 'Conductores' : 'Administrativos') : 'Conductores y administrativos', area || 'Todas las áreas'].join(' · ');
  $('pst-sub').textContent = _pst.filtro;
  const bAct = PST_BLOQUES.find((x) => x.key === (_pst.bloque || 'resumen')) || PST_BLOQUES[0];
  const tit2 = $('pst-title'); if (tit2) tit2.textContent = `${bAct.icon} ${bAct.label}`;
  body.innerHTML = '';
  if (!P.length) { body.appendChild(pstEl('div', 'cump-empty', 'No hay personas con estos filtros.')); return; }

  // ---- Indicadores ----
  const edades = P.map((p) => pstAnios(p.fecha_nacimiento)).filter((v) => v != null);
  const antig = P.map((p) => pstAnios(p.fecha_ingreso, p.estado === 'INACTIVO' ? p.fecha_retiro : null)).filter((v) => v != null);
  const prom = (a) => (a.length ? (a.reduce((s, v) => s + v, 0) / a.length).toLocaleString('es-CO', { maximumFractionDigits: 1 }) : '—');
  const lMujeres = P.filter((p) => p.sexo === 'FEMENINO'); const mujeres = lMujeres.length, conSexo = P.filter((p) => p.sexo).length;
  const nCond = P.filter((p) => p.tipo === 'CONDUCTOR').length, nAdm = P.length - nCond;
  const lCorregir = P.filter((p) => p.por_corregir); const corregir = lCorregir.length;
  const autorizaron = P.filter((p) => p.habeas_data_aceptado_en).length;
  const hoy = hoyServidor();
  const enDias = (f) => (f ? Math.round((new Date(f + 'T12:00:00') - new Date(hoy + 'T12:00:00')) / 86400000) : null);
  const condAct = P.filter((p) => p.tipo === 'CONDUCTOR' && p.estado === 'ACTIVO');
  const lLicVenc = condAct.filter((p) => { const d = enDias(p.licencia_vencimiento); return d != null && d < 0; });
  const lLic90 = condAct.filter((p) => { const d = enDias(p.licencia_vencimiento); return d != null && d >= 0 && d <= 90; });
  const licVenc = lLicVenc.length, lic90 = lLic90.length;
  const kpis = pstEl('div', 'pst-kpis');
  kpis.append(
    pstTile('Personas', pstNum(P.length), `${pstNum(nCond)} conductores · ${pstNum(nAdm)} administrativos`, true, P),
    pstTile('Edad promedio', `${prom(edades)} años`, edades.length ? `de ${Math.min(...edades)} a ${Math.max(...edades)} años` : ''),
    pstTile('Antigüedad promedio', `${prom(antig)} años`, estado === 'INACTIVO' ? 'tiempo que duraron' : 'en la empresa'),
    pstTile('Mujeres', `${pstPct(mujeres, conSexo)}%`, `${pstNum(mujeres)} de ${pstNum(conSexo)}`, false, lMujeres),
    pstTile('Licencias de conductores activos', licVenc ? `⛔ ${pstNum(licVenc)} vencidas` : '✅ Ninguna vencida', `🕒 ${pstNum(lic90)} vencen en 90 días`,
      false, [...lLicVenc, ...lLic90].map((p) => ({ ...p, _fecha: p.licencia_vencimiento }))),
    pstTile('Datos por corregir', `${pstNum(corregir)}`, `${pstPct(corregir, P.length)}% de las personas · ${pstNum(autorizaron)} autorizaron datos`, false, lCorregir),
  );
  body.appendChild(kpis);

  // ---- Secciones por tema ----
  // Cada tema es una entrada del menú (👥 Talento humano) y una pestaña aquí arriba.
  const B = _pst.bloque || 'resumen';
  const ver = (k) => B === 'resumen' || B === k;
  const tabs = pstEl('div', 'pst-tabs');
  PST_BLOQUES.forEach((b) => {
    const t2 = pstEl('button', 'pst-tab' + (b.key === B ? ' on' : ''), `${b.icon} ${b.label}`);
    t2.type = 'button';
    t2.onclick = () => { _pst.bloque = b.key; renderPerfilStats(); };
    tabs.appendChild(t2);
  });
  body.insertBefore(tabs, kpis);

  const seccion = (titulo) => { body.appendChild(pstEl('h3', 'pst-sec', titulo)); const g = pstEl('div', 'pst-grid'); body.appendChild(g); return g; };
  const L = PERFIL_LISTAS;
  let g;
  // ---- Demografía ----
  if (ver('demografia')) {
    g = seccion('👤 Demografía');
    g.appendChild(pstBarras('Sexo', pstContar(P, (p) => p.sexo)));
    g.appendChild(pstBarras('Rango de edad', pstContar(P, (p) => pstRango(pstAnios(p.fecha_nacimiento), PST_RANGOS.edad), { orden: PST_RANGOS.edad.map((r) => r[2]) })));
    g.appendChild(pstBarras('Estado civil', pstContar(P, (p) => p.estado_civil, { orden: L.estado_civil })));
    g.appendChild(pstBarras('Escolaridad', pstContar(P, (p) => p.escolaridad, { orden: L.escolaridad })));
    if (B === 'resumen') g.appendChild(pstMeses(P));
  }
  // ---- Cumpleaños ----
  if (B === 'cumple') {
    g = seccion('🎂 Cumpleaños');
    g.appendChild(pstMeses(P, true));
    const hoyMD = hoyServidor().slice(5);
    const mesActual = hoyMD.slice(0, 2);
    const anioHoy2 = Number(hoyServidor().slice(0, 4));
    const nombreMes = PST_MESES[Number(mesActual) - 1];
    const delMes = P.filter((p) => String(p.fecha_nacimiento || '').slice(5, 7) === mesActual)
      .sort((a, b) => (String(a.fecha_nacimiento).slice(8) < String(b.fecha_nacimiento).slice(8) ? -1 : 1));
    const cont = pstEl('div', 'pst-bars');
    if (!delMes.length) cont.appendChild(pstEl('div', 'pst-vacio', 'Nadie cumple años este mes con estos filtros.'));
    delMes.forEach((p) => {
      const dia = String(p.fecha_nacimiento).slice(8, 10);
      const esHoy = String(p.fecha_nacimiento).slice(5) === hoyMD;
      const fila = pstEl('div', 'pst-cump-row' + (esHoy ? ' hoy' : ''));
      fila.tabIndex = 0; fila.classList.add('pst-clic'); fila.title = 'Abrir la ficha';
      const cal = pstEl('div', 'pst-cump-dia');
      cal.appendChild(pstEl('b', null, dia));
      cal.appendChild(pstEl('span', null, nombreMes.slice(0, 3).toUpperCase()));
      fila.appendChild(cal);
      const c = pstEl('div', 'pst-cump-c');
      c.appendChild(pstEl('div', 'pst-cump-nom', p.nombre || p.cedula));
      c.appendChild(pstEl('div', 'pst-cump-fec', `${pstDiaSemana(anioHoy2, mesActual, dia)} ${Number(dia)} de ${nombreMes.toLowerCase()}${pstCumpleEdad(p, anioHoy2) ? ` · cumple ${pstCumpleEdad(p, anioHoy2)} años` : ''}`));
      c.appendChild(pstEl('div', 'pst-cump-sub', [p.cargo, p.celular].filter(Boolean).join(' · ')));
      fila.appendChild(c);
      if (esHoy) fila.appendChild(pstEl('span', 'chip chip-green', '¡Hoy!'));
      const abrir = () => pstAbrirFicha(p.id);
      fila.addEventListener('click', abrir);
      fila.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); abrir(); } });
      cont.appendChild(fila);
    });
    const cardC = pstCard(`Cumpleaños de ${nombreMes.toLowerCase()} ${anioHoy2}`,
      `${pstNum(delMes.length)} persona(s) · el día de hoy queda resaltado · toca a alguien para ver su ficha`, cont,
      { cab: ['Día', 'Fecha', 'Nombre', 'Cargo', 'Celular'],
        filas: delMes.map((p) => {
          const d = String(p.fecha_nacimiento).slice(8, 10);
          return [Number(d), `${pstDiaSemana(anioHoy2, mesActual, d)} ${Number(d)} de ${nombreMes.toLowerCase()}`, p.nombre || '', p.cargo || '', p.celular || ''];
        }),
        quienesPorFila: delMes.map((p) => [p]) }, true);
    // Excel de la lista del mes (para pasársela a los administradores)
    if (delMes.length) {
      const bx = pstEl('button', 'btn btn-sm', '⬇️ Excel de cumpleaños');
      bx.type = 'button';
      bx.onclick = () => pstExportarCumple(nombreMes, anioHoy2, delMes);
      cardC.querySelector('.pst-card-h').appendChild(bx);
    }
    g.appendChild(cardC);
  }
  // ---- Familia y vivienda ----
  if (ver('familia')) {
    g = seccion('🏠 Familia y vivienda');
    g.appendChild(pstBarras('Estrato socioeconómico', pstContar(P, (p) => (p.estrato != null ? `Estrato ${p.estrato}` : null), { orden: [1, 2, 3, 4, 5, 6].map((n) => `Estrato ${n}`) })));
    g.appendChild(pstBarras('Tipo de vivienda', pstContar(P, (p) => p.tipo_vivienda, { orden: L.tipo_vivienda })));
    g.appendChild(pstBarras('Personas a cargo', pstContar(P, (p) => p.personas_a_cargo, { orden: L.personas_a_cargo })));
    g.appendChild(pstBarras('¿Tiene hijos?', pstContar(P, (p) => p.tiene_hijos, { orden: L.si_no })));
    g.appendChild(pstBarras('¿Tiene pareja?', pstContar(P, (p) => p.convive_pareja, { orden: L.si_no })));
    g.appendChild(pstBarras('Municipio de residencia', pstContar(P, (p) => p.ciudad, { top: 8 })));
  }
  // ---- Laboral ----
  if (ver('laboral')) {
    g = seccion('💼 Laboral');
    g.appendChild(pstBarras('Antigüedad en la empresa', pstContar(P, (p) => pstRango(pstAnios(p.fecha_ingreso, p.estado === 'INACTIVO' ? p.fecha_retiro : null), PST_RANGOS.antig), { orden: PST_RANGOS.antig.map((r) => r[2]) })));
    g.appendChild(pstBarras('Área', pstContar(P, (p) => p.area, { top: 10 })));
    g.appendChild(pstBarras('Cargo', pstContar(P, (p) => p.cargo, { top: 10 })));
    g.appendChild(pstBarras('Tipo de contrato', pstContar(P, (p) => p.tipo_contrato)));
    g.appendChild(pstBarras('Rango salarial', pstContar(P, (p) => pstSalRango(p.salario), { orden: PST_RANGOS.salario.map((r) => r[2]) }),
      { nota: `SMMLV 2026 = $${pstNum(PST_SMMLV)}${estado !== 'ACTIVO' ? ' · en inactivos es el último salario (de otros años)' : ''}` }));
  }
  // ---- Salud y seguridad social ----
  if (ver('salud')) {
    g = seccion('🩺 Salud y seguridad social');
    g.appendChild(pstBarras('EPS', pstContar(P, (p) => p.eps)));
    g.appendChild(pstBarras('Fondo de pensiones', pstContar(P, (p) => p.afp)));
    g.appendChild(pstBarras('Tipo de sangre', pstContar(P, (p) => p.tipo_sangre, { orden: L.tipo_sangre })));
    g.appendChild(pstBarras('Uso de lentes', pstContar(P, (p) => p.uso_lentes, { orden: L.si_no })));
  }
  // ---- Conductores ----
  const PC = P.filter((p) => p.tipo === 'CONDUCTOR');
  if (ver('conductores') && PC.length) {
    g = seccion('🚌 Conductores');
    g.appendChild(pstBarras('Categoría de licencia', pstContar(PC, (p) => p.categoria_licencia, { orden: L.categoria_licencia })));
    g.appendChild(pstBarras('Estado de restricción', pstContar(PC, (p) => p.estado_restriccion)));
    g.appendChild(pstBarras('Vigencia de la licencia', pstContar(PC, (p) => {
      const d = enDias(p.licencia_vencimiento);
      return d == null ? null : d < 0 ? 'Vencida' : d <= 30 ? 'Vence en 30 días' : d <= 90 ? 'Vence en 31 a 90 días' : d <= 365 ? 'Vence en 3 a 12 meses' : 'Vigente más de 1 año';
    }, { orden: ['Vencida', 'Vence en 30 días', 'Vence en 31 a 90 días', 'Vence en 3 a 12 meses', 'Vigente más de 1 año'] })));
  }
  // ---- Rotación ----
  if (ver('rotacion')) {
    g = seccion('🔄 Rotación');
    g.appendChild(pstRotacion(V));
  }
  // ---- Calidad de datos ----
  if (ver('calidad')) {
    g = seccion('🧹 Calidad de datos');
    const campos = [];
    P.forEach((p) => String(p.por_corregir || '').split(',').filter(Boolean)
      .forEach((c) => campos.push({ ...p, _campo: PST_CAMPOS[c.trim()] || c.trim() })));
    g.appendChild(pstBarras('Campos por corregir', pstContar(campos, (c) => c._campo),
      { nota: 'Se corrigen desde la ficha o con el 🔗 link de actualización de datos' }));
    g.appendChild(pstBarras('Estado de los datos', pstContar(P, (p) => (p.por_corregir ? 'Con datos por corregir' : 'Completos')), {}));
  }
}

// ---- ¿Quiénes son? ----
// Cualquier número de las estadísticas (una barra, una fila de la tabla, un mes de cumpleaños,
// un punto de la rotación) abre esta lista con las personas que hay detrás. Desde aquí se
// descarga a Excel o se abre la ficha completa de cada quien.
let _pstLista = { titulo: '', personas: [] };
function pstPersonasModal() {
  let m = $('pstp-modal');
  if (m) return m;
  m = document.createElement('div');
  m.id = 'pstp-modal'; m.className = 'modal'; m.hidden = true;
  m.innerHTML = `<div class="modal-card pstp-card">
    <div class="modal-head"><h3></h3><span class="spacer"></span>
      <button type="button" class="icon-btn" data-x aria-label="Cerrar">✕</button></div>
    <div class="pstp-sub"></div>
    <div class="pstp-body"></div>
    <div class="modal-foot"><button type="button" class="btn btn-sm" data-excel>⬇️ Excel</button>
      <span class="spacer"></span><button type="button" class="btn" data-x>Cerrar</button></div>
  </div>`;
  m.addEventListener('click', (e) => { if (e.target === m || e.target.closest('[data-x]')) m.hidden = true; });
  m.querySelector('[data-excel]').onclick = () => pstExportarPersonas(_pstLista.titulo, _pstLista.personas);
  document.body.appendChild(m);
  return m;
}
function pstVerPersonas(titulo, personas, opts = {}) {
  // Si lo que hay detrás del número son siniestros, se muestra la lista de reportes
  if (personas && personas.length && esFilaSiniestro(personas[0])) return sinVerLista(titulo, personas);
  let lista = (personas || []).filter((p) => p && (p.cedula || p.nombre));
  // Sin fecha de por medio, en orden alfabético (más fácil de buscar)
  if (!opts.fecha) lista = lista.slice().sort((a, b) => String(a.nombre || '').localeCompare(String(b.nombre || '')));
  _pstLista = { titulo, personas: lista, opts };
  const m = pstPersonasModal();
  m.querySelector('h3').textContent = `👥 ${titulo}`;
  m.querySelector('.pstp-sub').textContent = `${pstNum(lista.length)} persona(s) · toca una para ver su ficha completa`;
  const body = m.querySelector('.pstp-body');
  body.innerHTML = '';
  if (!lista.length) { body.appendChild(pstEl('div', 'cump-empty', 'No hay personas en este grupo.')); m.hidden = false; return; }
  const campoFecha = opts.campoFecha || '_fecha';
  const conFecha = !!opts.fecha && lista.some((p) => p[campoFecha]);
  const tabla = pstEl('table', 'pst-tabla pstp-tabla');
  const cab = ['Nombre', 'Cédula', 'Cargo', 'Estado', 'Celular'];
  if (conFecha) cab.splice(3, 0, opts.fecha);
  const tr = pstEl('tr'); cab.forEach((c) => tr.appendChild(pstEl('th', null, c)));
  const thead = pstEl('thead'); thead.appendChild(tr); tabla.appendChild(thead);
  const tb = pstEl('tbody');
  for (const p of lista) {
    const r = pstEl('tr');
    r.appendChild(pstEl('td', 'pstp-nom', p.nombre || '(sin nombre en el perfil)'));
    r.appendChild(pstEl('td', null, p.cedula || '—'));
    r.appendChild(pstEl('td', null, p.cargo || '—'));
    if (conFecha) {
      const f = p[campoFecha] || '';
      r.appendChild(pstEl('td', null, opts.soloDia ? String(f).slice(8, 10) + '/' + String(f).slice(5, 7) : fechaLegible(f)));
    }
    r.appendChild(pstEl('td', null, p.estado || '—'));
    r.appendChild(pstEl('td', null, p.celular || '—'));
    if (p.id) {
      r.classList.add('pst-clic'); r.tabIndex = 0; r.title = 'Abrir la ficha completa';
      const abrir = () => pstAbrirFicha(p.id);
      r.addEventListener('click', abrir);
      r.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); abrir(); } });
    }
    tb.appendChild(r);
  }
  tabla.appendChild(tb);
  body.appendChild(tabla);
  m.hidden = false;
}
// Abre la ficha de la persona desde la lista (hay que traer la fila completa)
async function pstAbrirFicha(id) {
  showBusy('Abriendo ficha…');
  try {
    const { data, error } = await sb.from('perfilsociodemografico').select('*').eq('id', id).single();
    if (error) throw error;
    openPerfilFicha(data);
  } catch (e) {
    toast('No se pudo abrir la ficha: ' + (e.message || e), 'err');
  } finally { hideBusy(); }
}
async function pstExportarPersonas(titulo, personas) {
  if (!personas || !personas.length) { toast('No hay personas para exportar.', 'err'); return; }
  try {
    const XLSX = await import('https://esm.sh/xlsx@0.18.5');
    const aoa = [[titulo], [`${personas.length} persona(s) · ${_pst.filtro || ''}`], [`Generado: ${fmtFechaHora(new Date())}`], [],
      ['Nombre', 'Cédula', 'Código', 'Cargo', 'Área', 'Tipo', 'Estado', 'Celular', 'Fecha de ingreso', 'Fecha de retiro']];
    personas.forEach((p) => aoa.push([p.nombre || '', p.cedula || '', p.codigo || '', p.cargo || '', p.area || '',
      p.tipo || '', p.estado || '', p.celular || '',
      p.fecha_ingreso ? celdaFechaXlsx(p.fecha_ingreso) : '', p.fecha_retiro ? celdaFechaXlsx(p.fecha_retiro) : '']));
    const ws = XLSX.utils.aoa_to_sheet(aoa, { cellDates: true });
    ws['!cols'] = [{ wch: 34 }, { wch: 12 }, { wch: 8 }, { wch: 22 }, { wch: 16 }, { wch: 14 }, { wch: 10 }, { wch: 12 }, { wch: 13 }, { wch: 13 }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Personas');
    const blob = new Blob([XLSX.write(wb, { type: 'array', bookType: 'xlsx' })], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `${titulo.replace(/[^\wáéíóúñÁÉÍÓÚÑ ]+/g, ' ').trim().replace(/\s+/g, '_')}_${hoyServidor()}.xlsx`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    toast('Excel generado', 'ok');
  } catch (e) {
    toast('No se pudo generar el Excel: ' + (e.message || e), 'err');
  }
}

const PST_DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
function pstDiaSemana(anio, mes, dia) { return PST_DIAS[new Date(Number(anio), Number(mes) - 1, Number(dia)).getDay()]; }
function pstCumpleEdad(p, anio) { const y = Number(String(p.fecha_nacimiento || '').slice(0, 4)); return y ? anio - y : null; }
// Excel de los cumpleaños del mes (la lista que se le pasa a los administradores)
async function pstExportarCumple(nombreMes, anio, personas) {
  try {
    const XLSX = await import('https://esm.sh/xlsx@0.18.5');
    const aoa = [[`Cumpleaños de ${nombreMes.toLowerCase()} ${anio} — Autobuses El Poblado`],
      [`${personas.length} persona(s) · ${_pst.filtro || ''}`], [`Generado: ${fmtFechaHora(new Date())}`], [],
      ['Día', 'Fecha', 'Nombre', 'Cédula', 'Cargo', 'Área', 'Tipo', 'Celular', 'Cumple']];
    personas.forEach((p) => {
      const d = String(p.fecha_nacimiento).slice(8, 10);
      aoa.push([Number(d), `${pstDiaSemana(anio, String(p.fecha_nacimiento).slice(5, 7), d)} ${Number(d)} de ${nombreMes.toLowerCase()}`,
        p.nombre || '', p.cedula || '', p.cargo || '', p.area || '', p.tipo || '', p.celular || '',
        pstCumpleEdad(p, anio) ? `${pstCumpleEdad(p, anio)} años` : '']);
    });
    const ws = XLSX.utils.aoa_to_sheet(aoa);
    ws['!cols'] = [{ wch: 6 }, { wch: 26 }, { wch: 34 }, { wch: 12 }, { wch: 24 }, { wch: 16 }, { wch: 15 }, { wch: 12 }, { wch: 10 }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Cumpleaños');
    const blob = new Blob([XLSX.write(wb, { type: 'array', bookType: 'xlsx' })], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const a2 = document.createElement('a');
    a2.href = URL.createObjectURL(blob);
    a2.download = `Cumpleanos_${nombreMes}_${anio}.xlsx`;
    a2.click();
    setTimeout(() => URL.revokeObjectURL(a2.href), 4000);
    toast('Excel de cumpleaños generado', 'ok');
  } catch (e) {
    toast('No se pudo generar el Excel: ' + (e.message || e), 'err');
  }
}

async function exportarPerfilStats() {
  if (!_pst.tablas.length) { toast('No hay estadísticas para exportar.', 'err'); return; }
  const btn = $('pst-excel'); const prev = btn.textContent; btn.disabled = true; btn.textContent = '⏳ Generando…';
  try {
    const XLSX = await import('https://esm.sh/xlsx@0.18.5');
    const aoa = [['Estadísticas sociodemográficas — Autobuses El Poblado'], [`Filtro: ${_pst.filtro}`], [`Generado: ${fmtFechaHora(new Date())}`], []];
    for (const t of _pst.tablas) {
      aoa.push([t.titulo]); if (t.nota) aoa.push([t.nota]);
      aoa.push(t.cab); t.filas.forEach((f) => aoa.push(f)); aoa.push([]);
    }
    const ws = XLSX.utils.aoa_to_sheet(aoa);
    ws['!cols'] = [{ wch: 42 }, { wch: 14 }, { wch: 12 }, { wch: 12 }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Estadísticas');
    const blob = new Blob([XLSX.write(wb, { type: 'array', bookType: 'xlsx' })], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob); a.download = `Estadisticas_sociodemograficas_${hoyServidor()}.xlsx`; a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    toast('Excel generado', 'ok');
  } catch (e) {
    toast('No se pudo generar el Excel: ' + (e.message || e), 'err');
  } finally { btn.disabled = false; btn.textContent = prev; }
}

// ===================================================================================
// 📊 ESTADÍSTICAS DE SINIESTROS — comparten pantalla con las del perfil sociodemográfico.
// Cada tema es una entrada del submenú 🚨 Siniestros → 📊 Estadísticas. Todo número lleva al
// detalle: la lista de reportes que hay detrás y, de ahí, a la ficha completa del siniestro.
// El conductor se cruza por CÉDULA con el Perfil sociodemográfico, así se sabe quién es,
// si sigue activo, su cargo y su antigüedad (y quién quedó fuera del perfil).
// ===================================================================================
const SST_BLOQUES = [
  { key: 'resumen', icon: '📊', label: 'Resumen de siniestros' },
  { key: 'tiempo', icon: '📅', label: 'Por año y por mes' },
  { key: 'conductores', icon: '🧑‍✈️', label: 'Conductores' },
  { key: 'vehiculos', icon: '🚌', label: 'Vehículos y rutas' },
  { key: 'causas', icon: '💥', label: 'Causas y gravedad' },
  { key: 'costos', icon: '💰', label: 'Costos y conciliación' },
  { key: 'vial', icon: '🛡️', label: 'Seguridad vial (conducción)' },
  { key: 'mapa', icon: '🗺️', label: 'Mapa de riesgo' },
];
const _sst = { rows: null, personas: null, bloque: 'resumen', porCedula: null, porCodigo: null };
const SST_COLS = 'key,fecha,placa,numero_interno,ruta,afiliado,conductor_cedula,conductor_codigo,'
  + 'conductor_nombre,conductor_celular,gravedad,responsabilidad,tipo_conciliacion,tipo_lesion,'
  + 'monto,categorizacion,estado,causa,factor,lugar,reportado_en';
// Cédula comparable: los dos lados vienen de archivos distintos (AppSheet y el CSV de nómina)
const sinCed = (v) => String(v == null ? '' : v).replace(/\D/g, '').replace(/^0+/, '');
const sstMonto = (n) => '$ ' + Math.round(Number(n || 0)).toLocaleString('es-CO');

async function openSiniestrosStats(bloque) {
  if (!isTalentoHumano()) return;
  _sst.bloque = bloque || 'resumen';
  currentView = 'sinstats';
  statsPrepararVista();
  $('pst-fl-perfil').hidden = true; $('pst-fl-sin').hidden = false; $('pst-fl-pqr').hidden = true;
  $('nav-sst-' + (_sst.bloque || 'resumen'))?.classList.add('active');
  buildBottomNav();
  const b = SST_BLOQUES.find((x) => x.key === _sst.bloque) || SST_BLOQUES[0];
  const tit = $('pst-title'); if (tit) tit.textContent = `🚨 ${b.label}`;
  if (!_sst.rows) await cargarSiniestrosStats(); else renderSiniestrosStats();
}
async function cargarSiniestrosStats() {
  const body = $('pst-body');
  body.innerHTML = '<div class="loading">Leyendo los siniestros…</div>';
  const leerTodo = async (tabla, cols, orden) => {
    const out = [];
    for (let desde = 0; desde < 50000; desde += 1000) {
      const { data, error } = await sb.from(tabla).select(cols).order(orden).range(desde, desde + 999);
      if (error) throw error;
      out.push(...(data || []));
      if (!data || data.length < 1000) break;
    }
    return out;
  };
  try {
    // El perfil se lee solo para ponerle cara al conductor (quién es, si sigue activo, su cargo)
    const [rows, personas] = await Promise.all([
      leerTodo('siniestros', SST_COLS, 'key'),
      leerTodo('perfilsociodemografico', 'id,cedula,nombre,codigo,celular,tipo,estado,cargo,area,fecha_ingreso,fecha_retiro', 'id'),
    ]);
    _sst.rows = rows; _sst.personas = personas;
    _sst.porCedula = new Map();
    _sst.porCodigo = new Map();
    for (const p of personas) {
      const c = sinCed(p.cedula); if (c && !_sst.porCedula.has(c)) _sst.porCedula.set(c, p);
      const k = String(p.codigo || '').trim(); if (k && !_sst.porCodigo.has(k)) _sst.porCodigo.set(k, p);
    }
    // Los filtros se arman con lo que realmente trajo la hoja (conserva lo elegido)
    const llenar = (id, valores, primero) => {
      const sel = $(id), prev = sel.value;
      sel.innerHTML = `<option value="">${primero}</option>`;
      valores.forEach((v) => sel.appendChild(Object.assign(document.createElement('option'), { value: v, textContent: v })));
      if (valores.includes(prev)) sel.value = prev;
    };
    const anios = [...new Set(rows.map((s) => String(s.fecha || '').slice(0, 4)).filter((a) => /^\d{4}$/.test(a)))].sort().reverse();
    llenar('sst-anio', anios, 'Todos');
    llenar('sst-gravedad', [...new Set(rows.map((s) => s.gravedad).filter(Boolean))].sort(), 'Todas');
    llenar('sst-resp', [...new Set(rows.map((s) => s.responsabilidad).filter(Boolean))].sort(), 'Todos');
    sstLlenarMeses();
    renderSiniestrosStats();
  } catch (e) {
    body.innerHTML = '';
    body.appendChild(pstEl('div', 'cump-empty', 'No se pudieron leer los siniestros: ' + (e.message || e)));
  }
}
// La persona del perfil que hay detrás del conductor del reporte (por cédula, si no por código)
function sstPersona(s) {
  const c = sinCed(s.conductor_cedula);
  if (c && _sst.porCedula.has(c)) return _sst.porCedula.get(c);
  const k = String(s.conductor_codigo || '').trim();
  return k && _sst.porCodigo.has(k) ? _sst.porCodigo.get(k) : null;
}
// Agrupa los reportes por conductor y los cruza con el perfil
function sstPorConductor(R) {
  const m = new Map();
  for (const s of R) {
    const ced = sinCed(s.conductor_cedula);
    const k = ced || `n:${String(s.conductor_nombre || '').trim().toUpperCase()}` || 'sin';
    if (!m.has(k)) m.set(k, { ced, nombre: s.conductor_nombre, codigo: s.conductor_codigo, celular: s.conductor_celular, rows: [] });
    m.get(k).rows.push(s);
  }
  return [...m.values()].map((g) => {
    const p = sstPersona({ conductor_cedula: g.ced, conductor_codigo: g.codigo });
    return {
      ...g, p, n: g.rows.length,
      resp: g.rows.filter((s) => s.responsabilidad === 'SI').length,
      heridos: g.rows.filter((s) => s.gravedad === 'HERIDO').length,
      monto: g.rows.reduce((t, s) => t + Number(s.monto || 0), 0),
      ultimo: g.rows.reduce((mx, s) => (String(s.fecha || '') > mx ? String(s.fecha) : mx), ''),
    };
  }).sort((a, b) => b.n - a.n || b.monto - a.monto || String(a.nombre || '').localeCompare(String(b.nombre || '')));
}
// El conductor como "persona" para las listas: si está en el perfil se abre su ficha completa
function sstComoPersona(g) {
  if (g.p) return { ...g.p, _sin: g.n };
  return { cedula: g.ced || '—', nombre: g.nombre || '(sin nombre en el reporte)', codigo: g.codigo || '',
    celular: g.celular || '', cargo: 'CONDUCTOR', estado: 'NO ESTÁ EN EL PERFIL', _sin: g.n };
}
// Tarjeta que es solo una tabla (rankings y costos, donde la gráfica no aporta)
function sstTarjetaTabla(titulo, nota, tabla, ancha = true) {
  const card = pstEl('section', 'pst-card' + (ancha ? ' pst-ancha' : ''));
  const head = pstEl('div', 'pst-card-h'); const tt = pstEl('div');
  tt.appendChild(pstEl('h4', null, titulo));
  if (nota) tt.appendChild(pstEl('div', 'pst-nota', nota));
  head.appendChild(tt);
  const cuerpo = pstEl('div', 'pst-card-b pst-tabla-wrap');
  cuerpo.appendChild(pstTablaHtml(tabla, titulo));
  card.append(head, cuerpo);
  _pst.tablas.push({ titulo, nota, ...tabla });
  return card;
}
// Quién fue el conductor con MÁS reportes en cada periodo (corte 4 = año, 7 = mes).
// Si en el periodo nadie repitió, se dice tal cual: señalar a uno al azar sería injusto.
function sstLideresPorPeriodo(R, corte) {
  const periodos = [...new Set(R.map((s) => String(s.fecha || '').slice(0, corte)))]
    .filter((v) => v.length === corte && /^\d{4}/.test(v)).sort().reverse();
  const filas = [], quienes = [];
  for (const per of periodos) {
    const del = R.filter((s) => String(s.fecha || '').startsWith(per));
    const gm = sstPorConductor(del);
    const lider = gm[0]; if (!lider) continue;
    const empatados = gm.filter((x) => x.n === lider.n).length - 1;
    const etiqueta = corte === 4 ? per : `${PST_MESES[Number(per.slice(5, 7)) - 1]} ${per.slice(0, 4)}`;
    if (lider.n < 2) {
      filas.push([etiqueta, del.length, `Ninguno repitió (${gm.length} conductores, uno cada uno)`, '—', '—', '—', '—', '—']);
      quienes.push(del);
    } else {
      filas.push([etiqueta, del.length,
        (lider.p?.nombre || lider.nombre || '(sin nombre)') + (empatados ? ` (+${empatados} empatado${empatados > 1 ? 's' : ''})` : ''),
        lider.ced || '—', lider.n, lider.p ? (lider.p.estado || '—') : 'No está en el perfil',
        lider.resp, lider.monto ? sstMonto(lider.monto) : '—']);
      quienes.push(lider.rows);
    }
  }
  return { filas, quienes, periodos };
}
function renderSiniestrosStats() {
  const body = $('pst-body'); if (!_sst.rows) return;
  const anio = $('sst-anio').value, grav = $('sst-gravedad').value, resp = $('sst-resp').value;
  // El mes solo se puede elegir dentro de un año: sin año no hay periodo que recortar
  const selMes = $('sst-mes'); if (selMes) { selMes.disabled = !anio; if (!anio) selMes.value = ''; }
  const mes = anio && selMes ? selMes.value : '';
  const B = _sst.bloque || 'resumen';
  const esVial = B === 'vial' || B === 'mapa';
  // Gravedad y responsable son del siniestro: en las pantallas de conducción estorban
  const fl2 = $('pst-fl-sin2'); if (fl2) fl2.hidden = esVial;
  const R = _sst.rows.filter((s) => (!anio || String(s.fecha || '').slice(0, 4) === anio)
    && (!mes || String(s.fecha || '').slice(5, 7) === mes)
    && (!grav || s.gravedad === grav) && (!resp || s.responsabilidad === resp));
  _pst.tablas = [];
  const periodoTxt = anio ? (mes ? `${PST_MESES[Number(mes) - 1]} de ${anio}` : `Año ${anio}`)
    : 'Últimos 12 meses';
  _pst.filtro = esVial ? periodoTxt
    : [anio ? (mes ? `${PST_MESES[Number(mes) - 1]} de ${anio}` : `Año ${anio}`) : 'Todos los años',
      grav || 'Toda gravedad', resp ? `Responsable: ${resp}` : 'Toda responsabilidad'].join(' · ');
  _sst.filtro = _pst.filtro;
  $('pst-sub').textContent = _pst.filtro;
  const bAct = SST_BLOQUES.find((x) => x.key === (_sst.bloque || 'resumen')) || SST_BLOQUES[0];
  const tit = $('pst-title'); if (tit) tit.textContent = `🚨 ${bAct.label}`;
  body.innerHTML = '';

  // Pestañas (los mismos temas del submenú)
  const tabs = pstEl('div', 'pst-tabs');
  SST_BLOQUES.filter((b) => !b.soloOperacion || isAdmin() || isAuditor()).forEach((b) => {
    const t = pstEl('button', 'pst-tab' + (b.key === (_sst.bloque || 'resumen') ? ' on' : ''), `${b.icon} ${b.label}`);
    t.type = 'button';
    t.onclick = () => { _sst.bloque = b.key; renderSiniestrosStats(); };
    tabs.appendChild(t);
  });
  body.appendChild(tabs);

  // ---- 🗺️ Mapa de riesgo: dónde ocurre ----
  // Va antes del corte por filtros porque no sale de los siniestros sino de los eventos del
  // GPS: aunque no haya un solo siniestro con esa gravedad, el mapa sí tiene qué mostrar.
  if (B === 'mapa') {
    body.appendChild(pstEl('h3', 'pst-sec', '🗺️ Dónde ocurre'));
    const cm = pstEl('div', 'pst-grid'); body.appendChild(cm);
    sstMapaRender(cm, anio, mes);
    return;
  }
  if (!R.length) { body.appendChild(pstEl('div', 'cump-empty', 'No hay siniestros con estos filtros.')); return; }

  // ---- Indicadores ----
  const conResp = R.filter((s) => s.responsabilidad === 'SI');
  const heridos = R.filter((s) => s.gravedad === 'HERIDO');
  const conMonto = R.filter((s) => Number(s.monto || 0) > 0);
  const montoTotal = R.reduce((t, s) => t + Number(s.monto || 0), 0);
  const grupos = sstPorConductor(R);
  const enPerfil = grupos.filter((g) => g.p).length;
  const moviles = new Set(R.map((s) => String(s.numero_interno || '').trim()).filter(Boolean));
  const fechas = R.map((s) => String(s.fecha || '')).filter((f) => /^\d{4}-\d{2}/.test(f)).sort();
  const meses = new Set(fechas.map((f) => f.slice(0, 7)));
  const prom = meses.size ? (R.length / meses.size) : 0;
  const kpis = pstEl('div', 'pst-kpis');
  kpis.append(
    pstTile('Siniestros', pstNum(R.length), fechas.length ? `del ${fechaLegible(fechas[0])} al ${fechaLegible(fechas[fechas.length - 1])}` : '', true, R),
    pstTile('Con responsabilidad del conductor', `${pstPct(conResp.length, R.length)}%`, `${pstNum(conResp.length)} de ${pstNum(R.length)} reportes`, false, conResp),
    pstTile('Con heridos', pstNum(heridos.length), `${pstPct(heridos.length, R.length)}% de los reportes`, false, heridos),
    pstTile('Costo reconocido', sstMonto(montoTotal), `${pstNum(conMonto.length)} reporte(s) con monto`, false, conMonto),
    pstTile('Conductores involucrados', pstNum(grupos.length), `${pstNum(enPerfil)} están en el perfil · ${pstNum(grupos.length - enPerfil)} no`, false, grupos.map(sstComoPersona)),
    pstTile('Promedio por mes', prom.toLocaleString('es-CO', { maximumFractionDigits: 1 }), `${pstNum(moviles.size)} vehículos distintos · ${meses.size} mes(es) con reportes`),
  );
  body.appendChild(kpis);

  const ver = (k) => B === 'resumen' || B === k;
  const seccion = (titulo) => { body.appendChild(pstEl('h3', 'pst-sec', titulo)); const g = pstEl('div', 'pst-grid'); body.appendChild(g); return g; };
  let g;

  // ---- Por año y por mes ----
  if (ver('tiempo')) {
    g = seccion('📅 Cuándo pasan');
    g.appendChild(pstBarras('Siniestros por año', pstContar(R, (s) => (/^\d{4}/.test(String(s.fecha || '')) ? String(s.fecha).slice(0, 4) : null),
      { orden: [...new Set(_sst.rows.map((s) => String(s.fecha || '').slice(0, 4)))].sort() })));
    g.appendChild(pstBarras('Siniestros por mes' + (anio ? ` (${anio})` : ' (todos los años juntos)'),
      pstContar(R, (s) => { const m = Number(String(s.fecha || '').slice(5, 7)); return m >= 1 && m <= 12 ? PST_MESES[m - 1] : null; },
        { orden: PST_MESES })));
    g.appendChild(pstBarras('Día de la semana', pstContar(R, (s) => {
      const f = String(s.fecha || ''); if (!/^\d{4}-\d{2}-\d{2}/.test(f)) return null;
      const d = pstDiaSemana(f.slice(0, 4), f.slice(5, 7), f.slice(8, 10));
      return d ? d.charAt(0).toUpperCase() + d.slice(1) : null;
    }, { orden: PST_DIAS.map((d) => d.charAt(0).toUpperCase() + d.slice(1)) })));
    // Matriz año × mes: la foto completa de la accidentalidad
    const anios = [...new Set(R.map((s) => String(s.fecha || '').slice(0, 4)).filter((a) => /^\d{4}$/.test(a)))].sort();
    const filas = anios.map((a) => {
      const delAnio = R.filter((s) => String(s.fecha || '').startsWith(a));
      const porMes = PST_MESES.map((_, i) => delAnio.filter((s) => Number(String(s.fecha).slice(5, 7)) === i + 1).length);
      return [a, ...porMes, delAnio.length];
    });
    if (anios.length) {
      g.appendChild(sstTarjetaTabla('Año por mes', 'Cada fila abre los siniestros de ese año.',
        { cab: ['Año', ...PST_MESES.map((m) => m.slice(0, 3)), 'Total'], filas,
          quienesPorFila: anios.map((a) => R.filter((s) => String(s.fecha || '').startsWith(a))) }));
    }
  }

  // ---- Conductores (el cruce con el perfil) ----
  if (ver('conductores')) {
    g = seccion('🧑‍✈️ Conductores');
    const TOP = 25;
    const top = grupos.slice(0, TOP);
    g.appendChild(sstTarjetaTabla(`Conductores con más siniestros (top ${Math.min(TOP, grupos.length)})`,
      `${pstNum(grupos.length)} conductor(es) en total. Toca una fila para ver sus reportes.`,
      { cab: ['Conductor', 'Cédula', 'Siniestros', 'Con responsabilidad', 'Con heridos', 'Costo', 'Estado en el perfil', 'Último siniestro'],
        filas: top.map((x) => [x.p?.nombre || x.nombre || '(sin nombre)', x.ced || '—', x.n, x.resp, x.heridos,
          x.monto ? sstMonto(x.monto) : '—', x.p ? x.p.estado || '—' : 'No está en el perfil',
          x.ultimo ? fechaLegible(x.ultimo) : '—']),
        quienesPorFila: top.map((x) => x.rows) }));
    // Reincidencia: cuántos conductores tienen 1, 2, 3-4, 5 o más
    // Reincidencia y estado: aquí lo que hay detrás de cada barra son PERSONAS, no reportes
    const rango = (n) => (n >= 5 ? '5 o más siniestros' : n >= 3 ? '3 a 4 siniestros' : n === 2 ? '2 siniestros' : '1 siniestro');
    const comoPersonas = grupos.map(sstComoPersona);
    g.appendChild(pstBarras('Reincidencia (conductores)', pstContar(comoPersonas, (p) => rango(p._sin),
      { orden: ['1 siniestro', '2 siniestros', '3 a 4 siniestros', '5 o más siniestros'] }),
    { nota: 'Cuántos conductores tienen uno, dos o más siniestros.' }));
    g.appendChild(pstBarras('¿Sigue en la empresa?', pstContar(comoPersonas,
      (p) => (p.estado === 'NO ESTÁ EN EL PERFIL' ? 'No está en el perfil' : p.estado === 'ACTIVO' ? 'Activo' : 'Inactivo'),
      { orden: ['Activo', 'Inactivo', 'No está en el perfil'] }),
    { nota: 'Cruce por cédula con el perfil sociodemográfico.' }));
    // Quién fue el conductor con más reportes en cada AÑO y en cada MES
    const CAB_LIDER = ['Siniestros', 'Conductor con más reportes', 'Cédula', 'Sus siniestros',
      'Estado en el perfil', 'Con responsabilidad', 'Costo'];
    const porAnio = sstLideresPorPeriodo(R, 4);
    if (porAnio.filas.length) {
      g.appendChild(sstTarjetaTabla('Conductor con más reportes, año a año',
        'Quién encabezó la accidentalidad en cada año. Toca la fila para ver sus reportes de ese año.',
        { cab: ['Año', ...CAB_LIDER], filas: porAnio.filas, quienesPorFila: porAnio.quienes }));
    }
    const porMes = sstLideresPorPeriodo(R, 7);
    if (porMes.filas.length) {
      g.appendChild(sstTarjetaTabla('Conductor con más reportes, mes a mes',
        'El conductor que más siniestros reportó en cada mes. Toca la fila para ver sus reportes de ese mes.',
        { cab: ['Mes', ...CAB_LIDER], filas: porMes.filas, quienesPorFila: porMes.quienes }));
    }
    const sinPerfil = grupos.filter((x) => !x.p);
    if (sinPerfil.length) {
      g.appendChild(sstTarjetaTabla('Conductores del reporte que no están en el perfil',
        'Cédulas que vienen en el siniestro y no aparecen en el perfil sociodemográfico: hay que revisarlas.',
        { cab: ['Conductor', 'Cédula', 'Código', 'Siniestros', 'Último siniestro'],
          filas: sinPerfil.map((x) => [x.nombre || '(sin nombre)', x.ced || '—', x.codigo || '—', x.n, x.ultimo ? fechaLegible(x.ultimo) : '—']),
          quienesPorFila: sinPerfil.map((x) => x.rows) }));
    }
  }

  // ---- Vehículos y rutas ----
  if (ver('vehiculos')) {
    g = seccion('🚌 Vehículos y rutas');
    g.appendChild(pstBarras('Móviles con más siniestros', pstContar(R, (s) => (s.numero_interno ? `Móvil ${s.numero_interno}` : null), { top: 15 })));
    g.appendChild(pstBarras('Rutas', pstContar(R, (s) => s.ruta, { top: 15 })));
    g.appendChild(pstBarras('Afiliados', pstContar(R, (s) => s.afiliado, { top: 12 }), { ancha: true }));
  }

  // ---- Causas y gravedad ----
  if (ver('causas')) {
    g = seccion('💥 Qué pasó');
    g.appendChild(pstBarras('Gravedad', pstContar(R, (s) => s.gravedad)));
    g.appendChild(pstBarras('Responsabilidad del conductor', pstContar(R, (s) => s.responsabilidad)));
    g.appendChild(pstBarras('Categorización', pstContar(R, (s) => s.categorizacion, { orden: ['LEVE', 'MODERADO', 'GRAVE'] })));
    g.appendChild(pstBarras('Tipo de lesión o daño', pstContar(R, (s) => s.tipo_lesion, { top: 10 })));
    g.appendChild(pstBarras('Causa probable', pstContar(R, (s) => s.causa, { top: 12 }), { ancha: true }));
    g.appendChild(pstBarras('Factor', pstContar(R, (s) => s.factor)));
    g.appendChild(pstBarras('Estado del reporte', pstContar(R, (s) => s.estado)));
  }

  // ---- Seguridad vial: la conducción, cruzada con los siniestros ----
  if (B === 'vial') {
    body.appendChild(pstEl('h3', 'pst-sec', '🛡️ Conducción y siniestros'));
    const cv = pstEl('div', 'pst-grid'); body.appendChild(cv);
    sstVialRender(cv, R, anio, mes);
    return; // este tema trae sus datos aparte; no comparte tarjetas con los demás
  }

  // ---- Costos ----
  if (ver('costos')) {
    g = seccion('💰 Costos y conciliación');
    const anios = [...new Set(R.map((s) => String(s.fecha || '').slice(0, 4)).filter((a) => /^\d{4}$/.test(a)))].sort();
    g.appendChild(sstTarjetaTabla('Costo por año', 'Solo cuenta lo que tiene monto registrado en el reporte.',
      { cab: ['Año', 'Siniestros', 'Con monto', 'Costo total', 'Promedio'],
        filas: anios.map((a) => {
          const d = R.filter((s) => String(s.fecha || '').startsWith(a));
          const cm = d.filter((s) => Number(s.monto || 0) > 0);
          const tot = d.reduce((t, s) => t + Number(s.monto || 0), 0);
          return [a, d.length, cm.length, sstMonto(tot), cm.length ? sstMonto(tot / cm.length) : '—'];
        }),
        quienesPorFila: anios.map((a) => R.filter((s) => String(s.fecha || '').startsWith(a))) }, false));
    const tipos = [...new Set(R.map((s) => s.tipo_conciliacion).filter(Boolean))];
    g.appendChild(sstTarjetaTabla('Tipo de conciliación',
      'Cómo se resolvió el siniestro y cuánto costó cada forma.',
      { cab: ['Tipo de conciliación', 'Siniestros', 'Costo total'],
        filas: tipos.map((tp) => {
          const d = R.filter((s) => s.tipo_conciliacion === tp);
          return [tp, d.length, sstMonto(d.reduce((t, s) => t + Number(s.monto || 0), 0))];
        }).sort((a, b) => b[1] - a[1]),
        quienesPorFila: tipos.map((tp) => R.filter((s) => s.tipo_conciliacion === tp)) }, false));
    const caros = conMonto.slice().sort((a, b) => Number(b.monto) - Number(a.monto)).slice(0, 15);
    if (caros.length) {
      g.appendChild(sstTarjetaTabla('Los 15 siniestros más costosos', 'Toca una fila para abrir el reporte.',
        { cab: ['Fecha', 'Móvil', 'Placa', 'Conductor', 'Monto', 'Conciliación'],
          filas: caros.map((s) => [fechaLegible(s.fecha), s.numero_interno || '—', s.placa || '—',
            s.conductor_nombre || '—', sstMonto(s.monto), s.tipo_conciliacion || '—']),
          quienesPorFila: caros.map((s) => [s]) }));
    }
  }
}
// ---- 🛡️ Seguridad vial: la conducción (sql/81) cruzada con los siniestros ----
// Los eventos de riesgo (exceso de velocidad real y puerta abierta en marcha) se guardan cada
// madrugada desde SONAR con el conductor que iba manejando. Aquí se juntan con los siniestros
// del mismo periodo, por cédula: quién arriesga y a quién se le están volviendo choques.
// Los doce meses, siempre los mismos: el año manda cuál existe y cuál no
function sstLlenarMeses() {
  const sel = $('sst-mes'); if (!sel || sel.options.length > 1) return;
  PST_MESES.forEach((m, i) => sel.appendChild(Object.assign(document.createElement('option'),
    { value: String(i + 1).padStart(2, '0'), textContent: m })));
}
function sstVialPeriodo(anio, mes) {
  if (anio && mes) {
    const m = String(mes).padStart(2, '0');
    // El día 0 del mes siguiente es el último de este: sirve para los 30, 31 y para febrero
    const fin = new Date(Number(anio), Number(mes), 0);
    return [`${anio}-${m}-01`, `${anio}-${m}-${String(fin.getDate()).padStart(2, '0')}`];
  }
  if (anio) return [`${anio}-01-01`, `${anio}-12-31`];
  const hoy = hoyServidor();
  const d = new Date(hoy + 'T12:00:00'); d.setMonth(d.getMonth() - 12);
  return [d.toISOString().slice(0, 10), hoy];
}
async function sstVialRender(cont, R, anio, mes) {
  const [desde, hasta] = sstVialPeriodo(anio, mes);
  cont.innerHTML = '';
  cont.appendChild(pstEl('div', 'loading', 'Leyendo los eventos de conducción…'));
  let res = null, est = null;
  try {
    const [r1, r2] = await Promise.all([
      sb.rpc('eventos_bus_resumen', { p_desde: desde, p_hasta: hasta }),
      sb.rpc('eventos_bus_estado'),
    ]);
    res = r1.data; est = r2.data;
    if (r1.error) throw r1.error;
  } catch (e) {
    cont.innerHTML = '';
    cont.appendChild(pstEl('div', 'cump-empty', 'No se pudieron leer los eventos: ' + (e.message || e)));
    return;
  }
  cont.innerHTML = '';
  if (!res?.ok) {
    cont.appendChild(pstEl('div', 'cump-empty',
      res?.error || 'Los eventos de conducción los consultan el administrador y los auditores.'));
    return;
  }
  const items = res.items || [];
  // Estado del histórico: hasta qué día está cargado (el cron lo llena de madrugada)
  const cobertura = est?.ok && est.carros
    ? ` · Cobertura de ayer: ${pstNum(est.revisados_ayer || 0)} de ${pstNum(est.carros)} carros`
      + (est.pendientes_ayer ? ` (${pstNum(est.pendientes_ayer)} pendientes)` : ' ✅')
    : '';
  const estTxt = est?.ok
    ? (est.total
      ? `Histórico del ${fechaLegible(est.desde)} al ${fechaLegible(est.hasta)} · ${pstNum(est.total)} eventos guardados${cobertura}`
      : `Todavía no hay histórico guardado: el barrido corre de madrugada (02:00 a 06:50)${cobertura}`)
    : '';
  const umbral = Number(res.umbral_kmh || est?.umbral_kmh || 60);
  const cab = pstEl('div', 'pst-nota',
    `Periodo: ${fechaLegible(desde)} a ${fechaLegible(hasta)} · Umbral de la empresa: ${umbral} km/h${estTxt ? ' · ' + estTxt : ''}`);
  cont.appendChild(cab);
  if (isAdmin()) cont.appendChild(sstVialCargaUI());
  if (!items.length) {
    cont.appendChild(pstEl('div', 'cump-empty',
      'No hay eventos de conducción guardados en este periodo. Si acabas de aplicar sql/81, usa "Traer un día" o espera al barrido de la madrugada.'));
    return;
  }
  // Siniestros del periodo por cédula, para cruzarlos con la conducción
  const sinPorCed = new Map();
  for (const s of R) {
    const f = String(s.fecha || '');
    if (f < desde || f > hasta) continue;
    const c = sinCed(s.conductor_cedula); if (!c) continue;
    if (!sinPorCed.has(c)) sinPorCed.set(c, []);
    sinPorCed.get(c).push(s);
  }
  const filas = [], quienes = [];
  for (const it of items) {
    const c = sinCed(it.cedula);
    const sus = c ? (sinPorCed.get(c) || []) : [];
    const p = c ? _sst.porCedula.get(c) : null;
    filas.push([it.conductor || '(sin viaje asociado)', it.cedula || '—',
      it.rapidos || 0, it.excesos || 0,
      Number(it.peor_exceso) > 0 ? `+${Math.round(Number(it.peor_exceso))} km/h` : '—',
      it.vel_max != null ? `${Math.round(Number(it.vel_max))} km/h` : '—',
      it.puertas || 0, it.dias || 0, sus.length,
      p ? (p.estado || '—') : (it.cedula ? 'No está en el perfil' : '—')]);
    quienes.push(sus); // la fila abre los siniestros de ese conductor en el periodo
  }
  cont.appendChild(sstTarjetaTabla('Conducción de riesgo por conductor',
    `"Más de ${umbral}" son las VECES que pasó del umbral de la empresa aunque la vía permitiera `
    + 'más; "Excesos" es cuando SONAR marcó exceso contra el límite legal de esa vía. Se cuentan '
    + 'episodios, no lecturas: tres minutos seguidos a 65 km/h son una vez, no ocho. '
    + 'La columna de siniestros son los suyos en el mismo periodo: toca la fila para verlos.',
    { cab: ['Conductor', 'Cédula', `Más de ${umbral} km/h`, 'Excesos de la vía', 'Peor exceso',
      'Velocidad máxima', 'Puertas abiertas', 'Días con eventos', 'Siniestros', 'Estado en el perfil'],
    filas, quienesPorFila: quienes }));

  // Los que arriesgan Y además chocaron: el grupo al que hay que intervenir primero
  const criticos = items.map((it) => {
    const c = sinCed(it.cedula);
    return { it, sus: c ? (sinPorCed.get(c) || []) : [] };
  }).filter((x) => x.sus.length && ((x.it.rapidos || 0) > 0 || (x.it.excesos || 0) > 0))
    .sort((a, b) => b.sus.length - a.sus.length || (b.it.rapidos || 0) - (a.it.rapidos || 0));
  if (criticos.length) {
    cont.appendChild(sstTarjetaTabla('Conductores con excesos Y siniestros en el periodo',
      'Son los casos para intervenir primero: vienen corriendo y además ya tuvieron siniestros.',
      { cab: ['Conductor', 'Cédula', `Más de ${umbral} km/h`, 'Excesos de la vía', 'Puertas abiertas', 'Siniestros', 'Con responsabilidad'],
        filas: criticos.map((x) => [x.it.conductor || '(sin nombre)', x.it.cedula || '—',
          x.it.rapidos || 0, x.it.excesos || 0, x.it.puertas || 0, x.sus.length,
          x.sus.filter((s) => s.responsabilidad === 'SI').length]),
        quienesPorFila: criticos.map((x) => x.sus) }));
  }
  sstVialGraficas(cont, desde, hasta);
}

// ---- 📈 Las gráficas de la conducción: cuándo, en qué ruta y qué tan rápido ----
// Las series vienen ya agregadas del servidor (sql/88): son unas pocas decenas de filas por
// gráfica, no el histórico. Cada tarjeta trae su tabla (botón "Ver tabla") y por eso también
// sale en el Excel de la pantalla.
async function sstVialGraficas(cont, desde, hasta) {
  const cargando = pstEl('div', 'loading pst-ancha', 'Armando las gráficas…');
  cont.appendChild(cargando);
  let res = null;
  try {
    const { data, error } = await sb.rpc('eventos_bus_series', { p_desde: desde, p_hasta: hasta });
    if (error) throw error;
    res = data;
  } catch (e) {
    const txt = String(e.message || e);
    cargando.className = 'cump-empty pst-ancha';
    cargando.textContent = 'No se pudieron armar las gráficas: ' + txt
      + (/eventos_bus_series/.test(txt) ? ' — falta ejecutar sql/88.' : '');
    return;
  }
  cargando.remove();
  if (!res || !res.ok) {
    cont.appendChild(pstEl('div', 'cump-empty pst-ancha',
      (res && res.error) || 'No tienes permiso para ver los eventos.'));
    return;
  }
  const umbral = Number(res.umbral_kmh || 60);
  const conteo = (items) => ({ items, sin: 0, total: items.reduce((s, i) => s + i.n, 0) });
  // pstBarras ya devuelve la tarjeta con su gráfica, su nota y su botón "Ver tabla", y de paso
  // registra la tabla para el Excel de la pantalla. El filtro evita repetirla al recargar.
  const grafica = (titulo, nota, items, ancha) => {
    if (!items.length) return;
    _pst.tablas = _pst.tablas.filter((t) => t.titulo !== titulo);
    cont.appendChild(pstBarras(titulo, conteo(items), { nota, ancha: !!ancha }));
  };

  cont.appendChild(pstEl('h3', 'pst-sec pst-ancha', '📈 Cuándo y cómo se conduce'));

  // A qué hora: se rellenan las horas sin eventos entre la primera y la última, para que el
  // valle de la mitad del día se vea como valle y no como si no existiera.
  const mapH = new Map((res.por_hora || []).map((x) => [Number(x.k), Number(x.n || 0)]));
  const horas = [...mapH.keys()].sort((a, b) => a - b);
  const hItems = [];
  if (horas.length) {
    for (let h = horas[0]; h <= horas[horas.length - 1]; h++) {
      hItems.push({ k: `${String(h).padStart(2, '0')}:00`, n: mapH.get(h) || 0 });
    }
  }
  grafica('A qué hora se conduce con riesgo',
    'La hora en que empezó cada episodio, en hora de Colombia. Sirve para saber en qué turno insistir.',
    hItems, true);

  // Día de la semana, de lunes a domingo
  const mapD = new Map((res.por_dia || []).map((x) => [Number(x.k), Number(x.n || 0)]));
  const dItems = [1, 2, 3, 4, 5, 6, 0].map((d) => ({
    k: PST_DIAS[d].charAt(0).toUpperCase() + PST_DIAS[d].slice(1), n: mapD.get(d) || 0,
  })).filter((i) => i.n > 0 || mapD.size);
  grafica('Qué día de la semana', 'Episodios de riesgo por día.', dItems);

  // Mes a mes: es la gráfica que dice si la sensibilización está sirviendo
  const mItems = (res.por_mes || []).map((x) => {
    const a = String(x.k).slice(0, 4), m = Number(String(x.k).slice(5, 7));
    return { k: `${PST_MESES[m - 1] || x.k} ${a}`, n: Number(x.n || 0) };
  });
  grafica('Mes a mes', 'Si la cifra baja, la sensibilización está sirviendo. Con un mes incompleto la comparación todavía no es justa.',
    mItems, true);

  // Rutas
  const rItems = (res.por_ruta || []).map((x) => ({ k: String(x.k), n: Number(x.n || 0) }));
  grafica('Rutas donde más ocurre', 'Las 15 rutas con más episodios en el periodo.', rItems);

  // Qué tan rápido iban
  const vItems = (res.por_velocidad || []).map((x) => ({ k: String(x.k), n: Number(x.n || 0) }));
  grafica('Qué tan rápido iban', `Velocidad más alta de cada episodio. El umbral de la empresa son ${umbral} km/h.`,
    vItems);
}

// Caja del administrador para traer un día a mano (el resto lo hace el cron de la madrugada)
function sstVialCargaUI() {
  const box = pstEl('div', 'vial-carga');
  const inp = Object.assign(document.createElement('input'), { type: 'date', className: 'vial-fecha' });
  const ayer = new Date(); ayer.setDate(ayer.getDate() - 1);
  inp.value = ayer.toISOString().slice(0, 10);
  const btn = Object.assign(document.createElement('button'), { className: 'btn btn-sm', textContent: '⬇️ Traer ese día' });
  const msg = pstEl('span', 'muted');
  btn.onclick = async () => {
    btn.disabled = true; const prev = btn.textContent; btn.textContent = '⏳ Consultando SONAR…';
    msg.textContent = '';
    try {
      const { data, error } = await sb.rpc('eventos_bus_cargar', { p_fecha: inp.value, p_limite: 40 });
      if (error) throw error;
      if (!data?.ok) throw new Error(data?.error || 'no se pudo');
      msg.textContent = `${data.moviles} móvil(es) revisados · ${data.eventos} evento(s) guardados · ${data.pendientes} móvil(es) pendientes`;
      if (!data.pendientes) toast('Día completo.', 'ok');
    } catch (e) {
      msg.textContent = 'Error: ' + (e.message || e);
    } finally { btn.disabled = false; btn.textContent = prev; }
  };
  box.append(pstEl('span', null, 'Se llena solo cada madrugada (02:00 a 06:50) y completa los últimos días. Adelantar un día:'),
    inp, btn, msg);
  return box;
}

// ===================================================================================
// 🗺️ MAPA DE RIESGO — dónde se corre y dónde se rueda con la puerta abierta
// ===================================================================================
// La idea es sensibilizar: un conductor discute un listado, pero no discute ver que en el
// túnel de la 33 su bus pasó de 60 catorce veces este mes. Los puntos NO se bajan uno por
// uno (un año de histórico son millones): la RPC eventos_bus_mapa (sql/86) los agrupa en el
// servidor en celdas de ~110 m y devuelve las que más veces se repiten.
// Cuenta VECES (episodios), no lecturas: tres minutos corriendo son un hecho, no ocho.
const SST_MAPA_COLOR = { 'VELOCIDAD': '#C0392B', 'PUERTA ABIERTA': '#1F6FB2' };
const SST_MAPA_NOMBRE = { 'VELOCIDAD': '🚦 Velocidad', 'PUERTA ABIERTA': '🚪 Puerta abierta' };
const _sstMapa = { cat: null, map: null, marcas: [] };

async function sstMapaRender(cont, anio, mes) {
  const [desde, hasta] = sstVialPeriodo(anio, mes);
  cont.innerHTML = '';
  const card = pstEl('section', 'pst-card pst-ancha');
  const head = pstEl('div', 'pst-card-h'); const tt = pstEl('div');
  tt.appendChild(pstEl('h4', null, 'Mapa de los puntos de riesgo'));
  const nota = pstEl('div', 'pst-nota');
  tt.appendChild(nota); head.appendChild(tt);
  const cuerpo = pstEl('div', 'pst-card-b');

  // Qué se mira: las dos conductas juntas o una sola
  const chips = pstEl('div', 'vial-chips');
  const zona = pstEl('div');
  cuerpo.append(chips, zona);
  card.append(head, cuerpo);
  cont.appendChild(card);
  const tabla = pstEl('div', 'pst-ancha'); cont.appendChild(tabla);
  const vehiculos = pstEl('div', 'pst-ancha'); cont.appendChild(vehiculos);

  const opciones = [{ v: null, t: 'Las dos' }, { v: 'VELOCIDAD', t: SST_MAPA_NOMBRE.VELOCIDAD },
                    { v: 'PUERTA ABIERTA', t: SST_MAPA_NOMBRE['PUERTA ABIERTA'] }];
  const pintarChips = () => {
    chips.innerHTML = '';
    opciones.forEach((o) => {
      const b = pstEl('button', 'evt-chip' + (_sstMapa.cat === o.v ? ' evt-on' : ''), o.t);
      b.type = 'button';
      b.onclick = () => { if (_sstMapa.cat === o.v) return; _sstMapa.cat = o.v; pintarChips(); cargar(); };
      chips.appendChild(b);
    });
  };

  const cargar = async () => {
    zona.innerHTML = ''; tabla.innerHTML = '';
    zona.appendChild(pstEl('div', 'loading', 'Buscando dónde ocurren los eventos…'));
    let res = null;
    try {
      const { data, error } = await sb.rpc('eventos_bus_mapa',
        { p_desde: desde, p_hasta: hasta, p_categoria: _sstMapa.cat, p_limite: 600 });
      if (error) throw error;
      res = data;
    } catch (e) {
      const txt = String(e.message || e);
      zona.innerHTML = '';
      zona.appendChild(pstEl('div', 'cump-empty', 'No se pudo leer el mapa: ' + txt
        + (/eventos_bus_mapa/.test(txt) ? ' — falta ejecutar sql/86.' : '')));
      return;
    }
    zona.innerHTML = '';
    if (!res || !res.ok) {
      zona.appendChild(pstEl('div', 'cump-empty', (res && res.error) || 'No tienes permiso para ver los eventos.'));
      return;
    }
    const pts = res.items || [];
    const sinPunto = Number(res.sin_punto || 0);
    nota.textContent = `Periodo: ${fechaLegible(desde)} a ${fechaLegible(hasta)}`
      + ` · Cada círculo agrupa lo que pasó en unos ${res.celda_m || 110} metros a la redonda`
      + ' · El tamaño es cuántas VECES, no cuántas lecturas'
      + (sinPunto ? ` · ⚠️ ${pstNum(sinPunto)} evento(s) llegaron sin coordenada y no salen en el mapa` : '');
    if (!pts.length) {
      zona.appendChild(pstEl('div', 'cump-empty',
        'No hay eventos con coordenada en este periodo. El barrido corre de madrugada (02:00 a 06:50).'));
      return;
    }
    sstMapaPintar(zona, pts, { desde, hasta });
    tabla.appendChild(sstMapaTop(pts, { desde, hasta }));
  };

  pintarChips();
  await cargar();
  sstMapaVehiculos(vehiculos, desde, hasta);   // no cambia con el chip: va aparte
}

// El mapa: círculos de área proporcional, con anillo blanco para que se despeguen del fondo
function sstMapaPintar(zona, pts, ctx) {
  const el = pstEl('div', 'vial-mapa'); zona.appendChild(el);
  zona.appendChild(sstMapaLeyenda(pts));
  if (_sstMapa.map) { try { _sstMapa.map.remove(); } catch (_) { /* ya no existía */ } _sstMapa.map = null; }
  const map = L.map(el, { scrollWheelZoom: true }).setView([6.244, -75.575], 12); // Medellín
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
    { maxZoom: 19, attribution: '© OpenStreetMap' }).addTo(map);
  _sstMapa.map = map; _sstMapa.marcas = [];
  const maxV = Math.max(...pts.map((p) => Number(p.veces || 1)), 1);
  pts.forEach((p) => {
    const col = SST_MAPA_COLOR[p.categoria] || '#6b7280';
    const r = 6 + 20 * Math.sqrt(Number(p.veces || 1) / maxV);   // el área crece con las veces
    const m = L.circleMarker([p.lat, p.lon], {
      radius: r, color: '#fff', weight: 2, fillColor: col, fillOpacity: 0.82,
    }).addTo(map);
    m.bindTooltip(`${sstMapaSitio(p)} — ${pstNum(p.veces)} vez(ces)`, { direction: 'top' });
    m.bindPopup(sstMapaPopup(p, ctx));
    _sstMapa.marcas.push(m);
  });
  try { map.fitBounds(L.latLngBounds(pts.map((p) => [p.lat, p.lon])).pad(0.15)); } catch (_) { /* un solo punto */ }
  setTimeout(() => { try { map.invalidateSize(); } catch (_) { /* la vista cambió */ } }, 120);
}

function sstMapaSitio(p) { return p.direccion || `${Number(p.lat).toFixed(4)}, ${Number(p.lon).toFixed(4)}`; }

function sstMapaPopup(p, ctx) {
  const d = pstEl('div', 'vial-pop');
  d.appendChild(pstEl('div', 'vial-pop-t', sstMapaSitio(p)));
  const c = pstEl('div', 'vial-pop-c', SST_MAPA_NOMBRE[p.categoria] || p.categoria || '');
  c.style.color = SST_MAPA_COLOR[p.categoria] || '#374151';
  d.appendChild(c);
  const fila = (k, v) => {
    if (v == null || v === '') return;
    const f = pstEl('div'); f.appendChild(pstEl('b', null, k + ': '));
    f.appendChild(document.createTextNode(String(v))); d.appendChild(f);
  };
  fila('Veces', pstNum(p.veces));
  fila('Días distintos', pstNum(p.dias));
  fila('Conductores', pstNum(p.conductores));
  fila('Vehículos', pstNum(p.moviles));
  fila('Velocidad máxima', p.vel_max != null ? `${p.vel_max} km/h` : null);
  fila('Quien más se repite', p.conductor_top);
  fila('Ruta', p.ruta);
  fila('Última vez', p.ultimo ? fechaLegible(p.ultimo) : null);
  // Cada punto se puede abrir: quién, cuándo y a qué velocidad pasó por aquí
  const b = pstEl('button', 'btn btn-sm vial-pop-b', '👁️ Ver los eventos de este punto');
  b.type = 'button';
  b.onclick = () => evbVerDetalle(sstMapaSitio(p),
    { desde: ctx.desde, hasta: ctx.hasta, categoria: p.categoria, lat: p.lat, lon: p.lon });
  d.appendChild(b);
  return d;
}

function sstMapaLeyenda(pts) {
  const cats = [...new Set(pts.map((p) => p.categoria))];
  const l = pstEl('div', 'vial-leyenda');
  cats.forEach((c) => {
    const w = pstEl('span', 'vial-ley-p');
    const d = pstEl('span', 'vial-ley-d'); d.style.background = SST_MAPA_COLOR[c] || '#6b7280';
    w.append(d, pstEl('span', null, SST_MAPA_NOMBRE[c] || c));
    l.appendChild(w);
  });
  l.appendChild(pstEl('span', 'vial-ley-n', 'El círculo crece con el número de veces · Toca un punto para ver el detalle'));
  return l;
}

// Los puntos negros, en tabla: se puede ordenar la intervención y llevarla a la charla
function sstMapaTop(pts, ctx) {
  const top = pts.slice(0, 15);
  const cab = ['Dónde', 'Conducta', 'Veces', 'Días', 'Conductores', 'Vehículos', 'Vel. máx', 'Última vez', ''];
  const filas = top.map((p) => [sstMapaSitio(p), SST_MAPA_NOMBRE[p.categoria] || p.categoria || '—',
    Number(p.veces || 0), Number(p.dias || 0), Number(p.conductores || 0), Number(p.moviles || 0),
    p.vel_max != null ? `${p.vel_max} km/h` : '—', p.ultimo ? fechaLegible(p.ultimo) : '—']);
  const titulo = 'Los 15 puntos donde más se repite';
  const nota = 'Toca una fila y el mapa te lleva al punto. Estos son los sitios para señalizar y para nombrar en la charla de sensibilización.';
  const card = pstEl('section', 'pst-card pst-ancha');
  const head = pstEl('div', 'pst-card-h'); const tt = pstEl('div');
  tt.appendChild(pstEl('h4', null, titulo)); tt.appendChild(pstEl('div', 'pst-nota', nota));
  head.appendChild(tt);
  const cuerpo = pstEl('div', 'pst-card-b pst-tabla-wrap');
  const t = pstEl('table', 'pst-tabla');
  const thead = pstEl('thead'); const tr = pstEl('tr');
  cab.forEach((c) => tr.appendChild(pstEl('th', null, c)));
  thead.appendChild(tr); t.appendChild(thead);
  const tb = pstEl('tbody');
  filas.forEach((f, i) => {
    const r = pstEl('tr');
    f.forEach((v) => r.appendChild(pstEl('td', null, typeof v === 'number' ? pstNum(v) : v)));
    r.classList.add('pst-clic'); r.tabIndex = 0; r.title = 'Ver en el mapa';
    const ir = () => {
      const m = _sstMapa.marcas[i]; if (!m || !_sstMapa.map) return;
      _sstMapa.map.setView(m.getLatLng(), 17, { animate: true });
      m.openPopup();
      _sstMapa.map.getContainer().scrollIntoView({ behavior: 'smooth', block: 'center' });
    };
    // El ojo abre el detalle sin tener que ir al mapa
    const ver = pstEl('button', 'btn btn-sm', '👁️');
    ver.type = 'button'; ver.title = 'Ver los eventos de este punto';
    ver.onclick = (ev) => {
      ev.stopPropagation();
      evbVerDetalle(sstMapaSitio(top[i]),
        { desde: ctx.desde, hasta: ctx.hasta, categoria: top[i].categoria, lat: top[i].lat, lon: top[i].lon });
    };
    const tdv = pstEl('td'); tdv.appendChild(ver); r.appendChild(tdv);
    r.addEventListener('click', ir);
    r.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); ir(); } });
    tb.appendChild(r);
  });
  t.appendChild(tb); cuerpo.appendChild(t); card.append(head, cuerpo);
  _pst.tablas = _pst.tablas.filter((t) => t.titulo !== titulo);
  _pst.tablas.push({ titulo, nota, cab, filas });
  return card;
}

// ---- El detalle que hay detrás de cada número (punto del mapa, vehículo o conductor) ----
// Los eventos no se bajan con la pantalla: se piden solo cuando alguien abre un número, y con
// tope, para que un año de histórico no se convierta en una descarga de millones de filas.
let _evbLista = { titulo: '', filas: [] };
function evbListaModal() {
  let m = $('evb-modal');
  if (m) return m;
  m = document.createElement('div');
  m.id = 'evb-modal'; m.className = 'modal'; m.hidden = true;
  m.innerHTML = `<div class="modal-card pstp-card">
    <div class="modal-head"><h3></h3><span class="spacer"></span>
      <button type="button" class="icon-btn" data-x aria-label="Cerrar">✕</button></div>
    <div class="pstp-sub"></div>
    <div class="pstp-body"></div>
    <div class="modal-foot"><button type="button" class="btn btn-sm" data-excel>⬇️ Excel</button>
      <span class="spacer"></span><button type="button" class="btn" data-x>Cerrar</button></div>
  </div>`;
  m.addEventListener('click', (e) => { if (e.target === m || e.target.closest('[data-x]')) m.hidden = true; });
  m.querySelector('[data-excel]').onclick = () => evbExportar(_evbLista.titulo, _evbLista.filas);
  document.body.appendChild(m);
  return m;
}

async function evbVerDetalle(titulo, f) {
  const m = evbListaModal();
  m.querySelector('h3').textContent = `🚦 ${titulo}`;
  m.querySelector('.pstp-sub').textContent = '';
  const body = m.querySelector('.pstp-body');
  body.innerHTML = '<div class="loading">Leyendo los eventos…</div>';
  m.hidden = false;
  let res = null;
  try {
    const { data, error } = await sb.rpc('eventos_bus_detalle', {
      p_desde: f.desde, p_hasta: f.hasta, p_categoria: f.categoria || null,
      p_lat: f.lat == null ? null : f.lat, p_lon: f.lon == null ? null : f.lon,
      p_movil: f.movil || null, p_cedula: f.cedula || null, p_limite: 300,
    });
    if (error) throw error;
    res = data;
  } catch (e) {
    const txt = String(e.message || e);
    body.innerHTML = '';
    body.appendChild(pstEl('div', 'cump-empty', 'No se pudo leer el detalle: ' + txt
      + (/eventos_bus_detalle/.test(txt) ? ' — falta ejecutar sql/87.' : '')));
    return;
  }
  if (!res || !res.ok) {
    body.innerHTML = '';
    body.appendChild(pstEl('div', 'cump-empty', (res && res.error) || 'No tienes permiso para ver los eventos.'));
    return;
  }
  const filas = res.items || [];
  _evbLista = { titulo, filas };
  m.querySelector('.pstp-sub').textContent = res.total > filas.length
    ? `${pstNum(res.total)} lectura(s) · se muestran las ${pstNum(filas.length)} más recientes`
    : `${pstNum(filas.length)} lectura(s) del GPS`;
  body.innerHTML = '';
  if (!filas.length) { body.appendChild(pstEl('div', 'cump-empty', 'No hay eventos aquí en este periodo.')); return; }
  const tabla = pstEl('table', 'pst-tabla pstp-tabla');
  const cab = ['Cuándo', 'Móvil', 'Conductor', 'Ruta', 'Qué pasó', 'Velocidad', 'Límite vía', 'Sobre la vía', 'Dónde'];
  const tr = pstEl('tr'); cab.forEach((c) => tr.appendChild(pstEl('th', null, c)));
  const thead = pstEl('thead'); thead.appendChild(tr); tabla.appendChild(thead);
  const tb = pstEl('tbody');
  filas.forEach((e) => {
    const r = pstEl('tr');
    r.appendChild(pstEl('td', null, evbCuando(e.cuando)));
    r.appendChild(pstEl('td', null, e.movil || '—'));
    r.appendChild(pstEl('td', 'pstp-nom', e.conductor || '(sin viaje asociado)'));
    r.appendChild(pstEl('td', null, e.ruta || '—'));
    r.appendChild(pstEl('td', null, e.evento || '—'));
    // La velocidad se marca cuando pasa del umbral de la empresa: es la regla interna
    const tdv = pstEl('td', e.sobre_umbral ? 'evb-alta' : null, e.velocidad != null ? `${e.velocidad} km/h` : '—');
    r.appendChild(tdv);
    r.appendChild(pstEl('td', null, e.limite ? `${e.limite} km/h` : '—'));
    r.appendChild(pstEl('td', e.sobre_via ? 'evb-alta' : null, e.sobre_via ? `+${e.sobre_via}` : '—'));
    r.appendChild(pstEl('td', null, e.direccion || '—'));
    tb.appendChild(r);
  });
  tabla.appendChild(tb);
  body.appendChild(tabla);
}

function evbCuando(s) {
  const t = String(s || '');
  if (!/^\d{4}-\d{2}-\d{2}/.test(t)) return t || '—';
  return `${t.slice(8, 10)}/${t.slice(5, 7)}/${t.slice(0, 4)} ${t.slice(11, 16)}`;
}

async function evbExportar(titulo, filas) {
  if (!filas || !filas.length) { toast('No hay eventos para exportar.', 'err'); return; }
  try {
    const XLSX = await import('https://esm.sh/xlsx@0.18.5');
    const aoa = [[titulo], [`${filas.length} lectura(s) del GPS`], [`Generado: ${fmtFechaHora(new Date())}`], [],
      ['Cuándo', 'Móvil', 'Conductor', 'Cédula', 'Ruta', 'Qué pasó', 'Velocidad', 'Límite vía',
        'Sobre la vía', 'Más de 60', 'Dónde', 'Latitud', 'Longitud']];
    filas.forEach((e) => aoa.push([e.cuando ? celdaFechaXlsx(e.cuando) : '', e.movil || '', e.conductor || '',
      e.conductor_cedula || '', e.ruta || '', e.evento || '', e.velocidad ?? '', e.limite ?? '',
      e.sobre_via ?? '', e.sobre_umbral ? 'SI' : 'NO', e.direccion || '', e.lat ?? '', e.lon ?? '']));
    const ws = XLSX.utils.aoa_to_sheet(aoa, { cellDates: true });
    ws['!cols'] = [{ wch: 18 }, { wch: 8 }, { wch: 30 }, { wch: 12 }, { wch: 10 }, { wch: 24 }, { wch: 10 },
      { wch: 10 }, { wch: 11 }, { wch: 10 }, { wch: 40 }, { wch: 11 }, { wch: 11 }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Conducción');
    XLSX.writeFile(wb, `conduccion_${hoyServidor()}.xlsx`);
  } catch (e) {
    toast('No se pudo generar el Excel: ' + (e.message || e), 'err');
  }
}

// ---- Top de vehículos: con qué carros se anda pasando de lo reglamentario ----
async function sstMapaVehiculos(cont, desde, hasta) {
  cont.innerHTML = '';
  cont.appendChild(pstEl('div', 'loading', 'Armando el top de vehículos…'));
  let res = null;
  try {
    const { data, error } = await sb.rpc('eventos_bus_vehiculos', { p_desde: desde, p_hasta: hasta });
    if (error) throw error;
    res = data;
  } catch (e) {
    const txt = String(e.message || e);
    cont.innerHTML = '';
    cont.appendChild(pstEl('div', 'cump-empty', 'No se pudo leer el top de vehículos: ' + txt
      + (/eventos_bus_vehiculos/.test(txt) ? ' — falta ejecutar sql/87.' : '')));
    return;
  }
  cont.innerHTML = '';
  if (!res || !res.ok) {
    cont.appendChild(pstEl('div', 'cump-empty', (res && res.error) || 'No tienes permiso para ver los eventos.'));
    return;
  }
  const items = res.items || [];
  if (!items.length) { cont.appendChild(pstEl('div', 'cump-empty', 'Ningún vehículo con eventos en este periodo.')); return; }
  const umbral = Number(res.umbral_kmh || 60);
  const top = items.slice(0, 20);
  const titulo = 'Vehículos que más se pasan de lo reglamentario';
  const nota = `"Pasó el límite de la vía" compara la velocidad contra el límite que SONAR da para esa calle.`
    + ` "Más de ${umbral} km/h" es la regla interna de la empresa. Toca un móvil para ver sus eventos uno por uno.`;
  const cab = ['Móvil', 'Pasó el límite de la vía', `Más de ${umbral} km/h`, 'Puerta abierta',
    'Vel. máx', 'Mayor exceso', 'Días', 'Conductores', 'Ruta', 'Última vez'];
  const filas = top.map((v) => [v.movil || '—', Number(v.sobre_via || 0), Number(v.sobre_umbral || 0),
    Number(v.puertas || 0), v.vel_max != null ? `${v.vel_max} km/h` : '—',
    v.sobre_max != null && v.sobre_max > 0 ? `+${v.sobre_max} km/h` : '—',
    Number(v.dias || 0), Number(v.conductores || 0), v.ruta || '—',
    v.ultimo ? fechaLegible(v.ultimo) : '—']);
  const card = pstEl('section', 'pst-card pst-ancha');
  const head = pstEl('div', 'pst-card-h'); const tt = pstEl('div');
  tt.appendChild(pstEl('h4', null, titulo)); tt.appendChild(pstEl('div', 'pst-nota', nota));
  head.appendChild(tt);
  const cuerpo = pstEl('div', 'pst-card-b pst-tabla-wrap');
  const tabla = pstEl('table', 'pst-tabla');
  const tr = pstEl('tr'); cab.forEach((c) => tr.appendChild(pstEl('th', null, c)));
  const thead = pstEl('thead'); thead.appendChild(tr); tabla.appendChild(thead);
  const tb = pstEl('tbody');
  filas.forEach((f, i) => {
    const r = pstEl('tr');
    f.forEach((v) => r.appendChild(pstEl('td', null, typeof v === 'number' ? pstNum(v) : v)));
    r.classList.add('pst-clic'); r.tabIndex = 0; r.title = 'Ver los eventos de este vehículo';
    const abrir = () => evbVerDetalle(`Móvil ${top[i].movil}`, { desde, hasta, movil: top[i].movil });
    r.addEventListener('click', abrir);
    r.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); abrir(); } });
    tb.appendChild(r);
  });
  tabla.appendChild(tb); cuerpo.appendChild(tabla); card.append(head, cuerpo);
  _pst.tablas = _pst.tablas.filter((t) => t.titulo !== titulo);
  _pst.tablas.push({ titulo, nota, cab, filas });
  cont.appendChild(card);
}

async function exportarSiniestrosStats() {
  if (!_pst.tablas.length) { toast('No hay estadísticas para exportar.', 'err'); return; }
  const btn = $('pst-excel'); const prev = btn.textContent; btn.disabled = true; btn.textContent = '⏳ Generando…';
  try {
    const XLSX = await import('https://esm.sh/xlsx@0.18.5');
    const aoa = [['Estadísticas de siniestros — Autobuses El Poblado'], [`Filtro: ${_sst.filtro || ''}`],
      [`Generado: ${fmtFechaHora(new Date())}`], []];
    for (const t of _pst.tablas) {
      aoa.push([t.titulo]); if (t.nota) aoa.push([t.nota]);
      aoa.push(t.cab); t.filas.forEach((f) => aoa.push(f)); aoa.push([]);
    }
    const ws = XLSX.utils.aoa_to_sheet(aoa);
    ws['!cols'] = [{ wch: 40 }, { wch: 14 }, { wch: 14 }, { wch: 14 }, { wch: 14 }, { wch: 16 }, { wch: 20 }, { wch: 16 }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Siniestros');
    const blob = new Blob([XLSX.write(wb, { type: 'array', bookType: 'xlsx' })], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob); a.download = `Estadisticas_siniestros_${hoyServidor()}.xlsx`; a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    toast('Excel generado', 'ok');
  } catch (e) {
    toast('No se pudo generar el Excel: ' + (e.message || e), 'err');
  } finally { btn.disabled = false; btn.textContent = prev; }
}

// ---- Lista de reportes detrás de un número (el detalle de cada dato) ----
let _sinLista = { titulo: '', filas: [] };
function sinListaModal() {
  let m = $('sinl-modal');
  if (m) return m;
  m = document.createElement('div');
  m.id = 'sinl-modal'; m.className = 'modal'; m.hidden = true;
  m.innerHTML = `<div class="modal-card pstp-card">
    <div class="modal-head"><h3></h3><span class="spacer"></span>
      <button type="button" class="icon-btn" data-x aria-label="Cerrar">✕</button></div>
    <div class="pstp-sub"></div>
    <div class="pstp-body"></div>
    <div class="modal-foot"><button type="button" class="btn btn-sm" data-excel>⬇️ Excel</button>
      <span class="spacer"></span><button type="button" class="btn" data-x>Cerrar</button></div>
  </div>`;
  m.addEventListener('click', (e) => { if (e.target === m || e.target.closest('[data-x]')) m.hidden = true; });
  m.querySelector('[data-excel]').onclick = () => sinExportarLista(_sinLista.titulo, _sinLista.filas);
  document.body.appendChild(m);
  return m;
}
function sinVerLista(titulo, filas) {
  const lista = (filas || []).slice().sort((a, b) => String(b.fecha || '').localeCompare(String(a.fecha || '')));
  _sinLista = { titulo, filas: lista };
  const m = sinListaModal();
  m.querySelector('h3').textContent = `🚨 ${titulo}`;
  m.querySelector('.pstp-sub').textContent = `${pstNum(lista.length)} siniestro(s) · toca uno para ver el reporte completo`;
  const body = m.querySelector('.pstp-body');
  body.innerHTML = '';
  if (!lista.length) { body.appendChild(pstEl('div', 'cump-empty', 'No hay siniestros en este grupo.')); m.hidden = false; return; }
  const tabla = pstEl('table', 'pst-tabla pstp-tabla');
  const cab = ['Fecha', 'Móvil', 'Placa', 'Ruta', 'Conductor', 'Gravedad', 'Responsable', 'Monto'];
  const tr = pstEl('tr'); cab.forEach((c) => tr.appendChild(pstEl('th', null, c)));
  const thead = pstEl('thead'); thead.appendChild(tr); tabla.appendChild(thead);
  const tb = pstEl('tbody');
  for (const s of lista) {
    const r = pstEl('tr');
    [fechaLegible(s.fecha), s.numero_interno || '—', s.placa || '—', s.ruta || '—',
      s.conductor_nombre || '—', s.gravedad || '—', s.responsabilidad || '—',
      Number(s.monto || 0) ? sstMonto(s.monto) : '—'].forEach((v, i) => r.appendChild(pstEl('td', i === 4 ? 'pstp-nom' : null, v)));
    r.classList.add('pst-clic'); r.tabIndex = 0; r.title = 'Abrir el reporte completo';
    const abrir = () => sinAbrirPorKey(s.key);
    r.addEventListener('click', abrir);
    r.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); abrir(); } });
    tb.appendChild(r);
  }
  tabla.appendChild(tb);
  body.appendChild(tabla);
  m.hidden = false;
}
// Abre la ficha del siniestro desde una lista (hay que traer la fila completa)
async function sinAbrirPorKey(key) {
  if (!key) return;
  showBusy('Abriendo el reporte…');
  try {
    const { data, error } = await sb.from('siniestros').select('*').eq('key', key).single();
    if (error) throw error;
    openSiniestro(data);
  } catch (e) {
    toast('No se pudo abrir el reporte: ' + (e.message || e), 'err');
  } finally { hideBusy(); }
}
async function sinExportarLista(titulo, filas) {
  if (!filas || !filas.length) { toast('No hay siniestros para exportar.', 'err'); return; }
  try {
    const XLSX = await import('https://esm.sh/xlsx@0.18.5');
    const aoa = [[titulo], [`${filas.length} siniestro(s) · ${_sst.filtro || ''}`], [`Generado: ${fmtFechaHora(new Date())}`], [],
      ['Fecha', 'Móvil', 'Placa', 'Ruta', 'Afiliado', 'Conductor', 'Cédula', 'Código', 'Gravedad',
        'Responsable', 'Categorización', 'Tipo de lesión', 'Causa', 'Monto', 'Conciliación', 'Estado']];
    filas.forEach((s) => aoa.push([s.fecha ? celdaFechaXlsx(s.fecha) : '', s.numero_interno || '', s.placa || '',
      s.ruta || '', s.afiliado || '', s.conductor_nombre || '', s.conductor_cedula || '', s.conductor_codigo || '',
      s.gravedad || '', s.responsabilidad || '', s.categorizacion || '', s.tipo_lesion || '', s.causa || '',
      Number(s.monto || 0) || '', s.tipo_conciliacion || '', s.estado || '']));
    const ws = XLSX.utils.aoa_to_sheet(aoa, { cellDates: true });
    ws['!cols'] = [{ wch: 12 }, { wch: 8 }, { wch: 9 }, { wch: 10 }, { wch: 26 }, { wch: 30 }, { wch: 12 }, { wch: 8 },
      { wch: 13 }, { wch: 12 }, { wch: 14 }, { wch: 22 }, { wch: 30 }, { wch: 12 }, { wch: 16 }, { wch: 12 }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Siniestros');
    const blob = new Blob([XLSX.write(wb, { type: 'array', bookType: 'xlsx' })], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `${String(titulo).replace(/[^\wáéíóúñÁÉÍÓÚÑ ]+/g, ' ').trim().replace(/\s+/g, '_')}_${hoyServidor()}.xlsx`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    toast('Excel generado', 'ok');
  } catch (e) {
    toast('No se pudo generar el Excel: ' + (e.message || e), 'err');
  }
}

