// ===== Recorrido del bus (SONAR GET_TrackerEventsHistory) =====
let recLayer = null;   // capa Leaflet con el recorrido dibujado
let _recVeh = null;    // { mid, movil, ruta } del móvil elegido
let _recDesp = [];     // despachos cargados del móvil (para el selector)
// "HH:MM" (24h) -> "h:MM a.m./p.m." (formato colombiano)
function _hora12(hhmm) {
  if (!hhmm) return '';
  const [h, m] = String(hhmm).split(':').map(Number);
  const ap = h < 12 ? 'a.m.' : 'p.m.';
  const h12 = (h % 12) || 12;
  return `${h12}:${_pad2(m)} ${ap}`;
}
// Suma minutos a una hora local (fecha+hh:mm); devuelve {fecha, hhmm} (maneja cruce de día)
function _finConMinutos(fecha, hhmm, minutos) {
  const [h, m] = hhmm.split(':').map(Number);
  const d = new Date(fecha + 'T00:00:00'); d.setMinutes(h * 60 + m + (minutos || 0));
  const f = `${d.getFullYear()}-${_pad2(d.getMonth() + 1)}-${_pad2(d.getDate())}`;
  return { fecha: f, hhmm: `${_pad2(d.getHours())}:${_pad2(d.getMinutes())}` };
}
// CONDICIÓN: el recorrido solo se muestra del despacho de HOY, consultado EN VIVO a SONAR.
async function abrirRecorrido(r) {
  _recVeh = { mid: r.mid, movil: r.movil, ruta: r.ruta };
  _recDesp = [];
  $('rec-movil').textContent = `${r.movil || ''}${r.ruta ? ' · ' + r.ruta : ''}`;
  $('rec-msg').textContent = '';
  const sel = $('rec-despacho'); sel.innerHTML = '<option value="">Consultando despachos de hoy…</option>';
  $('rec-ver').disabled = true;
  $('rec-modal').hidden = false;
  if (!r.mid) { sel.innerHTML = '<option value="">—</option>'; $('rec-msg').textContent = 'Este móvil no tiene Id GPS en SONAR.'; return; }
  // Despachos de HOY en vivo desde SONAR (rango del día Bogotá expresado en UTC)
  const hoy = hoyServidor();
  const pIni = `${hoy} 05:00:00`; // 00:00 Bogotá → UTC
  const pFin = new Date().toISOString().slice(0, 19).replace('T', ' '); // ahora en UTC
  const { data, error } = await sb.rpc('despachos_sonar', { p_mid: r.mid, p_ini: pIni, p_fin: pFin });
  if (error) { sel.innerHTML = '<option value="">—</option>'; $('rec-msg').textContent = 'Error: ' + error.message; return; }
  if (!data || !data.ok) { sel.innerHTML = '<option value="">—</option>'; $('rec-msg').textContent = 'No se pudo consultar SONAR: ' + (data?.error || '?'); return; }
  // solo HOY, sin cancelados. OJO: 'minutos' de SONAR mide hasta el cierre del turno, NO la vuelta;
  // el fin de cada despacho = inicio del siguiente (el último, una ventana de 2.5 h por defecto).
  const base = (data.items || []).filter((d) => d.fecha === hoy && d.cancelado !== 'true')
    .map((d) => ({ fecha: d.fecha, ini: (d.hora || '').slice(0, 5), ruta: d.ruta || '', estado: d.corriendo === 'true' ? 'en curso' : 'finalizado' }))
    .filter((d) => d.ini)
    .sort((a, b) => _hmToMin(a.ini) - _hmToMin(b.ini));
  _recDesp = base.map((d, i) => {
    if (i < base.length - 1) return { ...d, fin: base[i + 1].ini, finFecha: d.fecha };
    const f = _finConMinutos(d.fecha, d.ini, 150); // último: ventana amplia
    return { ...d, fin: f.hhmm, finFecha: f.fecha };
  });
  if (!_recDesp.length) {
    sel.innerHTML = '<option value="">—</option>';
    $('rec-msg').textContent = '🚫 Este vehículo no tiene despacho hoy. El recorrido solo se muestra del despacho de hoy.';
    return;
  }
  sel.innerHTML = _recDesp.map((d, i) => `<option value="${i}">${esc(_hora12(d.ini))}–${esc(_hora12(d.fin))}${d.ruta ? ' · ' + esc(d.ruta) : ''} · ${esc(d.estado)}</option>`).join('');
  $('rec-ver').disabled = false;
}
async function verRecorrido() {
  if (!_recVeh) return;
  const sel = $('rec-despacho'); const msg = $('rec-msg');
  const d = _recDesp[+sel.value];
  if (!d) { msg.textContent = 'Elige un despacho. El recorrido solo se muestra para vehículos despachados.'; return; }
  const btn = $('rec-ver'); const t = btn.textContent; btn.disabled = true; btn.textContent = 'Cargando…';
  msg.textContent = 'Consultando SONAR…';
  try {
    const { data, error } = await sb.rpc('sonar_recorrido', { p_mid: _recVeh.mid, p_desde: `${d.fecha} ${d.ini}`, p_hasta: `${d.finFecha} ${d.fin}` });
    if (error) { msg.textContent = 'Error: ' + error.message; return; }
    if (!data || !data.ok) { msg.textContent = 'No se pudo: ' + (data?.error || '?'); return; }
    const pts = (data.puntos || []).filter((p) => p.lat != null && p.lon != null);
    if (!pts.length) { msg.textContent = 'El despacho no tiene reportes GPS en ese rango.'; return; }
    dibujarRecorrido(pts, _recVeh.movil, d.ruta || _recVeh.ruta);
    $('rec-modal').hidden = true;
    closeVehSheet();
    toast(`Recorrido de ${_recVeh.movil}: ${pts.length} puntos · ${_hora12(pts[0].t)}–${_hora12(pts[pts.length - 1].t)}`, 'ok');
  } catch (e) { msg.textContent = e.message || String(e); }
  finally { btn.disabled = false; btn.textContent = t; }
}
let _recPts = [];      // puntos del recorrido actual
let _recCursor = null; // marcador que avanza con el slider
let _recTimer = null;      // reproductor automático (setInterval)
let _recTrips = [];        // despachos del día que solapan el recorrido (para diferenciar viajes)
let _recTripsLoaded = false; // ¿ya se consultaron los despachos? (si no, no afirmar "sin despacho")
let _recRange = null;      // {from,to}: límites del reproductor cuando se elige un viaje; null = todo
let _recLatLng = [];       // [[lat,lon],…] del recorrido, para resaltar el tramo de un viaje
let _recTripHi = null;     // capa Leaflet del viaje resaltado en verde
let _recParadas = [];      // paradas largas detectadas {ini,fin,durMin,lat,lon,dir,...}
let _recParadaMarks = [];  // marcadores 🅿️ en el mapa (paralelo a _recParadas)
let _recTab = 'ev';        // pestaña activa de la lista: 'ev' eventos | 'st' paradas
function _hmToMin(hhmm) { const [h, m] = String(hhmm || '').split(':').map(Number); return (h || 0) * 60 + (m || 0); }
// "18 min" / "1 h 5 min" a partir de minutos (para las paradas largas)
function _durParada(min) { const h = Math.floor(min / 60), m = min % 60; return h ? `${h} h${m ? ' ' + m + ' min' : ''}` : `${m} min`; }
// Índice del viaje que contiene la hora hh:mm (-1 fuera de todo viaje, -2 si aún no se sabe).
// Ventana [iniMin, finMin): contigua entre vueltas, sin solaparse.
function _tripOf(hhmm) {
  if (!_recTripsLoaded) return -2;
  const t = _hmToMin(hhmm);
  for (let i = 0; i < _recTrips.length; i++) { const v = _recTrips[i]; if (t >= v.iniMin && t < v.finMin) return i; }
  return -1;
}
function _recQuitarHi() { if (_recTripHi) { try { (recLayer || flotaMap).removeLayer(_recTripHi); } catch (e) {} _recTripHi = null; } }
// Encuadre del recorrido. En PC el panel va ACOPLADO al lado (no tapa el mapa) → solo se reserva
// el aviso de ruta (arriba). En celular la hoja inferior tapa abajo → se reserva ese espacio.
function _recFitOpts() {
  return window.innerWidth > 760
    ? { paddingTopLeft: [40, 74], paddingBottomRight: [40, 48] }
    : { paddingTopLeft: [28, 64], paddingBottomRight: [28, 180] };
}
// Acopla/desacopla el panel del recorrido: el mapa se encoge para que quepan mapa + lista sin
// taparse, y se re-encaja el trazo al nuevo tamaño (invalidateSize para que Leaflet re-renderice).
function _recDock(on) {
  const mv = $('map-view'); if (mv) mv.classList.toggle('rec-active', !!on);
  if (!flotaMap) return;
  setTimeout(() => {
    try {
      flotaMap.invalidateSize();
      if (on && _recLatLng.length) {
        const seg = _recRange ? _recLatLng.slice(_recRange.from, _recRange.to + 1) : _recLatLng;
        flotaMap.fitBounds(seg.length ? seg : _recLatLng, _recFitOpts());
      }
    } catch (e) {}
  }, 60);
}
// Detiene el reproductor y restablece el botón ▶️
function recStop() {
  if (_recTimer) { clearInterval(_recTimer); _recTimer = null; }
  const b = $('rec-play'); if (b) { b.textContent = '▶️'; b.classList.remove('playing'); b.title = 'Reproducir recorrido'; }
}
// Reproduce el recorrido de corrido (o lo pausa si ya está corriendo)
function recPlay() {
  const sl = $('rec-slider'); if (!sl || !_recPts.length) return;
  if (_recTimer) { recStop(); return; }
  const b = $('rec-play'); if (b) { b.textContent = '⏸'; b.classList.add('playing'); b.title = 'Pausar'; }
  const lo = _recRange ? _recRange.from : 0;
  const hi = _recRange ? _recRange.to : _recPts.length - 1;
  let i = +sl.value; if (i >= hi || i < lo) i = lo; // si está al final, reinicia
  recGoto(i);
  const ms = +($('rec-speed')?.value || 600);
  _recTimer = setInterval(() => { i++; if (i > hi) { recStop(); return; } recGoto(i); }, ms);
}
// Avanza/retrocede d puntos (respeta el viaje elegido) y pausa la reproducción
function recStepBy(d) {
  recStop();
  const sl = $('rec-slider'); if (!sl) return;
  const lo = _recRange ? _recRange.from : 0, hi = _recRange ? _recRange.to : _recPts.length - 1;
  recGoto(Math.max(lo, Math.min(hi, (+sl.value) + d)));
}
function recSpeedChange() { if (_recTimer) { recStop(); recPlay(); } } // aplica la nueva velocidad al vuelo
// Elige un viaje del selector: acota el reproductor a su tramo, lo resalta en verde y hace zoom
function recViajeElegido(ix) {
  recStop(); _recQuitarHi();
  if (ix < 0 || !_recTrips[ix] || _recTrips[ix].i0 < 0) {
    _recRange = null;
    if (flotaMap && _recLatLng.length) flotaMap.fitBounds(_recLatLng, _recFitOpts());
    recGoto(0); return;
  }
  const t = _recTrips[ix];
  _recRange = { from: t.i0, to: t.i1 };
  const seg = _recLatLng.slice(t.i0, t.i1 + 1);
  if (flotaMap && seg.length) {
    // halo violeta suave (no satura como el verde): banda ancha translúcida + núcleo fino
    _recTripHi = L.layerGroup([
      L.polyline(seg, { color: '#7c3aed', weight: 11, opacity: 0.22, lineCap: 'round', lineJoin: 'round' }),
      L.polyline(seg, { color: '#7c3aed', weight: 3, opacity: 0.9 }),
    ]).addTo(recLayer || flotaMap);
    flotaMap.fitBounds(seg, _recFitOpts());
  }
  recGoto(t.i0);
}
// Cruza los despachos del día con los puntos del recorrido y prepara el selector de viajes
function _recAplicarViajes(trips) {
  _recTrips = (trips || []).slice();
  for (const t of _recTrips) {
    let i0 = -1, i1 = -1;
    for (let k = 0; k < _recPts.length; k++) { const m = _hmToMin(_recPts[k].t); if (m >= t.iniMin && m < t.finMin) { if (i0 < 0) i0 = k; i1 = k; } }
    t.i0 = i0; t.i1 = i1;
    if (i0 >= 0) {
      t.ini = _recPts[i0].t;                       // etiqueta: primer evento real del viaje
      let f = i1; while (f > i0 && (_recPts[f].vel ?? 0) === 0) f--; // recorta el ralentí final (terminal)
      t.fin = _recPts[f].t;                         // etiqueta: último evento EN MOVIMIENTO del viaje
    }
  }
  _recTripsLoaded = true;
  const validos = _recTrips.filter((t) => t.i0 >= 0 && t.i1 >= t.i0);
  const sel = $('rec-trip');
  if (sel) {
    if (validos.length) {
      sel.innerHTML = `<option value="-1">🚍 Todo el día · ${validos.length} viaje${validos.length > 1 ? 's' : ''} despachado${validos.length > 1 ? 's' : ''}</option>`
        + validos.map((t) => `<option value="${_recTrips.indexOf(t)}">🚍 ${esc(_hora12(t.ini))}–${esc(_hora12(t.fin))}${t.ruta ? ' · ' + esc(t.ruta) : ''}</option>`).join('');
      sel.hidden = false; sel.onchange = () => recViajeElegido(+sel.value);
    } else { sel.innerHTML = ''; sel.hidden = true; }
  }
  // barra verde en las filas de la lista que caen dentro de un viaje
  const list = $('rec-panel-list');
  if (list) list.querySelectorAll('.rec-pt').forEach((el) => { const p = _recPts[+el.dataset.i]; el.classList.toggle('rec-in-trip', !!(p && _tripOf(p.t) >= 0)); });
  const sub = $('rec-panel-sub');
  if (sub) sub.innerHTML += validos.length ? ` · 🚍 <b>${validos.length}</b> viaje${validos.length > 1 ? 's' : ''} despachado${validos.length > 1 ? 's' : ''}` : ' · sin despacho ese día';
  const lg = $('rec-legend');
  if (lg && !lg.hidden && validos.length && !lg.querySelector('.rl-trip'))
    lg.insertAdjacentHTML('beforeend', '<div class="rl-row rl-trip"><span class="rl-line" style="border-top-color:#7c3aed;border-top-width:4px"></span> Tramo del viaje elegido</div>');
  const sl = $('rec-slider'); if (sl) recGoto(+sl.value); // refresca la etiqueta del punto actual
}
function limpiarRecorrido() {
  recStop(); _recQuitarHi();
  if (recLayer && flotaMap) { flotaMap.removeLayer(recLayer); recLayer = null; }
  // restaura los demás vehículos al quitar el recorrido
  if (flotaLayer && flotaMap && !flotaMap.hasLayer(flotaLayer)) flotaLayer.addTo(flotaMap);
  _recPts = []; _recCursor = null; _recLatLng = [];
  _recTrips = []; _recTripsLoaded = false; _recRange = null;
  _recParadas = []; _recParadaMarks = []; _recTab = 'ev';
  const st = $('rec-trip'); if (st) { st.hidden = true; st.innerHTML = ''; }
  const rc = $('rec-ruta-chip'); if (rc) rc.hidden = true;
  const b = $('rec-clear'); if (b) b.hidden = true;
  const pn = $('rec-panel'); if (pn) pn.hidden = true;
  const lg = $('rec-legend'); if (lg) lg.hidden = true;
  _recDock(false); // el mapa recupera todo el ancho
}
function dibujarRecorrido(pts, movil, rutaName) {
  if (!flotaMap) return;
  limpiarRecorrido();
  // oculta la flota para ver mejor el recorrido (se restaura al quitarlo)
  if (flotaLayer && flotaMap.hasLayer(flotaLayer)) flotaMap.removeLayer(flotaLayer);
  _recPts = pts;
  recLayer = L.layerGroup().addTo(flotaMap);
  // Superpone la ruta AUTORIZADA del KMZ (azul punteado) para comparar contra lo real.
  overlayRutaKmzEnRecorrido(rutaName);
  const latlngs = pts.map((p) => [p.lat, p.lon]);
  _recLatLng = latlngs; // para resaltar el tramo de un viaje elegido
  L.polyline(latlngs, { color: '#ED1C24', weight: 4, opacity: 0.85 }).addTo(recLayer);
  // puntos pequeños del trayecto (inicio verde, fin azul); sin popups (el detalle va en el panel)
  pts.forEach((p, i) => {
    const ini = i === 0, fin = i === pts.length - 1, ext = ini || fin;
    const col = ini ? '#137a2b' : (fin ? '#0b5cad' : '#ED1C24');
    L.circleMarker([p.lat, p.lon], { radius: ext ? 6 : 3, color: col, fillColor: col, fillOpacity: 0.9, weight: ext ? 2 : 1, interactive: false }).addTo(recLayer);
  });
  // cursor móvil (lo controla el slider / la lista)
  _recCursor = L.circleMarker([pts[0].lat, pts[0].lon], { radius: 9, color: '#fff', weight: 3, fillColor: '#ED1C24', fillOpacity: 1 }).addTo(recLayer);
  flotaMap.fitBounds(latlngs, _recFitOpts());
  const b = $('rec-clear'); if (b) b.hidden = false;
  renderRecPanel(pts, movil);
}
// Nombre de ruta ("133", "134 CENTRO", "133-133D") -> codigos con recorrido KMZ.
function _codigosDeRuta(label, recMap) {
  const out = [];
  for (const t of String(label || '').split(/[^0-9a-zA-Z]+/).map(normRuta).filter(Boolean)) {
    if (recMap.has(t) && !out.includes(t)) out.push(t);
  }
  return out;
}
// Dibuja la ruta AUTORIZADA (KMZ) del carro sobre su recorrido real, para comparar.
async function overlayRutaKmzEnRecorrido(rutaName) {
  if (!recLayer || !flotaMap) return;
  const recMap = await loadRecorridos();
  if (!recLayer) return; // por si limpiaron el recorrido mientras cargaba
  for (const c of _codigosDeRuta(rutaName, recMap)) {
    const rec = recMap.get(c);
    if (rec && Array.isArray(rec.puntos) && rec.puntos.length) {
      L.polyline(rec.puntos, { color: '#2563eb', weight: 3, opacity: 0.7, dashArray: '6,6' })
        .bindTooltip('Ruta autorizada ' + (rec.codigo || c), { sticky: true }).addTo(recLayer);
    }
  }
}
// Mueve el cursor al punto i: marcador + mapa + info + slider + lista (todo sincronizado)
function recGoto(i) {
  const p = _recPts[i]; if (!p || !flotaMap) return;
  const ll = [p.lat, p.lon];
  if (_recCursor) _recCursor.setLatLng(ll);
  // No recentra en cada paso (eso "sacaba de contexto"): solo desplaza si el punto se acerca al borde.
  try { if (!flotaMap.getBounds().pad(-0.18).contains(ll)) flotaMap.panTo(ll, { animate: false }); } catch (e) {}
  const det = (p.vel ?? 0) === 0 ? 'detenido' : `${p.vel} km/h`;
  const ti = _tripOf(p.t);
  let trip = '';
  if (ti >= 0) { const v = _recTrips[ti]; trip = `<span class="rec-trip-now on">🚍 En viaje despachado${v.ruta ? ' · ' + esc(v.ruta) : ''} · ${esc(_hora12(v.ini))}–${esc(_hora12(v.fin))}</span>`; }
  else if (ti === -1) { trip = `<span class="rec-trip-now off">⚪ Sin despacho a esta hora</span>`; }
  // Aviso flotante no invasivo: qué ruta va haciendo en este punto (solo dentro de un viaje).
  const chip = $('rec-ruta-chip');
  if (chip) {
    if (ti >= 0) { const v = _recTrips[ti]; chip.innerHTML = `🚍 Ruta ${esc(v.ruta || '—')}<span class="rc-sub">viaje ${esc(_hora12(v.ini))}–${esc(_hora12(v.fin))}</span>`; chip.hidden = false; }
    else chip.hidden = true;
  }
  const info = $('rec-scrub-info'); if (info) info.innerHTML = `${trip}<div class="rec-scrub-line"><b>${esc(_hora12(p.t))}</b> · ${esc(det)} · ${esc(p.dir || '')}</div>`;
  const sl = $('rec-slider'); if (sl && +sl.value !== i) sl.value = i;
  const list = $('rec-panel-list');
  list.querySelectorAll('.rec-pt.sel').forEach((x) => x.classList.remove('sel'));
  const it = list.querySelector(`.rec-pt[data-i="${i}"]`);
  if (it) { it.classList.add('sel'); it.scrollIntoView({ block: 'nearest' }); }
}
function renderRecPanel(pts, movil) {
  const pn = $('rec-panel'); if (!pn) return;
  // recorrido nuevo: reinicia reproductor y datos de viajes (se recargan aparte si aplica)
  recStop(); _recQuitarHi();
  _recTrips = []; _recTripsLoaded = false; _recRange = null;
  const st = $('rec-trip'); if (st) { st.hidden = true; st.innerHTML = ''; }
  const rc = $('rec-ruta-chip'); if (rc) rc.hidden = true;
  $('rec-panel-title').textContent = `🛣️ ${movil || ''}`;
  $('rec-panel-sub').textContent = `${pts.length} puntos · ${_hora12(pts[0].t)}–${_hora12(pts[pts.length - 1].t)}`;
  // Paradas largas: detección + marcadores 🅿️ en el mapa + rótulo de la pestaña
  _recParadas = _detectarParadas(pts);
  pintarParadasEnMapa();
  const tb = $('rec-tab-st');
  if (tb) { tb.textContent = `🅿️ Paradas largas${_recParadas.length ? ' · ' + _recParadas.length : ''}`; tb.disabled = _recParadas.length === 0; }
  _recTab = 'ev';
  $('rec-tab-ev')?.classList.add('on'); $('rec-tab-st')?.classList.remove('on');
  renderRecLista();
  const sl = $('rec-slider'); if (sl) { sl.min = 0; sl.max = pts.length - 1; sl.value = 0; sl.oninput = () => { recStop(); recGoto(+sl.value); }; }
  // En celular arranca con la lista oculta (mapa visible); en PC, con la lista abierta
  pn.classList.toggle('list-open', window.innerWidth > 760);
  pn.hidden = false;
  _recDock(true); // acopla el panel: el mapa se encoge para verse completo al lado
  recGoto(0);
}
// Renderiza la lista según la pestaña activa: eventos (recorrido) o paradas largas.
function renderRecLista() {
  const list = $('rec-panel-list'); if (!list) return;
  if (_recTab === 'st') {
    if (!_recParadas.length) { list.innerHTML = '<div class="rec-stop-empty">No hubo paradas largas (≥ 5 min) en este recorrido.</div>'; return; }
    list.innerHTML = _recParadas.map((s, k) => `<button type="button" class="rec-stop" data-k="${k}">
      <span class="rec-stop-ic">🅿️</span>
      <span class="rec-stop-t">${esc(_hora12(s.ini))}–${esc(_hora12(s.fin))}</span>
      <span class="rec-stop-dur">${esc(_durParada(s.durMin))}</span>
      <span class="rec-stop-d">${esc(s.dir || '—')}</span>
    </button>`).join('');
    list.querySelectorAll('.rec-stop').forEach((b) => b.addEventListener('click', () => recGotoParada(+b.dataset.k)));
  } else {
    list.innerHTML = _recPts.map((p, i) => {
      const tag = i === 0 ? '🟢' : (i === _recPts.length - 1 ? '🔵' : '•');
      const det = (p.vel ?? 0) === 0 ? '<span class="rec-pt-stop">detenido</span>' : `${p.vel} km/h`;
      return `<button type="button" class="rec-pt" data-i="${i}">
        <span class="rec-pt-t">${tag} ${esc(_hora12(p.t))}</span>
        <span class="rec-pt-v">${det}</span>
        <span class="rec-pt-d">${esc(p.dir || '—')}</span>
      </button>`;
    }).join('');
    list.querySelectorAll('.rec-pt').forEach((b) => b.addEventListener('click', () => recGoto(+b.dataset.i)));
  }
}
// Dibuja un marcador 🅿️ (con los minutos) por cada parada larga, para localizarla en el mapa.
function pintarParadasEnMapa() {
  _recParadaMarks = [];
  if (!recLayer || !flotaMap) return;
  for (const s of _recParadas) {
    const big = s.durMin >= 15;
    const lbl = s.durMin < 60 ? `${s.durMin}m` : `${Math.floor(s.durMin / 60)}h${String(s.durMin % 60).padStart(2, '0')}`;
    const m = L.marker([s.lat, s.lon], {
      icon: L.divIcon({ className: '', iconSize: [0, 0], html: `<div class="stop-mark${big ? ' big' : ''}">🅿️ ${lbl}</div>` }),
      zIndexOffset: 500,
    }).bindPopup(`🅿️ <b>Parada ${esc(_durParada(s.durMin))}</b><br>${esc(_hora12(s.ini))}–${esc(_hora12(s.fin))}${s.dir ? '<br>' + esc(s.dir) : ''}`).addTo(recLayer);
    _recParadaMarks.push(m);
  }
}
// Localiza una parada en el mapa: centra, abre su globo y la marca en la lista.
function recGotoParada(k) {
  const s = _recParadas[k]; if (!s || !flotaMap) return;
  flotaMap.setView([s.lat, s.lon], Math.max(flotaMap.getZoom(), 16), { animate: true });
  const m = _recParadaMarks[k]; if (m) m.openPopup();
  const list = $('rec-panel-list');
  list.querySelectorAll('.rec-stop.sel').forEach((x) => x.classList.remove('sel'));
  const it = list.querySelector(`.rec-stop[data-k="${k}"]`);
  if (it) it.classList.add('sel');
}
// Cambia de pestaña (eventos / paradas) y re-renderiza la lista.
function setRecTab(t) {
  if (t === 'st' && !_recParadas.length) return;
  _recTab = t;
  $('rec-tab-ev')?.classList.toggle('on', t === 'ev');
  $('rec-tab-st')?.classList.toggle('on', t === 'st');
  renderRecLista();
  if (t === 'ev') { const sl = $('rec-slider'); if (sl) recGoto(+sl.value); } // re-marca el punto actual
}
$('rec-tab-ev') && $('rec-tab-ev').addEventListener('click', () => setRecTab('ev'));
$('rec-tab-st') && $('rec-tab-st').addEventListener('click', () => setRecTab('st'));
$('rec-panel-toggle') && $('rec-panel-toggle').addEventListener('click', () => { const p = $('rec-panel'); if (p) p.classList.toggle('list-open'); });
$('rec-panel-x') && $('rec-panel-x').addEventListener('click', () => limpiarRecorrido()); // ✕ = cerrar el rastreo (el botón "Quitar recorrido" queda tapado por el panel)
// Controles del reproductor del recorrido (⏮ ◀ ▶️ ▶ + velocidad)
$('rec-play') && $('rec-play').addEventListener('click', recPlay);
$('rec-next') && $('rec-next').addEventListener('click', () => recStepBy(1));
$('rec-prev') && $('rec-prev').addEventListener('click', () => recStepBy(-1));
$('rec-first') && $('rec-first').addEventListener('click', () => { recStop(); recGoto(_recRange ? _recRange.from : 0); });
$('rec-speed') && $('rec-speed').addEventListener('change', recSpeedChange);
// Teclado: ← → avanzan punto a punto, barra espaciadora reproduce/pausa (solo con el panel abierto)
document.addEventListener('keydown', (e) => {
  const pn = $('rec-panel'); if (!pn || pn.hidden) return;
  const tag = (e.target && e.target.tagName || '').toLowerCase();
  if (tag === 'input' || tag === 'select' || tag === 'textarea' || tag === 'button') return;
  if (e.key === 'ArrowRight') { e.preventDefault(); recStepBy(1); }
  else if (e.key === 'ArrowLeft') { e.preventDefault(); recStepBy(-1); }
  else if (e.key === ' ') { e.preventDefault(); recPlay(); }
});
$('rec-x') && $('rec-x').addEventListener('click', () => { $('rec-modal').hidden = true; });
$('rec-cancel') && $('rec-cancel').addEventListener('click', () => { $('rec-modal').hidden = true; });
$('rec-ver') && $('rec-ver').addEventListener('click', verRecorrido);
$('rec-clear') && $('rec-clear').addEventListener('click', limpiarRecorrido);

async function openVehSheet(r) {
  const sheet = $('veh-sheet'), body = $('veh-sheet-body');
  body.innerHTML = mapPopup(r);
  // Acciones del móvil: recorrido (todos) + despachar/consultar SONAR (solo admin)
  const acts = document.createElement('div');
  acts.className = 'veh-sheet-acts';
  const bRec = Object.assign(document.createElement('button'), { className: 'btn', textContent: '🛣️ Recorrido' });
  bRec.onclick = () => abrirRecorrido(r);
  acts.appendChild(bRec);
  // Seguir / dejar de seguir este móvil (para vigilar varios a la vez)
  const bSeg = Object.assign(document.createElement('button'), { className: 'btn' });
  const pintarSeg = () => {
    const on = seguidos.has(_mk(r.movil));
    bSeg.textContent = on ? '✓ Siguiendo' : '🎯 Seguir';
    bSeg.classList.toggle('btn-primary', on);
  };
  pintarSeg();
  bSeg.onclick = () => { toggleSeguir(r.movil); pintarSeg(); };
  acts.appendChild(bSeg);
  if (isAdmin()) {
    const bDsp = Object.assign(document.createElement('button'), { className: 'btn btn-primary', textContent: '🛰️ Despachar' });
    bDsp.onclick = () => despacharDesdeMapa(r.movil);
    const bCon = Object.assign(document.createElement('button'), { className: 'btn', textContent: '📡 Consultar SONAR' });
    bCon.onclick = () => consultarDesdeMapa(r.movil);
    acts.append(bDsp, bCon);
  }
  body.appendChild(acts);
  sheet.hidden = false;
  requestAnimationFrame(() => sheet.classList.add('open'));
  // Ruta actual en SONAR (1 llamada)
  const cur = body.querySelector('#cur-ruta');
  if (cur) {
    cur.textContent = '⏳…';
    const { data, error } = await sb.rpc('ruta_actual_sonar', { p_mid: r.mid });
    const c2 = body.querySelector('#cur-ruta');
    if (c2) c2.textContent = (error || !data || !data.ok) ? (r.ruta ? `${r.ruta} (despacho)` : '—') : (data.ruta || '—');
  }
}
function closeVehSheet() {
  const sheet = $('veh-sheet');
  if (!sheet || sheet.hidden) return;
  sheet.style.transform = '';
  sheet.classList.remove('open');
  setTimeout(() => { sheet.hidden = true; }, 250);
}
// Despachar el móvil del panel: abre el modal SONAR con ese móvil preseleccionado
async function despacharDesdeMapa(movil) {
  closeVehSheet();
  if (!(await openSonar(null))) return; // otra apertura en curso: no pisar sus campos
  const veh = await loadVehiculos();
  const vr = veh.find((v) => String(v.numero) === String(movil));
  if (vr) { $('s-mov').value = String(vr.id); $('s-mov')._comboSync && $('s-mov')._comboSync(); await updateSonarInfo(); }
}
// Consultar en SONAR el móvil del panel
async function consultarDesdeMapa(movil) {
  closeVehSheet();
  await openDsonar(movil);   // abre con ese móvil ya marcado
  $('ds-run').click();       // y consulta de una vez
}
$('veh-sheet-close')?.addEventListener('click', closeVehSheet);

// Deslizar hacia abajo (en la barra superior del panel) para cerrar
(() => {
  const sheet = $('veh-sheet'), head = $('veh-sheet-head');
  if (!sheet || !head) return;
  let y0 = null, drag = false;
  head.addEventListener('touchstart', (e) => { y0 = e.touches[0].clientY; drag = true; sheet.style.transition = 'none'; }, { passive: true });
  head.addEventListener('touchmove', (e) => { if (!drag) return; const dy = e.touches[0].clientY - y0; if (dy > 0) sheet.style.transform = `translateY(${dy}px)`; }, { passive: true });
  head.addEventListener('touchend', (e) => {
    if (!drag) return; drag = false; sheet.style.transition = '';
    const dy = e.changedTouches[0].clientY - y0;
    sheet.style.transform = '';
    if (dy > 90) closeVehSheet();
  });
  // En escritorio: clic en la barra (no en la ✕) también cierra
  head.addEventListener('click', (e) => { if (e.target.id !== 'veh-sheet-close') closeVehSheet(); });
})();

let lastUbic = [], mapFilter = 'todos', routeFilter = '', vehSearch = [];
// Filtro por PUESTO(s) del mapa (solo admin): puestoSel = nombres elegidos; puestoFilterSet =
// conjunto normalizado de rutas+grupos de esos puestos (con qué se compara ubicaciones.ruta).
let puestoSel = new Set(), puestoFilterSet = null, _puestosCache = null, _puestosChecklistBuilt = false;
async function loadPuestos() {
  if (_puestosCache) return _puestosCache;
  const { data } = await sb.from('puestos').select('nombre,rutas').eq('activo', true).order('nombre');
  _puestosCache = data || [];
  return _puestosCache;
}
// Traduce los puestos elegidos a su conjunto de rutas + grupos (vía ruta_grupos), normalizado,
// para comparar contra ubicaciones.ruta (que a veces trae el número de ruta y a veces el grupo).
async function computePuestoFilterSet() {
  if (!puestoSel.size) { puestoFilterSet = null; return; }
  const [puestos, gmap] = await Promise.all([loadPuestos(), loadRutaGrupos()]);
  const set = new Set();
  for (const p of puestos) {
    if (!puestoSel.has(p.nombre)) continue;
    for (const rn of String(p.rutas || '').split(',').map((s) => s.trim()).filter(Boolean)) {
      set.add(normRuta(rn));
      const g = _grupoDeRuta(gmap, rn); if (g) set.add(normRuta(g));
    }
  }
  puestoFilterSet = set;
}
function updatePuestosBtn() {
  const btn = $('map-puestos-btn'); if (!btn) return;
  const n = puestoSel.size;
  btn.textContent = n ? `🏢 Puestos (${n})` : '🏢 Puestos';
  btn.classList.toggle('btn-primary', n > 0);
  const c = $('mp-count'); if (c) c.textContent = n ? `${n} puesto(s) seleccionados` : 'Ninguno seleccionado';
}
async function buildPuestosChecklist() {
  const box = $('mp-items'); if (!box) return;
  const puestos = await loadPuestos();
  box.innerHTML = puestos.map((p) => {
    const rutas = String(p.rutas || '').trim();
    return `<label class="mp-item"><input type="checkbox" value="${esc(p.nombre)}"${puestoSel.has(p.nombre) ? ' checked' : ''}>`
      + `<span class="mp-nom">${esc(p.nombre)}</span>`
      + (rutas ? `<span class="mp-rutas">${esc(rutas)}</span>` : `<span class="mp-rutas mp-sin">sin rutas</span>`)
      + `</label>`;
  }).join('');
  _puestosChecklistBuilt = true;
}
// Muestra el filtro de puestos SOLO al admin; lo oculta y limpia para el resto.
function syncPuestosFiltro() {
  const wrap = $('map-puestos-wrap'); if (!wrap) return;
  const show = efIsAdmin();
  wrap.hidden = !show;
  if (!show) { puestoSel.clear(); puestoFilterSet = null; const pnl = $('map-puestos-panel'); if (pnl) pnl.hidden = true; }
  else if (!_puestosChecklistBuilt) buildPuestosChecklist();
  updatePuestosBtn();
}
// Marcadores reutilizables: movil -> { marker, pos, icon }. Evita reconstruir toda la
// flota en cada refresco/filtro; solo mueve los que cambiaron de sitio y reconstruye el
// ícono si cambió su estado. Así el mapa va fluido aunque haya cientos de móviles.
let markerMap = new Map();
// Seguimiento: móviles seleccionados para vigilar. soloSeguidos = mostrar únicamente esos.
let seguidos = new Set(), soloSeguidos = false;
const _mk = (m) => String(m ?? '').trim();
const _movKey = (r) => _mk(r.movil) || (r.mid != null ? '#' + r.mid : '@' + r.latitude + ',' + r.longitude);
function toggleSeguir(movil) {
  const k = _mk(movil); if (!k) return;
  if (seguidos.has(k)) seguidos.delete(k); else seguidos.add(k);
  if (!seguidos.size) soloSeguidos = false;
  renderSeguidosBar(); renderMarkers(false);
}
function quitarSeguido(movil) {
  seguidos.delete(_mk(movil)); if (!seguidos.size) soloSeguidos = false;
  renderSeguidosBar(); renderMarkers(false);
}
function limpiarSeguidos() { seguidos.clear(); soloSeguidos = false; renderSeguidosBar(); renderMarkers(false); }
// Barra de seguidos: aparece solo cuando hay móviles seleccionados.
function renderSeguidosBar() {
  syncListaSel();
  const bar = $('map-seguidos'); if (!bar) return;
  if (!seguidos.size) { bar.hidden = true; bar.innerHTML = ''; return; }
  bar.hidden = false;
  const chips = [...seguidos].sort((a, b) => a.localeCompare(b, 'es', { numeric: true }))
    .map((m) => `<span class="seg-chip" data-m="${esc(m)}" title="Quitar">${esc(m)} <b>✕</b></span>`).join('');
  bar.innerHTML = `<span class="seg-lbl">🎯 Siguiendo (${seguidos.size}):</span>${chips}`
    + `<button class="btn seg-btn ${soloSeguidos ? 'btn-primary' : ''}" id="seg-ver">${soloSeguidos ? '🎯 Siguiendo en vivo' : '👁️ Ver en pantalla'}</button>`
    + `<button class="btn seg-btn" id="seg-clear">Limpiar</button>`;
  bar.querySelectorAll('.seg-chip').forEach((c) => c.addEventListener('click', () => quitarSeguido(c.dataset.m)));
  // "Ver en pantalla": alterna mostrar solo los seguidos y los encuadra en el mapa
  $('seg-ver').addEventListener('click', () => { soloSeguidos = !soloSeguidos; renderSeguidosBar(); renderMarkers(true); });
  $('seg-clear').addEventListener('click', limpiarSeguidos);
}
// Refleja en la lista qué móviles están seleccionados (sin reconstruirla).
function syncListaSel() {
  const box = $('ml-items'); if (!box) return;
  box.querySelectorAll('.ml-item').forEach((el) => {
    const on = seguidos.has(_mk(el.dataset.m));
    el.classList.toggle('sel', on);
    const chk = el.querySelector('.ml-check'); if (chk) chk.textContent = on ? '✓' : '';
  });
  const c = $('ml-count');
  if (c) c.textContent = seguidos.size ? `🎯 ${seguidos.size} seleccionado(s)` : 'Toca un móvil para seguirlo';
}
function fillRutaSelect() {
  const sel = $('map-ruta'); if (!sel) return;
  const prev = sel.value;
  const rutas = [...new Set(lastUbic.map((r) => r.ruta).filter(Boolean))]
    .sort((a, b) => a.localeCompare(b, 'es', { numeric: true }));
  sel.innerHTML = `<option value="">Todas las rutas (${rutas.length})</option>`
    + rutas.map((rt) => `<option value="${esc(rt)}">${esc(rt)}</option>`).join('');
  if (rutas.includes(prev)) sel.value = prev; else routeFilter = '';
}
// ===== Recorridos AUTORIZADOS de las rutas (tabla rutas_recorrido, KMZ oficiales) =====
// Panel propio "🛣️ Rutas": el usuario marca UNA o VARIAS rutas y se dibuja su trazo
// oficial en el mapa (cada una con su color), exista o no un móvil de esa ruta ahora.
// Independiente del filtro de móviles. Distinto del recorrido REAL de SONAR (rojo, recLayer).
let rutaGeoLayer = null;        // capa Leaflet con los trazos dibujados
let _recorridos = null;         // Map normRuta(codigo) -> { codigo, puntos:[[lat,lng],...] }
let _rutasVerSet = new Set();   // codigos (normalizados) elegidos para ver
let _rutasChecklistBuilt = false;
const _recColorDe = new Map();  // normRuta(codigo) -> color (estable por ruta)
const REC_COLORES = ['#e6194B', '#3cb44b', '#4363d8', '#f58231', '#911eb4', '#0891b2',
  '#db2777', '#65a30d', '#9A6324', '#7c3aed', '#0d9488', '#b45309'];
async function loadRecorridos() {
  if (_recorridos) return _recorridos;
  const { data, error } = await sb.from('rutas_recorrido').select('codigo,puntos');
  _recorridos = new Map();
  if (!error) for (const r of (data || [])) _recorridos.set(normRuta(r.codigo), r);
  return _recorridos;
}
// Dibuja los recorridos de las rutas marcadas en _rutasVerSet (limpia y redibuja todo).
function dibujarRecorridosSeleccionados(fit) {
  if (!flotaMap) return;
  if (rutaGeoLayer) { flotaMap.removeLayer(rutaGeoLayer); rutaGeoLayer = null; }
  if (!_rutasVerSet.size || !_recorridos) return;
  rutaGeoLayer = L.layerGroup();
  const todos = [];
  for (const c of _rutasVerSet) {
    const rec = _recorridos.get(c);
    if (!rec || !Array.isArray(rec.puntos) || !rec.puntos.length) continue;
    const col = _recColorDe.get(c) || '#2563eb';
    L.polyline(rec.puntos, { color: col, weight: 4, opacity: 0.85 })
      .bindTooltip('Ruta ' + (rec.codigo || c), { sticky: true }).addTo(rutaGeoLayer);
    todos.push(...rec.puntos);
  }
  rutaGeoLayer.addTo(flotaMap);
  if (fit && todos.length) flotaMap.fitBounds(todos, { padding: [30, 30] });
}
function updateRutasBtn() {
  const btn = $('map-rutas-btn'); if (!btn) return;
  const n = _rutasVerSet.size;
  btn.textContent = n ? `🛣️ Rutas (${n})` : '🛣️ Rutas';
  btn.classList.toggle('btn-primary', n > 0);
  const c = $('mr-count'); if (c) c.textContent = n ? `${n} ruta(s) en el mapa` : 'Ninguna seleccionada';
}
// Arma el checklist con las rutas que tienen recorrido cargado; asigna un color por ruta.
// Es una GUÍA para el despachador: a él le muestra SOLO sus rutas (por nombre o por su
// grupo); el admin y el auditor ven todas.
async function buildRutasChecklist() {
  const box = $('mr-items'); if (!box) return;
  const recMap = await loadRecorridos();
  let codigos = [...recMap.values()].map((r) => r.codigo)
    .sort((a, b) => a.localeCompare(b, 'es', { numeric: true }));
  if (!(efIsAdmin() || efIsAuditor())) {
    const gmap = await loadRutaGrupos();
    const allowR = allowedRutaSet();
    const allowG = new Set([...(allowedGrupoSet() || []), ...gruposDeMisRutas(gmap)].map(normRuta));
    codigos = codigos.filter((cod) => {
      if (allowR.has(normRuta(cod))) return true;           // coincide por nombre de ruta
      const g = _grupoDeRuta(gmap, cod);                    // o por el grupo al que pertenece
      return !!(g && allowG.has(normRuta(g)));
    });
  }
  _recColorDe.clear();
  codigos.forEach((cod, i) => _recColorDe.set(normRuta(cod), REC_COLORES[i % REC_COLORES.length]));
  box.innerHTML = codigos.length ? codigos.map((cod) => {
    const k = normRuta(cod);
    return `<label class="mp-item"><input type="checkbox" value="${esc(cod)}"${_rutasVerSet.has(k) ? ' checked' : ''}>`
      + `<span class="rec-sw" style="background:${_recColorDe.get(k)}"></span>`
      + `<span class="mp-nom">Ruta ${esc(cod)}</span></label>`;
  }).join('') : '<div class="mp-item" style="justify-content:center;color:var(--muted)">No hay recorrido para tus rutas.</div>';
  _rutasChecklistBuilt = true;
}
// Inicializa el panel de rutas al abrir el mapa (una sola vez).
async function syncRutasPanel() {
  if (!_rutasChecklistBuilt) await buildRutasChecklist();
  updateRutasBtn();
}
function _buildBusIcon(r, cls, seg) {
  const ruta = r.ruta ? ` <small>${esc(r.ruta)}</small>` : '';
  return L.divIcon({
    className: 'bus-marker',
    html: `<div class="bus-pin ${cls}${seg ? ' seg' : ''}"><span>🚌</span>${esc(r.movil || '—')}${ruta}</div>`,
    iconSize: null, iconAnchor: [26, 24], popupAnchor: [0, -22],
  });
}
// Dibuja/actualiza la flota REUTILIZANDO marcadores: mueve el que cambió de sitio y
// rehace el ícono solo si cambió su estado. Nada de borrar y recrear todo en cada refresco.
function renderMarkers(fit) {
  if (!flotaLayer) return;
  const pts = [], vivos = new Set();
  for (const r of lastUbic) {
    if (r.latitude == null || r.longitude == null) continue;
    const cls = clasificar(r);
    if (mapFilter !== 'todos' && cls !== mapFilter) continue;
    if (routeFilter && (r.ruta || '') !== routeFilter) continue;
    if (vehSearch.length) {
      const m = String(r.movil || '').toLowerCase(), p = String(r.placa || '').toLowerCase();
      if (!vehSearch.some((q) => m.includes(q) || p.includes(q))) continue;
    }
    const seg = seguidos.has(_mk(r.movil));
    if (soloSeguidos && !seg) continue; // modo "ver seguidos": oculta los demás
    const key = _movKey(r);
    vivos.add(key);
    const posSig = r.latitude + ',' + r.longitude;
    const iconSig = cls + '|' + (seg ? 1 : 0) + '|' + (r.movil || '') + '|' + (r.ruta || '');
    const ex = markerMap.get(key);
    if (ex) {
      if (ex.pos !== posSig) { ex.marker.setLatLng([r.latitude, r.longitude]); ex.pos = posSig; }
      if (ex.icon !== iconSig) { ex.marker.setIcon(_buildBusIcon(r, cls, seg)); ex.icon = iconSig; }
      ex.marker._row = r;
    } else {
      const m = L.marker([r.latitude, r.longitude], { icon: _buildBusIcon(r, cls, seg), title: `Móvil ${r.movil || ''}` });
      m._row = r;
      // Un clic hace ZOOM al carro y abre su panel (usa la fila viva del marcador)
      m.on('click', () => { zoomAlMovil(m._row); openVehSheet(m._row); });
      flotaLayer.addLayer(m);
      markerMap.set(key, { marker: m, pos: posSig, icon: iconSig });
    }
    pts.push([r.latitude, r.longitude]);
  }
  // Quita los marcadores que ya no aplican (fuera del filtro o desaparecidos)
  for (const [key, ent] of markerMap) {
    if (!vivos.has(key)) { flotaLayer.removeLayer(ent.marker); markerMap.delete(key); }
  }
  const filtrando = mapFilter !== 'todos' || routeFilter || soloSeguidos || vehSearch.length;
  $('map-count').textContent = filtrando ? `${pts.length} de ${lastUbic.length}` : `${pts.length} móviles`;
  if (fit && pts.length) encuadrar(pts);
}
// Encuadra el mapa a unos puntos. Con un solo carro recentra SIN cambiarte el zoom
// (para seguirlo de cerca); con varios, ajusta la vista para verlos a todos.
function encuadrar(pts) {
  if (!flotaMap || !pts.length) return;
  if (pts.length === 1) flotaMap.setView(pts[0], Math.max(flotaMap.getZoom(), 15), { animate: true });
  else flotaMap.fitBounds(pts, { padding: [30, 30], maxZoom: 16 });
}
// Acerca el mapa a un móvil (sin alejar si ya estás más cerca).
function zoomAlMovil(r) {
  if (!flotaMap || r.latitude == null || r.longitude == null) return;
  flotaMap.flyTo([r.latitude, r.longitude], Math.max(flotaMap.getZoom(), 16), { duration: 0.6 });
}
async function refreshMapa(fit) {
  const { data, error } = await sb.from('ubicaciones').select('*').not('latitude', 'is', null);
  if (error) { toast('Error al cargar ubicaciones: ' + error.message, 'err'); verificarSesionVigente(); return; }
  // Si a un despachador le llegan 0 ubicaciones, casi siempre es que su sesión fue
  // desplazada (la RLS devuelve vacío). Verificar de una: si está muerta, sale al login
  // con el aviso; si está viva, sigue normal (no hay falso cierre: decide el servidor).
  if (!efIsAdmin() && (data || []).length === 0) { if (!(await verificarSesionVigente())) return; }
  let rows = data || [];
  // Despachador: móviles de sus RUTAS o de sus GRUPOS del parque. En 'ubicaciones'
  // muchos vehículos vienen etiquetados con el nombre del GRUPO (ej. "Laureles"),
  // no con el número de ruta (190, 191…). Sin incluir el grupo, el mapa salía en
  // "0 móviles" para puestos como Laureles. La RLS ya limita; esto ajusta la vista.
  if (!efIsAdmin() && !isAfiliado()) {
    const allowR = allowedRutaSet();
    // En día hábil CTX.grupos (allowedGrupoSet) suele venir vacío; derivamos los grupos de las
    // rutas del despachador (igual que en el despacho, vía ruta_grupos) para no perder los
    // móviles que 'ubicaciones' etiqueta con el nombre del GRUPO (ej. "133-133D", "Laureles")
    // en vez del número de ruta. Sin esto, un puesto como 133-133D solo mostraba el carro
    // etiquetado "133" y no los 6 etiquetados "133-133D".
    const gmap = await loadRutaGrupos();
    const grupos = new Set([...(allowedGrupoSet() || []), ...gruposDeMisRutas(gmap)]);
    const allowG = new Set([...grupos].map(normRuta));
    rows = rows.filter((r) => {
      const nr = normRuta(r.ruta);
      return allowR.has(nr) || allowG.has(nr);
    });
  }
  // Admin: filtro OPCIONAL por puesto(s) elegidos (rutas del puesto + sus grupos). Al aplicarlo,
  // el desplegable de rutas de abajo se reduce solo a las rutas de esos puestos (fillRutaSelect
  // se arma desde lastUbic), cumpliendo el "señalar las rutas del puesto".
  if (efIsAdmin() && puestoFilterSet && puestoFilterSet.size) {
    rows = rows.filter((r) => puestoFilterSet.has(normRuta(r.ruta)));
  }
  lastUbic = rows;
  fillRutaSelect();
  // En modo "Ver seleccionados" el mapa PERSIGUE a los carros vigilados: re-encuadra en
  // cada refresco (aunque sea el automático de 60 s) para no perderles el rastro al moverse.
  renderMarkers(fit || (soloSeguidos && seguidos.size > 0));
}
// Crea el mapa Leaflet una sola vez (lo reusan la vista completa y la ventana flotante)
function ensureFlotaMap() {
  if (flotaMap) return;
  flotaMap = L.map('map').setView([6.244, -75.58], 12); // Medellín
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    maxZoom: 19, attribution: '© OpenStreetMap',
  }).addTo(flotaMap);
  flotaLayer = L.layerGroup().addTo(flotaMap);
  flotaMap.on('click', closeVehSheet); // tocar el mapa cierra el panel
  flotaMap.on('click', onMapClickGeo); // en modo "agregar geocerca", el clic la coloca
  loadGeocercas(); // dibuja origen/destino/controles (piloto Laureles)
}
// (Capa de tráfico de TomTom retirada: el botón 🚦 del mapa se eliminó por pedido.)

// ===== GEOCERCAS + ETA (piloto Laureles) =====
// Usa SOLO el GPS que ya trae SONAR (tabla 'ubicaciones', refresco cada minuto).
// No consume ninguna API de mapas: distancia y tiempo se calculan con la velocidad real del bus.
let geocercasLayer = null, geoList = [], geoAddMode = false, geoPickLatLng = null, etaTimer = null, etaLoading = false;
const GEO_GRUPO = 'Laureles';

function _geoColor(t) { return t === 'origen' ? '#16a34a' : t === 'destino' ? '#dc2626' : '#2563eb'; }
function _geoTipoLbl(t) { return t === 'origen' ? 'Origen' : t === 'destino' ? 'Destino' : 'Control'; }

// Muestra/oculta los botones flotantes según el rol (ver: admin/auditor; editar geocercas: solo admin)
function syncMapFabs() {
  const verEta = efIsAdmin() || efIsAuditor();
  const editarGeo = efIsAdmin();
  const ef = $('eta-fab'), gf = $('geo-fab');
  if (ef) ef.hidden = !verEta;
  if (gf) gf.hidden = !editarGeo;
  if (!verEta && $('eta-panel')) { $('eta-panel').hidden = true; if (etaTimer) { clearInterval(etaTimer); etaTimer = null; } }
  if (!editarGeo && $('geo-panel')) { $('geo-panel').hidden = true; cancelGeoAdd(); }
}

async function loadGeocercas() {
  if (!flotaMap) return;
  if (!geocercasLayer) geocercasLayer = L.layerGroup().addTo(flotaMap);
  const { data, error } = await sb.from('geocercas').select('*').order('id');
  if (error) return; // silencioso: no romper el mapa por esto
  geoList = data || [];
  drawGeocercas();
  if ($('geo-panel') && !$('geo-panel').hidden) renderGeoList();
}

function drawGeocercas() {
  if (!geocercasLayer) return;
  geocercasLayer.clearLayers();
  const editable = efIsAdmin();
  for (const g of geoList) {
    if (!g.activo) continue;
    const col = _geoColor(g.tipo);
    L.circle([g.lat, g.lon], { radius: g.radio_m, color: col, weight: 2, fillColor: col, fillOpacity: 0.12, interactive: false })
      .addTo(geocercasLayer);
    const mk = L.marker([g.lat, g.lon], {
      draggable: editable, title: g.nombre,
      icon: L.divIcon({ className: 'geo-pin', iconSize: [0, 0], html: `<span style="border-color:${col};color:${col}">${esc(g.nombre)}</span>` }),
    }).addTo(geocercasLayer);
    if (editable) {
      mk.on('dragend', async (e) => {
        const ll = e.target.getLatLng();
        const { error } = await sb.from('geocercas').update({ lat: ll.lat, lon: ll.lng }).eq('id', g.id);
        if (error) { toast('No se pudo mover: ' + error.message, 'err'); loadGeocercas(); return; }
        g.lat = ll.lat; g.lon = ll.lng; drawGeocercas(); refreshEtaPanel(); toast('Geocerca movida', 'ok');
      });
    }
  }
}

// ---- Editor de geocercas (admin) ----
function toggleGeoPanel() {
  const p = $('geo-panel'); if (!p) return;
  const show = p.hidden; p.hidden = !show;
  $('geo-fab')?.classList.toggle('on', show);
  if (show) {
    if ($('eta-panel') && !$('eta-panel').hidden) toggleEtaPanel(); // no solapar
    renderGeoList();
  } else { cancelGeoAdd(); }
}
function startGeoAdd() {
  geoAddMode = true; geoPickLatLng = null;
  $('geo-form').hidden = true;
  const m = $('map'); if (m) m.style.cursor = 'crosshair';
  toast('Toca en el mapa el punto de la geocerca', 'ok');
}
function cancelGeoAdd() {
  geoAddMode = false; geoPickLatLng = null;
  const m = $('map'); if (m) m.style.cursor = '';
  if ($('geo-form')) $('geo-form').hidden = true;
}
function onMapClickGeo(e) {
  if (!geoAddMode) return;
  geoPickLatLng = e.latlng;
  $('geo-coords').textContent = `Lat ${e.latlng.lat.toFixed(6)}, Lon ${e.latlng.lng.toFixed(6)}`;
  $('geo-form').hidden = false;
  $('geo-nombre').focus();
}
async function saveGeoNew() {
  if (!geoPickLatLng) { toast('Toca primero el punto en el mapa', 'err'); return; }
  const nombre = ($('geo-nombre').value || '').trim();
  if (!nombre) { toast('Ponle un nombre a la geocerca', 'err'); return; }
  const tipo = $('geo-tipo').value;
  const radio = Math.max(20, Math.min(5000, parseInt($('geo-radio').value, 10) || 200));
  const { error } = await sb.from('geocercas').insert({
    nombre, tipo, grupo: GEO_GRUPO, lat: geoPickLatLng.lat, lon: geoPickLatLng.lng, radio_m: radio,
  });
  if (error) { toast('No se pudo guardar: ' + error.message, 'err'); return; }
  toast('Geocerca creada', 'ok');
  $('geo-nombre').value = '';
  cancelGeoAdd();
  await loadGeocercas();
  refreshEtaPanel();
}
async function deleteGeo(id) {
  if (!confirm('¿Eliminar esta geocerca?')) return;
  const { error } = await sb.from('geocercas').delete().eq('id', id);
  if (error) { toast('No se pudo eliminar: ' + error.message, 'err'); return; }
  await loadGeocercas(); refreshEtaPanel(); toast('Geocerca eliminada', 'ok');
}
function renderGeoList() {
  const box = $('geo-list'); if (!box) return;
  if (!geoList.length) { box.innerHTML = '<div class="sp-empty">Aún no hay geocercas. Crea el <b>destino</b> con ➕ para calcular el ETA.</div>'; return; }
  box.innerHTML = geoList.map((g) => `<div class="geo-item">
      <span class="geo-dot" style="background:${_geoColor(g.tipo)}"></span>
      <div class="geo-item-txt"><strong>${esc(g.nombre)}</strong><small>${_geoTipoLbl(g.tipo)} · ${g.radio_m} m</small></div>
      <button class="icon-btn" data-geo-center="${g.id}" title="Centrar en el mapa">🎯</button>
      <button class="icon-btn" data-geo-del="${g.id}" title="Eliminar">🗑️</button>
    </div>`).join('');
}

// ---- Panel de seguimiento + ETA ----
function toggleEtaPanel() {
  const p = $('eta-panel'); if (!p) return;
  const show = p.hidden; p.hidden = !show;
  $('eta-fab')?.classList.toggle('on', show);
  if (show) {
    if ($('geo-panel') && !$('geo-panel').hidden) toggleGeoPanel(); // no solapar
    refreshEtaPanel();
    if (etaTimer) clearInterval(etaTimer);
    etaTimer = setInterval(refreshEtaPanel, 60000); // se refresca al ritmo del GPS
  } else if (etaTimer) { clearInterval(etaTimer); etaTimer = null; }
}
async function refreshEtaPanel() {
  const panel = $('eta-panel');
  if (!panel || panel.hidden || etaLoading) return; // no encimar consultas
  const list = $('eta-list');
  if (!list.children.length || list.querySelector('.sp-empty')) {
    list.innerHTML = '<div class="sp-empty">⏳ Consultando SONAR…</div>';
  }
  etaLoading = true;
  try {
    // Bajo demanda: pide a SONAR el próximo punto + hora de llegada (con caché ~2 min)
    const { data, error } = await sb.rpc('refrescar_eta_laureles', {});
    if (error) { list.innerHTML = `<div class="sp-empty">Error: ${esc(error.message)}</div>`; return; }
    renderEta(data || []);
  } finally { etaLoading = false; }
}
function _etaChip(est) {
  return est === 'en_ruta' ? '🟢 En ruta' : est === 'detenido' ? '🔴 Detenido'
    : est === 'sin_eta' ? '⚪ Sin ruta activa' : est;
}
// "2026-07-25 19:51:00" (UTC) → hora local de Colombia "14:51"
function _horaLocal(utcStr) {
  if (!utcStr) return '';
  const d = new Date(String(utcStr).replace(' ', 'T') + 'Z');
  if (isNaN(d)) return '';
  return d.toLocaleTimeString('es-CO', { timeZone: 'America/Bogota', hour: '2-digit', minute: '2-digit' });
}
function renderEta(rows) {
  $('eta-count').textContent = rows.length ? `${rows.length} bus(es)` : '';
  const hint = $('eta-hint');
  if (!rows.length) {
    $('eta-list').innerHTML = '<div class="sp-empty">No hay buses despachados con posición en este momento.</div>';
    hint.hidden = true; return;
  }
  const hayEta = rows.some((r) => r.eta_sonar_min != null);
  if (!hayEta) {
    hint.hidden = false;
    hint.innerHTML = 'ℹ️ SONAR no está reportando el próximo punto de estos buses en este momento.';
  } else hint.hidden = true;
  $('eta-list').innerHTML = rows.map((r) => {
    let eta;
    if (r.eta_sonar_min == null) eta = '<span class="eta-min muted">— sin ETA</span>';
    else if (r.eta_sonar_min <= 0) eta = '<span class="eta-min ok">🟢 llegando</span>';
    else eta = `<span class="eta-min">⏱ ${r.eta_sonar_min} min</span>`;
    const hLlega = _horaLocal(r.arrival_utc);
    const prox = r.next_point
      ? `→ ${esc(r.next_point)}${hLlega ? ' · llega ' + hLlega : ''}`
      : (r.estado === 'sin_eta' ? 'sin ruta activa en SONAR' : '');
    const rutaB = r.next_it || r.ruta || '';
    const vel = r.speed != null ? r.speed + ' km/h' : '';
    return `<div class="eta-item" data-eta-lat="${r.lat}" data-eta-lon="${r.lon}">
      <div class="eta-item-top"><strong>${esc(String(r.movil))}</strong> <small>${esc(r.placa || '')}</small>
        ${rutaB ? `<span class="eta-ruta">${esc(String(rutaB))}</span>` : ''}
        <span class="spacer"></span><span class="eta-chip est-${r.estado}">${_etaChip(r.estado)}</span></div>
      ${prox ? `<div class="eta-next">${prox}</div>` : ''}
      <div class="eta-item-bot">${eta} <small>${esc(vel)}</small></div>
    </div>`;
  }).join('');
}

// ---- Cableado de eventos (una sola vez) ----
$('eta-fab')?.addEventListener('click', (e) => { e.preventDefault(); toggleEtaPanel(); });
$('eta-close')?.addEventListener('click', () => toggleEtaPanel());
$('eta-refresh')?.addEventListener('click', () => refreshEtaPanel());
$('eta-list')?.addEventListener('click', (e) => {
  const it = e.target.closest('[data-eta-lat]'); if (!it) return;
  const lat = parseFloat(it.dataset.etaLat), lon = parseFloat(it.dataset.etaLon);
  if (flotaMap && !isNaN(lat)) flotaMap.flyTo([lat, lon], Math.max(flotaMap.getZoom(), 16), { duration: 0.6 });
});
$('geo-fab')?.addEventListener('click', (e) => { e.preventDefault(); toggleGeoPanel(); });
$('geo-close')?.addEventListener('click', () => toggleGeoPanel());
$('geo-add-btn')?.addEventListener('click', () => startGeoAdd());
$('geo-save')?.addEventListener('click', () => saveGeoNew());
$('geo-cancel')?.addEventListener('click', () => cancelGeoAdd());
$('geo-list')?.addEventListener('click', (e) => {
  const del = e.target.closest('[data-geo-del]');
  if (del) { deleteGeo(Number(del.dataset.geoDel)); return; }
  const cen = e.target.closest('[data-geo-center]');
  if (cen) {
    const g = geoList.find((x) => x.id === Number(cen.dataset.geoCenter));
    if (g && flotaMap) flotaMap.flyTo([g.lat, g.lon], 15, { duration: 0.6 });
  }
});

async function showMapView() {
  if (typeof L === 'undefined') { toast('No se pudo cargar el mapa (revisa tu conexión a internet)', 'err'); return; }
  if (mapaFlotante) cerrarMapaFlotante(); // si estaba flotante, devolver el mapa a su lugar
  currentView = 'mapa';
  cerrarRecorridoBus();
  document.getElementById('app').classList.add('view-map');
  cerrarPanelesFlotantes();
  $('cump-view').hidden = true;
  $('rutas-view').hidden = true;
  $('malla-view').hidden = true;
  $('laureles-view').hidden = true; $('oriental-view').hidden = true; $('interv-view').hidden = true; $('disc-view').hidden = true;
  $('integradas-view').hidden = true;
  $('frecuencia-view').hidden = true;
  $('productividad-view').hidden = true;
  $('jornada-view').hidden = true;
  $('pasajeros-view').hidden = true; $('usuarios-view').hidden = true; $('top-view').hidden = true; $('perfilstats-view').hidden = true; $('preventivas-view').hidden = true;
  if (_rutasTimer) { clearInterval(_rutasTimer); _rutasTimer = null; }
  $('table-view').hidden = true;
  ocultarVistas('map-view');
  $('map-view').hidden = false;
  closeVehSheet();
  limpiarRecorrido(); // entra al mapa sin recorrido previo dibujado
  // resaltar la opción del menú
  document.querySelectorAll('#sidebar button').forEach((b) => b.classList.remove('active'));
  $('nav-mapa')?.classList.add('active');
  buildBottomNav(); // quita el resaltado de la barra inferior (el mapa no está allí)
  ensureFlotaMap();
  syncMapFabs(); // muestra 🛰️/📍 según el rol (admin/auditor)
  syncPuestosFiltro(); // filtro por puesto(s): solo admin
  syncRutasPanel(); // panel "🛣️ Rutas": dibuja los recorridos KMZ elegidos
  setTimeout(() => flotaMap.invalidateSize(), 120); // el contenedor estaba oculto
  await refreshMapa(true);
  if (mapTimer) clearInterval(mapTimer);
  mapTimer = setInterval(() => refreshMapa(false), 60000); // refresco automático cada 60s
}
// ----- Mapa flotante: mueve TODO el #map-view a una ventana arrastrable -----
async function abrirMapaFlotante() {
  if (typeof L === 'undefined') { toast('No se pudo cargar el mapa (revisa tu conexión a internet)', 'err'); return; }
  const mv = $('map-view');
  if (!mapViewHome) mapViewHome = { parent: mv.parentNode, next: mv.nextSibling };
  document.getElementById('app').classList.remove('view-map');
  if (currentView === 'mapa') { currentView = 'tabla'; $('table-view').hidden = false; buildBottomNav(); }
  $('map-float-body').appendChild(mv);
  mv.hidden = false;
  $('map-float').hidden = false;
  $('map-fab').classList.add('activo');
  mapaFlotante = true;
  ensureFlotaMap();
  syncMapFabs(); // muestra 🛰️/📍 según el rol también en modo flotante
  setTimeout(() => flotaMap.invalidateSize(), 150);
  await refreshMapa(true);
  if (floatTimer) clearInterval(floatTimer);
  floatTimer = setInterval(() => { if (mapaFlotante) refreshMapa(false); }, 60000);
}
function cerrarMapaFlotante() {
  const mv = $('map-view');
  if (mapViewHome) mapViewHome.parent.insertBefore(mv, mapViewHome.next); // devolver a su lugar
  mv.hidden = true;
  $('map-float').hidden = true;
  $('map-fab').classList.remove('activo');
  mapaFlotante = false;
  if (floatTimer) { clearInterval(floatTimer); floatTimer = null; }
}
function toggleMapaFlotante() { mapaFlotante ? cerrarMapaFlotante() : abrirMapaFlotante(); }
$('map-fab')?.addEventListener('click', toggleMapaFlotante);
